#[derive(Clone, Serialize, Deserialize)]
pub struct HostConfig {
    pub server: String,
    pub host_id: Uuid,
    pub host_token: String,
    pub relay_public_key: String,
    pub revocation_epoch: u64,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub direct_listener: Option<DirectListenerConfig>,
    pub name: String,
    pub roots: Vec<PathBuf>,
    /// The security boundary this host was enrolled to provide. Older host
    /// configs default to trusted-user execution and therefore cannot satisfy
    /// the Web hosted-isolation gate.
    #[serde(default)]
    pub execution_profile: HostExecutionProfile,
    #[serde(default)]
    pub resource_limits: HostResourceLimits,
}

/// Marker written by the generated systemd unit for an isolated host.
///
/// The marker is deliberately paired with process-level checks below. An
/// arbitrary environment variable is not an isolation boundary; the server's
/// isolated-host allowlist and the service manager's sandbox are the authority.
#[cfg(target_os = "linux")]
const SYSTEMD_ISOLATION_ATTESTATION: &str = "systemd-user-sandbox-v1";
#[cfg(target_os = "linux")]
const ISOLATION_ATTESTATION_ENV: &str = "BORG_HOST_ISOLATION_ATTESTATION";
const PROVIDER_AUTH_JSON_MAX_BYTES: u64 = 1024 * 1024;
const REMOTE_RETRY_INITIAL: Duration = Duration::from_secs(2);
const REMOTE_RETRY_MAX: Duration = Duration::from_secs(60);
const REMOTE_RETRY_AFTER_MAX: Duration = Duration::from_secs(300);
const HOST_HEARTBEAT_INTERVAL: Duration = Duration::from_secs(15);
const HOST_HEARTBEAT_RETRY_MAX: Duration = Duration::from_secs(30);
const SYSTEMD_NOTIFY_TIMEOUT: Duration = Duration::from_secs(5);

#[derive(Default)]
struct RemoteRetryBackoff {
    failures: u32,
}

impl RemoteRetryBackoff {
    fn next_delay(&mut self, retry_after: Option<Duration>) -> Duration {
        let multiplier = 1_u32 << self.failures.min(5);
        self.failures = self.failures.saturating_add(1);
        REMOTE_RETRY_INITIAL
            .saturating_mul(multiplier)
            .min(REMOTE_RETRY_MAX)
            .max(retry_after.unwrap_or_default().min(REMOTE_RETRY_AFTER_MAX))
    }

    fn reset(&mut self) {
        self.failures = 0;
    }
}

type ProviderCapabilitiesCache = HashMap<bool, (Instant, Vec<ProviderCapability>)>;
static PROVIDER_CAPABILITIES_CACHE: OnceLock<Mutex<ProviderCapabilitiesCache>> = OnceLock::new();
impl HostConfig {
    fn validate(&self) -> Result<()> {
        validate_server_url(&self.server)?;
        ensure!(
            !self.host_token.trim().is_empty(),
            "remote host token is empty"
        );
        ensure!(!self.name.trim().is_empty(), "remote host name is empty");
        self.resource_limits.validate()?;
        Ok(())
    }
}

/// Require an independently enforced boundary before an enrolled host can
/// claim the hosted-isolation profile. The normal user service generated by
/// `borg remote install` supplies the attestation and systemd supplies
/// `NoNewPrivileges`; the server still decides which host IDs may serve
/// isolated tenants.
fn ensure_execution_boundary(config: &HostConfig) -> Result<()> {
    if config.execution_profile != HostExecutionProfile::IsolatedHosted {
        return Ok(());
    }

    #[cfg(target_os = "linux")]
    {
        ensure!(
            std::env::var(ISOLATION_ATTESTATION_ENV).ok().as_deref()
                == Some(SYSTEMD_ISOLATION_ATTESTATION),
            "isolated hosted execution requires the hardened systemd host service; run `borg remote install` and start borg-remote.service"
        );
        ensure!(
            linux_process_has_no_new_privileges(),
            "isolated hosted execution requires NoNewPrivileges from the service manager"
        );
        ensure!(
            linux_process_belongs_to_generated_service(),
            "isolated hosted execution requires the generated borg-remote.service cgroup"
        );
        Ok(())
    }

    #[cfg(not(target_os = "linux"))]
    {
        let _ = config;
        bail!(
            "isolated hosted execution is currently supported only by the hardened Linux systemd host"
        );
    }
}

#[cfg(target_os = "linux")]
fn linux_process_has_no_new_privileges() -> bool {
    fs::read_to_string("/proc/self/status")
        .ok()
        .and_then(|status| {
            status
                .lines()
                .find_map(|line| line.strip_prefix("NoNewPrivs:")?.trim().parse::<u8>().ok())
        })
        == Some(1)
}

#[cfg(target_os = "linux")]
fn linux_process_belongs_to_generated_service() -> bool {
    fs::read_to_string("/proc/self/cgroup")
        .ok()
        .is_some_and(|cgroup| {
            cgroup
                .lines()
                .any(|line| line.contains("borg-remote.service"))
        })
}

#[derive(Serialize)]
