struct EnrollResponse {
    host: RemoteHost,
    host_token: String,
    relay_public_key: String,
    revocation_epoch: u64,
}

#[derive(Deserialize)]
struct RelayWorkspaceRoster {
    participants: Vec<RelayWorkspaceParticipant>,
}

#[derive(Deserialize)]
struct RelayInbox {
    messages: Vec<RelayInboxMessage>,
}

#[derive(Deserialize)]
struct RelayInboxMessage {
    id: Uuid,
    workspace_id: Uuid,
    author_id: Uuid,
    author_name: String,
    text: String,
    thread_id: Option<Uuid>,
    reply_to_message_id: Option<Uuid>,
    created_at: DateTime<Utc>,
    delivery_mode: crate::DeliveryMode,
    /// References only; the bytes are fetched separately and verified before
    /// the message is admitted. A relay that predates images omits the field.
    #[serde(default)]
    attachments: Vec<crate::MessageAttachment>,
}

#[derive(Deserialize)]
struct RelayInstanceDirectory {
    participants: Vec<RelayInstanceParticipant>,
}

#[derive(Deserialize)]
struct RelayInstanceParticipant {
    id: Uuid,
    kind: ParticipantKind,
    display_name: String,
    created_at: DateTime<Utc>,
    host_id: Option<Uuid>,
    workspace_id: Option<Uuid>,
    /// Where the owning host says this instance runs. It is the only identity a
    /// peer on another machine offers, since that host's pid means nothing
    /// here, and several sessions in one workspace are otherwise
    /// indistinguishable.
    #[serde(default)]
    cwd: Option<String>,
    /// The owning host's lifecycle state: `running`, `ready`, `starting`, or
    /// `stopped`. `stopped` is what retires a dead peer from the default
    /// listing.
    #[serde(default)]
    status: Option<String>,
}

#[derive(Deserialize)]
struct RelayWorkspaceParticipant {
    id: Uuid,
    kind: ParticipantKind,
    role: WorkspaceRole,
    display_name: String,
    created_at: DateTime<Utc>,
}

