/// True when the stored launch was registered by a local terminal owner, so
/// the session is still locally owned and may be resumed or attached.
pub fn host_launch_is_local_mirror(metadata: &serde_json::Value) -> bool {
    metadata
        .get("local_mirror")
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false)
}

pub async fn enroll_host(
    server: &str,
    token: &str,
    name: Option<&str>,
    roots: Vec<PathBuf>,
    config_path: &Path,
) -> Result<HostConfig> {
    let server = validate_server_url(server)?;
    ensure!(!token.trim().is_empty(), "host enrollment token is empty");
    let roots = canonical_roots(roots)?;
    let name = name
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .unwrap_or_else(hostname);
    let execution_profile = configured_execution_profile()?;
    let resource_limits = configured_resource_limits();
    let capabilities = probe_capabilities_with_profile(roots.clone(), execution_profile).await;
    let response = Client::new()
        .post(endpoint(&server, "/api/remote/hosts/enroll"))
        .json(&EnrollRequest {
            token: token.to_string(),
            name: name.clone(),
            hostname: hostname(),
            platform: platform(),
            capabilities,
        })
        .send()
        .await
        .context("failed to contact Borg for host enrollment")?;
    if !response.status().is_success() {
        bail!(
            "host enrollment failed with {}: {}",
            response.status(),
            response.text().await.unwrap_or_default()
        );
    }
    let enrolled: EnrollResponse = response
        .json()
        .await
        .context("Borg returned an invalid host enrollment response")?;
    let _issuer = crate::admission::issuer_key(&enrolled.relay_public_key)?;
    let config = HostConfig {
        server,
        host_id: enrolled.host.id,
        host_token: enrolled.host_token,
        relay_public_key: enrolled.relay_public_key,
        revocation_epoch: enrolled.revocation_epoch,
        direct_listener: None,
        name,
        roots,
        execution_profile,
        resource_limits,
    };
    config.validate()?;
    write_config(config_path, &config)?;
    Ok(config)
}

pub async fn probe_capabilities(roots: Vec<PathBuf>) -> HostCapabilities {
    match configured_execution_profile() {
        Ok(profile) => probe_capabilities_with_profile(roots, profile).await,
        Err(error) => {
            tracing::error!(%error, "host execution disabled");
            let mut capabilities =
                probe_capabilities_with_profile(roots, HostExecutionProfile::IsolatedHosted).await;
            capabilities.can_launch = false;
            capabilities
        }
    }
}

async fn probe_capabilities_with_profile(
    roots: Vec<PathBuf>,
    execution_profile: HostExecutionProfile,
) -> HostCapabilities {
    let providers = probe_provider_capabilities_with_managed_kimi(true).await;
    HostCapabilities {
        protocol_version: REMOTE_PROTOCOL_VERSION,
        providers,
        roots,
        can_launch: true,
        can_run_shell_commands: true,
        can_open_terminal: terminal_emulator().is_some(),
        execution_profile,
        resource_limits: configured_resource_limits(),
        workspace_attachment: Some(workspace_attachment_capabilities()),
    }
}

fn configured_resource_limits() -> HostResourceLimits {
    // Keep the first hosted policy intentionally conservative and local. A
    // future control plane can negotiate lower ceilings, but it must never
    // increase what the host has declared here. Values are persisted in the
    // host config at enrollment so a later environment change cannot silently
    // widen an existing host's budget.
    let defaults = HostResourceLimits::default();
    HostResourceLimits {
        max_session_seconds: bounded_limit_env(
            "BORG_HOST_MAX_SESSION_SECONDS",
            defaults.max_session_seconds,
            1,
            7 * 24 * 60 * 60,
        ),
        max_runtime_execution_ms: bounded_limit_env(
            "BORG_HOST_MAX_RUNTIME_EXECUTION_MS",
            defaults.max_runtime_execution_ms,
            1,
            defaults.max_runtime_execution_ms,
        ),
        max_workspace_command_timeout_ms: bounded_limit_env(
            "BORG_HOST_MAX_COMMAND_TIMEOUT_MS",
            defaults.max_workspace_command_timeout_ms,
            1,
            defaults.max_workspace_command_timeout_ms,
        ),
        max_workspace_command_output_bytes: bounded_limit_env(
            "BORG_HOST_MAX_COMMAND_OUTPUT_BYTES",
            defaults.max_workspace_command_output_bytes,
            1,
            defaults.max_workspace_command_output_bytes,
        ),
        max_file_transfer_bytes: bounded_limit_env(
            "BORG_HOST_MAX_FILE_TRANSFER_BYTES",
            defaults.max_file_transfer_bytes,
            1,
            defaults.max_file_transfer_bytes,
        ),
        max_concurrent_sessions: bounded_limit_env(
            "BORG_HOST_MAX_CONCURRENT_SESSIONS",
            u64::from(defaults.max_concurrent_sessions),
            1,
            u64::from(defaults.max_concurrent_sessions),
        ) as u32,
        max_memory_bytes: bounded_limit_env(
            "BORG_HOST_MAX_MEMORY_BYTES",
            defaults.max_memory_bytes,
            128 * 1024 * 1024,
            64 * 1024 * 1024 * 1024,
        ),
        max_cpu_percent: bounded_limit_env(
            "BORG_HOST_MAX_CPU_PERCENT",
            u64::from(defaults.max_cpu_percent),
            1,
            1_600,
        ) as u32,
        max_processes: bounded_limit_env(
            "BORG_HOST_MAX_PROCESSES",
            u64::from(defaults.max_processes),
            16,
            4_096,
        ) as u32,
    }
}

fn bounded_limit_env(name: &str, default: u64, min: u64, max: u64) -> u64 {
    let Some(raw) = std::env::var_os(name) else {
        return default;
    };
    let raw = raw.to_string_lossy();
    match raw.trim().parse::<u64>() {
        Ok(value) => value.clamp(min, max),
        Err(error) => {
            tracing::warn!(name, value = %raw, %error, "invalid host resource limit; using default");
            default
        }
    }
}

fn configured_execution_profile() -> Result<HostExecutionProfile> {
    Ok(
        match std::env::var("BORG_HOST_EXECUTION_PROFILE")
            .ok()
            .map(|value| value.trim().to_ascii_lowercase())
            .as_deref()
        {
            Some("isolated_hosted" | "isolated" | "hosted") => HostExecutionProfile::IsolatedHosted,
            Some("trusted_user" | "trusted" | "local") | None => HostExecutionProfile::TrustedUser,
            Some(value) => bail!("invalid BORG_HOST_EXECUTION_PROFILE: {value}"),
        },
    )
}

/// Probe every provider lane concurrently and return only secret-free
/// admission metadata. This is used at local launch and again at an enrolled
/// host boundary; a controller-supplied snapshot is never trusted.
pub async fn probe_provider_capabilities() -> Vec<ProviderCapability> {
    probe_provider_capabilities_with_managed_kimi(false).await
}

/// Build the provider admission snapshot from local executable and credential
/// metadata without starting every provider CLI. Detailed host/status probes
/// continue to validate commands and report versions.
pub async fn probe_provider_admission_capabilities() -> Vec<ProviderCapability> {
    probe_provider_admission_capabilities_with_managed_kimi(false).await
}

async fn probe_provider_admission_capabilities_with_managed_kimi(
    managed_kimi: bool,
) -> Vec<ProviderCapability> {
    probe_provider_capabilities_uncached(managed_kimi, ProviderProbeMode::Admission).await
}

async fn probe_provider_capabilities_with_managed_kimi(
    managed_kimi: bool,
) -> Vec<ProviderCapability> {
    let cache = PROVIDER_CAPABILITIES_CACHE.get_or_init(|| Mutex::new(HashMap::new()));
    let mut cache = cache.lock().await;
    if let Some((probed_at, providers)) = cache.get(&managed_kimi)
        && probed_at.elapsed() < crate::provider_usage::PROVIDER_CAPABILITIES_CACHE_TTL
    {
        return providers.clone();
    }

    let providers =
        probe_provider_capabilities_uncached(managed_kimi, ProviderProbeMode::Detailed).await;
    cache.insert(managed_kimi, (Instant::now(), providers.clone()));
    providers
}

#[derive(Clone, Copy)]
enum ProviderProbeMode {
    Admission,
    Detailed,
}

async fn probe_provider_capabilities_uncached(
    managed_kimi: bool,
    mode: ProviderProbeMode,
) -> Vec<ProviderCapability> {
    let (codex, claude, opencode, kimi, openrouter, compatible, muse) = tokio::join!(
        probe_provider(CodingProvider::Codex, managed_kimi, mode),
        probe_provider(CodingProvider::Claude, managed_kimi, mode),
        probe_provider(CodingProvider::OpenCode, managed_kimi, mode),
        probe_provider(CodingProvider::Kimi, managed_kimi, mode),
        probe_provider(CodingProvider::OpenRouter, managed_kimi, mode),
        probe_provider(CodingProvider::OpenAiCompatible, managed_kimi, mode),
        probe_provider(CodingProvider::Muse, managed_kimi, mode),
    );
    let capabilities = vec![codex, claude, opencode, kimi, openrouter, compatible, muse];
    match mode {
        // Launch only needs locally available authentication routes. Starting
        // provider subprocesses to refresh subscription usage blocks first
        // paint for up to ten seconds and is unnecessary until a caller asks
        // for a fresh capability snapshot or attempts cross-provider work.
        ProviderProbeMode::Admission => capabilities,
        ProviderProbeMode::Detailed => {
            crate::provider_usage::refresh_provider_capability_usage(&capabilities).await
        }
    }
}

fn workspace_attachment_capabilities() -> crate::WorkspaceAttachmentCapabilities {
    crate::WorkspaceAttachmentCapabilities {
        presence_leases: true,
        approval_provenance: true,
        reconnect_sync_cursors: true,
        participant_scoped_command_authority: true,
    }
}

async fn probe_provider(
    provider: CodingProvider,
    managed_kimi: bool,
    mode: ProviderProbeMode,
) -> ProviderCapability {
    let native_go = provider == CodingProvider::OpenCode
        && borg_provider::credentials::opencode_go_api_key().is_some();
    let (version, subscription_authenticated) = if native_go {
        (None, true)
    } else if provider == CodingProvider::Muse {
        // The official launcher can download or prompt even for --version.
        // Capability discovery must not start it or imply a paid entitlement.
        (None, muse_stored_credentials_present())
    } else if provider == CodingProvider::Claude {
        (
            None,
            borg_provider::provider::read_claude_subscription_status()
                .await
                .unwrap_or(false),
        )
    } else if provider == CodingProvider::Codex {
        (
            None,
            borg_provider::openai_subscription::account()
                .ok()
                .flatten()
                .is_some(),
        )
    } else {
        match mode {
            ProviderProbeMode::Detailed => {
                let (version, auth_status) = tokio::join!(
                    async {
                        command_output(provider.executable(), &["--version"])
                            .await
                            .ok()
                            .filter(|value| !value.is_empty())
                    },
                    async {
                        match provider {
                            CodingProvider::Codex
                            | CodingProvider::Claude
                            | CodingProvider::OpenCode
                            | CodingProvider::Grok
                            | CodingProvider::Muse => provider_auth_status(provider).await.ok(),
                            CodingProvider::Anthropic
                            | CodingProvider::Kimi
                            | CodingProvider::Glm
                            | CodingProvider::Qwen
                            | CodingProvider::OpenRouter
                            | CodingProvider::Vercel
                            | CodingProvider::OpenAiCompatible => None,
                        }
                    }
                );
                let authenticated = match provider {
                    CodingProvider::Codex => auth_status
                        .as_deref()
                        .is_some_and(codex_auth_status_authenticated),
                    CodingProvider::Claude => auth_status
                        .as_deref()
                        .is_some_and(claude_auth_status_authenticated),
                    CodingProvider::OpenCode => auth_status
                        .as_deref()
                        .is_some_and(opencode_auth_status_authenticated),
                    // Grok Build and Muse Code keep their subscription session
                    // in their own credential file; presence of that session or
                    // an API key is the signal.
                    CodingProvider::Grok => grok_credentials_present(),
                    CodingProvider::Muse => muse_credentials_present(),
                    CodingProvider::Anthropic
                    | CodingProvider::Kimi
                    | CodingProvider::Glm
                    | CodingProvider::Qwen
                    | CodingProvider::OpenRouter
                    | CodingProvider::Vercel
                    | CodingProvider::OpenAiCompatible => false,
                };
                (version, authenticated)
            }
            ProviderProbeMode::Admission => {
                let authenticated = if provider == CodingProvider::Codex {
                    borg_provider::provider::read_codex_subscription_status()
                        .await
                        .unwrap_or(false)
                } else {
                    provider_subscription_credentials_present(provider)
                };
                #[cfg(target_os = "macos")]
                let authenticated = if provider == CodingProvider::Claude && !authenticated {
                    provider_auth_status(provider)
                        .await
                        .ok()
                        .as_deref()
                        .is_some_and(claude_auth_status_authenticated)
                } else {
                    authenticated
                };
                (None, authenticated)
            }
        }
    };
    let mut auth_methods = Vec::new();
    let mut detail = Vec::new();
    // `billing` follows the precedence the provider adapter applies when it
    // actually runs a turn, not the order the methods are listed in: the
    // Codex and Claude CLIs give an explicit API-key environment variable
    // precedence over their OAuth session.
    let billing = match provider {
        CodingProvider::Codex => {
            if subscription_authenticated {
                auth_methods.push(ProviderAuthMethod::Subscription);
                detail.push("Native ChatGPT subscription authenticated");
            }
            let api_key = borg_provider::credentials::openai_api_key().is_some();
            if api_key {
                auth_methods.push(ProviderAuthMethod::ApiKey);
                detail.push("OpenAI API key configured");
            }
            if borg_provider::credentials::openai_uses_api_key() {
                Some(BillingLane::ApiKey)
            } else if subscription_authenticated {
                Some(BillingLane::Subscription)
            } else {
                None
            }
        }
        CodingProvider::Claude => {
            if subscription_authenticated {
                auth_methods.push(ProviderAuthMethod::Subscription);
                detail.push("Claude subscription authenticated");
            }
            let api_key = borg_provider::credentials::api_key(
                borg_provider::credentials::ApiKeyCredential::Anthropic,
            )
            .is_some();
            if api_key {
                auth_methods.push(ProviderAuthMethod::ApiKey);
                detail.push("Anthropic API key configured");
            }
            let env_api_key = nonempty_env("ANTHROPIC_API_KEY").is_some()
                || nonempty_env("ANTHROPIC_AUTH_TOKEN").is_some();
            if env_api_key {
                Some(BillingLane::ApiKey)
            } else if subscription_authenticated {
                Some(BillingLane::Subscription)
            } else if api_key {
                Some(BillingLane::ApiKey)
            } else {
                None
            }
        }
        CodingProvider::OpenCode => {
            if subscription_authenticated
                || borg_provider::credentials::opencode_go_api_key().is_some()
            {
                auth_methods.push(ProviderAuthMethod::Subscription);
                detail.push(if native_go {
                    "OpenCode Go native subscription available; other routes require OpenCode"
                } else {
                    "OpenCode provider credentials available"
                });
            }
            (!auth_methods.is_empty()).then_some(BillingLane::Subscription)
        }
        CodingProvider::Grok => {
            if subscription_authenticated {
                auth_methods.push(ProviderAuthMethod::Subscription);
                detail.push("Grok Build subscription authenticated");
                Some(BillingLane::Subscription)
            } else if nonempty_env("XAI_API_KEY").is_some() {
                auth_methods.push(ProviderAuthMethod::ApiKey);
                detail.push("xAI API key configured");
                Some(BillingLane::ApiKey)
            } else {
                None
            }
        }
        CodingProvider::Muse => {
            if nonempty_env("META_API_KEY").is_some() {
                auth_methods.push(ProviderAuthMethod::ApiKey);
                detail.push("META_API_KEY overrides Muse Code account login (pay-as-you-go)");
                Some(BillingLane::ApiKey)
            } else if subscription_authenticated {
                auth_methods.push(ProviderAuthMethod::ApiKey);
                detail.push("Muse Code managed credential available; subscription entitlement and billing are determined by Muse Code");
                None
            } else {
                None
            }
        }
        CodingProvider::Kimi => {
            if managed_kimi {
                auth_methods.push(ProviderAuthMethod::Endpoint);
                detail.push("Borg gateway credentials available");
                Some(BillingLane::Endpoint)
            } else if nonempty_env("BORG_KIMI_API_KEY").is_some()
                || nonempty_env("MOONSHOT_API_KEY").is_some()
            {
                auth_methods.push(ProviderAuthMethod::ApiKey);
                detail.push("Kimi API key configured");
                Some(BillingLane::ApiKey)
            } else {
                None
            }
        }
        CodingProvider::Glm => {
            // A selected GLM Coding Plan supplies its own key; a pay-as-you-go
            // key is the fallback, exactly as for Kimi.
            if borg_provider::subscription::active_for(borg_provider::Plan::GlmCoding)
                .and_then(|plan| plan.api_key())
                .is_some()
            {
                auth_methods.push(ProviderAuthMethod::Subscription);
                detail.push("GLM Coding Plan key configured");
                Some(BillingLane::Subscription)
            } else if nonempty_env("BORG_GLM_API_KEY").is_some() {
                auth_methods.push(ProviderAuthMethod::ApiKey);
                detail.push("GLM API key configured");
                Some(BillingLane::ApiKey)
            } else {
                None
            }
        }
        CodingProvider::Qwen => {
            // A selected Qwen Coding Plan supplies its own `sk-sp-` key; a
            // pay-as-you-go DashScope key is the fallback.
            if borg_provider::subscription::active_for(borg_provider::Plan::QwenCoding)
                .and_then(|plan| plan.api_key())
                .is_some()
            {
                auth_methods.push(ProviderAuthMethod::Subscription);
                detail.push("Qwen Coding Plan key configured");
                Some(BillingLane::Subscription)
            } else if nonempty_env("BORG_QWEN_API_KEY").is_some()
                || nonempty_env("DASHSCOPE_API_KEY").is_some()
            {
                auth_methods.push(ProviderAuthMethod::ApiKey);
                detail.push("Qwen API key configured");
                Some(BillingLane::ApiKey)
            } else {
                None
            }
        }
        CodingProvider::OpenRouter => {
            if borg_provider::credentials::api_key(
                borg_provider::credentials::ApiKeyCredential::OpenRouter,
            )
            .is_some()
            {
                auth_methods.push(ProviderAuthMethod::ApiKey);
                detail.push("OpenRouter API key configured");
                Some(BillingLane::ApiKey)
            } else {
                None
            }
        }
        CodingProvider::Vercel => {
            if borg_provider::credentials::api_key(
                borg_provider::credentials::ApiKeyCredential::Vercel,
            )
            .is_some()
            {
                auth_methods.push(ProviderAuthMethod::ApiKey);
                detail.push("Vercel AI Gateway key configured");
                Some(BillingLane::ApiKey)
            } else {
                None
            }
        }
        CodingProvider::Anthropic => {
            // This lane is API-key only. It never reports a subscription lane,
            // because it has no way to spend one.
            if borg_provider::credentials::api_key(
                borg_provider::credentials::ApiKeyCredential::Anthropic,
            )
            .is_some()
            {
                auth_methods.push(ProviderAuthMethod::ApiKey);
                detail.push("Anthropic API key configured");
                Some(BillingLane::ApiKey)
            } else {
                None
            }
        }
        CodingProvider::OpenAiCompatible => {
            // The native generic route deliberately has a localhost default,
            // but it is only an advertised lane after the caller configured an
            // endpoint or model (the local-server bootstrap does that before
            // probing). A local endpoint does not require a bearer key.
            let endpoint_configured = nonempty_env("BORG_OPENAI_COMPATIBLE_BASE_URL").is_some()
                || nonempty_env("BORG_OPENAI_COMPATIBLE_MODEL").is_some();
            if endpoint_configured {
                auth_methods.push(ProviderAuthMethod::Endpoint);
                detail.push("OpenAI-compatible endpoint configured");
                if nonempty_env("BORG_OPENAI_COMPATIBLE_API_KEY")
                    .or_else(|| nonempty_env("BORG_OPENAI_API_KEY"))
                    .or_else(|| nonempty_env("OPENAI_API_KEY"))
                    .is_some()
                {
                    auth_methods.push(ProviderAuthMethod::ApiKey);
                    detail.push("endpoint API key configured");
                }
                Some(BillingLane::Endpoint)
            } else {
                None
            }
        }
    };
    let authenticated = if provider == CodingProvider::Codex {
        match billing {
            Some(BillingLane::Subscription) => subscription_authenticated,
            Some(BillingLane::ApiKey) => auth_methods.contains(&ProviderAuthMethod::ApiKey),
            _ => false,
        }
    } else {
        !auth_methods.is_empty()
    };
    let installed = match provider {
        CodingProvider::Muse => {
            borg_provider::provider_bin::resolve_uncached(borg_provider::Runtime::Muse)
                .await
                .is_ok()
        }
        // These routes execute in Borg's native harness; they do not depend
        // on a separately installed `borg` executable being discoverable in a
        // service user's PATH.
        CodingProvider::Codex
        | CodingProvider::Claude
        | CodingProvider::Anthropic
        | CodingProvider::Kimi
        | CodingProvider::Glm
        | CodingProvider::Qwen
        | CodingProvider::OpenRouter
        | CodingProvider::Vercel
        | CodingProvider::OpenAiCompatible => true,
        CodingProvider::OpenCode if native_go => true,
        CodingProvider::OpenCode | CodingProvider::Grok => match mode {
            ProviderProbeMode::Admission => {
                executable_in_path(Path::new(provider.executable())).is_some()
            }
            ProviderProbeMode::Detailed => version.is_some(),
        },
    };
    let can_spawn = installed && authenticated;
    ProviderCapability {
        provider,
        installed,
        version,
        authenticated,
        auth_detail: (!detail.is_empty()).then(|| detail.join("; ")),
        auth_methods,
        can_spawn,
        usage: None,
        billing,
    }
}

pub fn provider_subscription_credentials_present(provider: CodingProvider) -> bool {
    match provider {
        CodingProvider::Codex => borg_provider::openai_subscription::account()
            .ok()
            .flatten()
            .is_some(),
        CodingProvider::Claude => {
            nonempty_env("CLAUDE_CODE_OAUTH_TOKEN").is_some()
                || claude_credentials_path()
                    .and_then(|path| read_bounded_auth_json(&path))
                    .as_ref()
                    .is_some_and(claude_auth_json_authenticated)
                || claude_keychain_credentials_present()
        }
        CodingProvider::OpenCode => opencode_auth_json()
            .as_ref()
            .is_some_and(opencode_auth_json_authenticated),
        CodingProvider::Grok => grok_credentials_present(),
        CodingProvider::Muse => muse_stored_credentials_present(),
        CodingProvider::Anthropic
        | CodingProvider::Kimi
        | CodingProvider::Glm
        | CodingProvider::Qwen
        | CodingProvider::OpenRouter
        | CodingProvider::Vercel
        | CodingProvider::OpenAiCompatible => false,
    }
}

/// Grok Build caches its subscription session in `~/.grok/auth.json`; an
/// `XAI_API_KEY` is the pay-as-you-go alternative.
fn grok_credentials_present() -> bool {
    nonempty_env("XAI_API_KEY").is_some()
        || std::env::var_os("HOME")
            .filter(|home| !home.is_empty())
            .map(|home| PathBuf::from(home).join(".grok").join("auth.json"))
            .is_some_and(|path| path.is_file())
}

/// Muse Code uses its XDG configuration auth file, not the installation directory.
fn muse_credentials_present() -> bool {
    nonempty_env("META_API_KEY").is_some() || muse_stored_credentials_present()
}

fn muse_stored_credentials_present() -> bool {
    let root = std::env::var_os("XDG_CONFIG_HOME")
        .filter(|root| !root.is_empty())
        .map(PathBuf::from)
        .or_else(|| {
            std::env::var_os("HOME")
                .filter(|home| !home.is_empty())
                .map(|home| PathBuf::from(home).join(".config"))
        });
    root.and_then(|root| read_bounded_auth_json(&root.join("muse/auth.json")))
        .as_ref()
        .is_some_and(muse_auth_json_authenticated)
}

fn muse_auth_json_authenticated(value: &serde_json::Value) -> bool {
    value
        .pointer("/providers/meta/api_key")
        .and_then(serde_json::Value::as_str)
        .is_some_and(|key| !key.trim().is_empty())
}

/// On macOS the Claude CLI keeps its OAuth session in the login Keychain and
/// writes no credentials file, so a file-only check reports every fresh Borg
/// instance as signed out. Probe the item's existence without reading it.
#[cfg(target_os = "macos")]
fn claude_keychain_credentials_present() -> bool {
    std::process::Command::new("/usr/bin/security")
        .args(["find-generic-password", "-s", "Claude Code-credentials"])
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .is_ok_and(|status| status.success())
}

#[cfg(not(target_os = "macos"))]
fn claude_keychain_credentials_present() -> bool {
    false
}

fn claude_credentials_path() -> Option<PathBuf> {
    nonempty_path_env("CLAUDE_SECURESTORAGE_CONFIG_DIR")
        .or_else(|| nonempty_path_env("CLAUDE_CONFIG_DIR"))
        .map(|directory| directory.join(".credentials.json"))
        .or_else(|| {
            nonempty_path_env("HOME")
                .or({
                    #[cfg(windows)]
                    {
                        nonempty_path_env("USERPROFILE")
                    }
                    #[cfg(not(windows))]
                    {
                        None
                    }
                })
                .map(|home| home.join(".claude").join(".credentials.json"))
        })
}

fn opencode_auth_json() -> Option<serde_json::Value> {
    if let Ok(contents) = std::env::var("OPENCODE_AUTH_CONTENT")
        && let Some(value) = parse_bounded_auth_json(contents.as_bytes())
    {
        return Some(value);
    }
    let data_home = nonempty_path_env("XDG_DATA_HOME")
        .or_else(|| nonempty_path_env("HOME").map(|home| home.join(".local").join("share")))?;
    read_bounded_auth_json(&data_home.join("opencode").join("auth.json"))
}

fn nonempty_path_env(name: &str) -> Option<PathBuf> {
    std::env::var_os(name)
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
}

fn read_bounded_auth_json(path: &Path) -> Option<serde_json::Value> {
    let file = fs::File::open(path).ok()?;
    let mut bytes = Vec::new();
    file.take(PROVIDER_AUTH_JSON_MAX_BYTES + 1)
        .read_to_end(&mut bytes)
        .ok()?;
    parse_bounded_auth_json(&bytes)
}

fn parse_bounded_auth_json(bytes: &[u8]) -> Option<serde_json::Value> {
    if u64::try_from(bytes.len()).ok()? > PROVIDER_AUTH_JSON_MAX_BYTES {
        return None;
    }
    serde_json::from_slice(bytes).ok()
}

fn nonempty_json_string(value: Option<&serde_json::Value>) -> bool {
    value
        .and_then(serde_json::Value::as_str)
        .is_some_and(|value| !value.trim().is_empty())
}

#[cfg(test)]
fn codex_auth_json_authenticated(value: &serde_json::Value) -> bool {
    value
        .get("tokens")
        .and_then(serde_json::Value::as_object)
        .is_some_and(|tokens| {
            tokens
                .values()
                .any(|value| nonempty_json_string(Some(value)))
        })
        || nonempty_json_string(value.get("OPENAI_API_KEY"))
}

fn claude_auth_json_authenticated(value: &serde_json::Value) -> bool {
    value
        .get("claudeAiOauth")
        .and_then(serde_json::Value::as_object)
        .is_some_and(|oauth| {
            nonempty_json_string(oauth.get("accessToken"))
                || nonempty_json_string(oauth.get("refreshToken"))
        })
}

fn opencode_auth_json_authenticated(value: &serde_json::Value) -> bool {
    value
        .as_object()
        .is_some_and(|providers| providers.values().any(opencode_auth_entry_authenticated))
}

fn opencode_auth_entry_authenticated(value: &serde_json::Value) -> bool {
    match value.get("type").and_then(serde_json::Value::as_str) {
        Some("api") => nonempty_json_string(value.get("key")),
        Some("oauth") => {
            value
                .get("expires")
                .and_then(serde_json::Value::as_u64)
                .is_some()
                && value
                    .get("access")
                    .is_some_and(serde_json::Value::is_string)
                && value
                    .get("refresh")
                    .is_some_and(serde_json::Value::is_string)
                && (nonempty_json_string(value.get("access"))
                    || nonempty_json_string(value.get("refresh")))
        }
        Some("wellknown") => {
            value.get("key").is_some_and(serde_json::Value::is_string)
                && value.get("token").is_some_and(serde_json::Value::is_string)
                && (nonempty_json_string(value.get("key"))
                    || nonempty_json_string(value.get("token")))
        }
        _ => false,
    }
}

fn nonempty_env(name: &str) -> Option<String> {
    std::env::var(name)
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

async fn provider_auth_status(provider: CodingProvider) -> Result<String> {
    match provider {
        // CLI-backed providers probe executable candidates rather than trusting a broken launcher on PATH.
        CodingProvider::Codex => Ok(
            if borg_provider::openai_subscription::account()?.is_some() {
                "Logged in using ChatGPT"
            } else {
                "Not logged in"
            }
            .to_string(),
        ),
        CodingProvider::Claude => {
            #[cfg(feature = "subscription-adapters")]
            {
                let authority = borg_provider::claude_subscription::AuthAuthority::resolve(None)?;
                Ok(borg_provider::claude_subscription::status(authority)
                    .await?
                    .to_string())
            }
            #[cfg(not(feature = "subscription-adapters"))]
            {
                bail!("Claude subscription adapter is unavailable")
            }
        }
        CodingProvider::OpenCode => {
            runtime_output(borg_provider::Runtime::OpenCode, &["providers", "list"]).await
        }
        CodingProvider::Grok => Ok(if grok_credentials_present() {
            "Logged in"
        } else {
            "Not logged in"
        }
        .to_string()),
        CodingProvider::Muse => Ok(if muse_credentials_present() {
            "Logged in"
        } else {
            "Not logged in"
        }
        .to_string()),
        _ => bail!("{provider:?} does not use an interactive provider login"),
    }
}

fn claude_auth_status_authenticated(output: &str) -> bool {
    match serde_json::from_str::<serde_json::Value>(output) {
        Ok(value) => value
            .get("loggedIn")
            .or_else(|| value.get("logged_in"))
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false),
        Err(_) => {
            // Non-JSON output is an older CLI or an error banner. Only a
            // positive statement counts; an unrelated message (a crash, an
            // update notice, a login URL) must not read as authenticated.
            let normalized = output.to_ascii_lowercase();
            !normalized.contains("not logged in")
                && !normalized.contains("logged out")
                && (normalized.contains("logged in") || normalized.contains("authenticated"))
        }
    }
}

fn codex_auth_status_authenticated(output: &str) -> bool {
    if let Ok(value) = serde_json::from_str::<serde_json::Value>(output)
        && let Some(authenticated) = value
            .get("loggedIn")
            .or_else(|| value.get("logged_in"))
            .or_else(|| value.get("authenticated"))
            .and_then(serde_json::Value::as_bool)
    {
        let method = value
            .get("authMethod")
            .or_else(|| value.get("auth_mode"))
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        return authenticated && !matches!(method, "apikey" | "api_key" | "api-key");
    }
    let normalized = output.to_ascii_lowercase();
    !normalized.contains("api key")
        && !normalized.contains("apikey")
        && !normalized.trim().is_empty()
        && !normalized.contains("not logged in")
        && !normalized.contains("logged out")
        && !normalized.contains("unauthenticated")
        && (normalized.contains("logged in")
            || normalized.contains("authenticated")
            || normalized.contains("success"))
}

fn opencode_auth_status_authenticated(output: &str) -> bool {
    // `opencode providers list` renders its table header even when no provider
    // has credentials. A provider row is marked with a filled bullet; treat
    // that as the CLI's configured signal rather than merely accepting a
    // successful command exit.
    output.lines().any(|line| line.contains('●'))
}

/// Run a resolved provider runtime and capture its output.
async fn runtime_output(runtime: borg_provider::Runtime, args: &[&str]) -> Result<String> {
    let mut command = borg_provider::runtime_command(runtime).await?;
    command.args(args).stdin(Stdio::null());
    command_output_from(&mut command, runtime.program()).await
}

async fn command_output(executable: &str, args: &[&str]) -> Result<String> {
    let mut command = Command::new(executable);
    command.args(args).stdin(Stdio::null());
    command_output_from(&mut command, executable).await
}

async fn command_output_from(command: &mut Command, executable: &str) -> Result<String> {
    let output = tokio::time::timeout(Duration::from_secs(8), command.output())
        .await
        .context("provider probe timed out")?
        .with_context(|| format!("{executable} is not installed"))?;
    if !output.status.success() {
        bail!("{executable} command failed");
    }
    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
    Ok(if stdout.is_empty() { stderr } else { stdout })
}

/// Whether `provider` already has credentials on this machine — an OAuth
/// session file written by its CLI, or an API key borg holds. Providers whose
/// credentials come from the environment are treated as configured; they fail
/// loudly at call time with their own message.
pub fn provider_credentials_present(provider: CodingProvider) -> bool {
    match provider {
        CodingProvider::Claude => {
            borg_provider::credentials::api_key(
                borg_provider::credentials::ApiKeyCredential::Anthropic,
            )
            .is_some()
                || provider_subscription_credentials_present(provider)
        }
        CodingProvider::Codex => {
            if borg_provider::credentials::openai_uses_api_key() {
                borg_provider::credentials::openai_api_key().is_some()
            } else {
                provider_subscription_credentials_present(provider)
            }
        }
        CodingProvider::OpenCode => {
            borg_provider::credentials::opencode_go_api_key().is_some()
                || provider_subscription_credentials_present(provider)
        }
        CodingProvider::Anthropic => borg_provider::credentials::api_key(
            borg_provider::credentials::ApiKeyCredential::Anthropic,
        )
        .is_some(),
        CodingProvider::Grok => grok_credentials_present(),
        CodingProvider::Muse => muse_credentials_present(),
        CodingProvider::Kimi => {
            borg_provider::subscription::active_for(borg_provider::Plan::KimiCode)
                .and_then(|plan| plan.api_key())
                .is_some()
                || nonempty_env("BORG_KIMI_API_KEY").is_some()
                || nonempty_env("MOONSHOT_API_KEY").is_some()
        }
        CodingProvider::Glm => {
            borg_provider::subscription::active_for(borg_provider::Plan::GlmCoding)
                .and_then(|plan| plan.api_key())
                .is_some()
                || nonempty_env("BORG_GLM_API_KEY").is_some()
        }
        CodingProvider::Qwen => {
            borg_provider::subscription::active_for(borg_provider::Plan::QwenCoding)
                .and_then(|plan| plan.api_key())
                .is_some()
                || nonempty_env("BORG_QWEN_API_KEY").is_some()
                || nonempty_env("DASHSCOPE_API_KEY").is_some()
        }
        CodingProvider::OpenRouter => borg_provider::credentials::api_key(
            borg_provider::credentials::ApiKeyCredential::OpenRouter,
        )
        .is_some(),
        CodingProvider::Vercel => borg_provider::credentials::api_key(
            borg_provider::credentials::ApiKeyCredential::Vercel,
        )
        .is_some(),
        CodingProvider::OpenAiCompatible => {
            nonempty_env("BORG_OPENAI_COMPATIBLE_BASE_URL").is_some()
                || nonempty_env("BORG_OPENAI_COMPATIBLE_MODEL").is_some()
        }
    }
}

fn provider_login_command(provider: CodingProvider, mut command: Command) -> Result<Command> {
    if provider.uses_native_harness() {
        bail!(
            "{provider:?} uses API credentials from the environment; configure the provider key and endpoint variables"
        );
    }
    match provider {
        CodingProvider::Codex => bail!("ChatGPT subscription login is handled natively"),
        CodingProvider::Claude => bail!("Claude subscription login is handled natively"),
        CodingProvider::OpenCode => {
            command.args(["providers", "login"]);
        }
        CodingProvider::Grok => {
            command.args(["login"]);
        }
        CodingProvider::Muse => {
            command.args(["login"]);
        }
        CodingProvider::Anthropic
        | CodingProvider::Kimi
        | CodingProvider::Glm
        | CodingProvider::Qwen
        | CodingProvider::OpenRouter
        | CodingProvider::Vercel
        | CodingProvider::OpenAiCompatible => {
            unreachable!("handled above")
        }
    };
    Ok(command)
}

pub async fn login_provider(provider: CodingProvider) -> Result<()> {
    if matches!(provider, CodingProvider::Codex | CodingProvider::Claude) {
        return login_provider_with_output(provider, |line| println!("{line}")).await;
    }
    let command = if provider == CodingProvider::Muse {
        borg_provider::provider_bin::command(borg_provider::Runtime::Muse).await?
    } else {
        Command::new(provider.executable())
    };
    let status = provider_login_command(provider, command)?
        .status()
        .await
        .with_context(|| format!("failed to start {} login", provider.executable()))?;
    if !status.success() {
        bail!("{} login exited with {status}", provider.executable());
    }
    let auth = provider_auth_status(provider).await.with_context(|| {
        format!(
            "{} login completed but auth status failed",
            provider.executable()
        )
    })?;
    anyhow::ensure!(
        match provider {
            CodingProvider::Codex => codex_auth_status_authenticated(&auth),
            CodingProvider::Claude => claude_auth_status_authenticated(&auth),
            CodingProvider::Muse => muse_stored_credentials_present(),
            _ => !auth.trim().is_empty(),
        },
        "{} login completed but no authenticated session is available",
        provider.executable()
    );
    if let Some(cache) = PROVIDER_CAPABILITIES_CACHE.get() {
        cache.lock().await.clear();
    }
    crate::provider_usage::clear_login_dependent_usage_caches().await;
    Ok(())
}

async fn stream_provider_login_output(
    stream: impl AsyncRead + Unpin,
    tx: mpsc::UnboundedSender<String>,
) {
    let mut lines = BufReader::new(stream).lines();
    while let Ok(Some(line)) = lines.next_line().await {
        let _ = tx.send(line);
    }
}

/// Run a provider's browser/device login without requiring a terminal and
/// stream its user-facing output to a native frontend.
pub async fn login_provider_with_output(
    provider: CodingProvider,
    mut on_output: impl FnMut(&str) + Send,
) -> Result<()> {
    #[cfg(feature = "subscription-adapters")]
    if provider == CodingProvider::Claude {
        let authority = borg_provider::claude_subscription::AuthAuthority::resolve(None)?;
        let login = borg_provider::claude_subscription::begin_browser_login(authority).await?;
        on_output(&format!(
            "Open {} to connect your Claude subscription (expires in 10 minutes).",
            login.authorize_url()
        ));
        login.complete().await?;
        if let Some(cache) = PROVIDER_CAPABILITIES_CACHE.get() {
            cache.lock().await.clear();
        }
        crate::provider_usage::clear_login_dependent_usage_caches().await;
        on_output("Connected Claude subscription. Saved API credentials were kept.");
        return Ok(());
    }
    if provider == CodingProvider::Codex {
        let login = borg_provider::openai_subscription::begin_device_login().await?;
        on_output(&format!(
            "Open {} and enter code {} (expires in 15 minutes).",
            login.verification_url, login.user_code
        ));
        borg_provider::openai_subscription::complete_device_login(login).await?;
        borg_provider::credentials::set_openai_auth_mode(
            borg_provider::credentials::OpenAiAuthMode::Subscription,
        )?;
        if let Some(cache) = PROVIDER_CAPABILITIES_CACHE.get() {
            cache.lock().await.clear();
        }
        crate::provider_usage::clear_login_dependent_usage_caches().await;
        on_output("Connected ChatGPT subscription. Saved API credentials were kept.");
        return Ok(());
    }
    let command = if provider == CodingProvider::Muse {
        borg_provider::provider_bin::command(borg_provider::Runtime::Muse).await?
    } else {
        Command::new(provider.executable())
    };
    let mut command = provider_login_command(provider, command)?;
    command
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = command
        .spawn()
        .with_context(|| format!("failed to start {} login", provider.executable()))?;
    let stdout = child
        .stdout
        .take()
        .context("provider login stdout missing")?;
    let stderr = child
        .stderr
        .take()
        .context("provider login stderr missing")?;
    let (line_tx, mut line_rx) = mpsc::unbounded_channel();
    let stdout_task = host_transport::spawn(stream_provider_login_output(stdout, line_tx.clone()));
    let stderr_task = host_transport::spawn(stream_provider_login_output(stderr, line_tx.clone()));
    drop(line_tx);
    while let Some(line) = line_rx.recv().await {
        on_output(&line);
    }
    let _ = tokio::join!(stdout_task, stderr_task);
    let status = child
        .wait()
        .await
        .with_context(|| format!("failed to wait for {} login", provider.executable()))?;
    if !status.success() {
        bail!("{} login exited with {status}", provider.executable());
    }
    let auth = provider_auth_status(provider).await.with_context(|| {
        format!(
            "{} login completed but auth status failed",
            provider.executable()
        )
    })?;
    anyhow::ensure!(
        match provider {
            CodingProvider::Codex => codex_auth_status_authenticated(&auth),
            CodingProvider::Claude => claude_auth_status_authenticated(&auth),
            CodingProvider::Muse => muse_stored_credentials_present(),
            _ => !auth.trim().is_empty(),
        },
        "{} login completed but no authenticated session is available",
        provider.executable()
    );
    if let Some(cache) = PROVIDER_CAPABILITIES_CACHE.get() {
        cache.lock().await.clear();
    }
    crate::provider_usage::clear_login_dependent_usage_caches().await;
    Ok(())
}

pub type HostExecutorFactory =
    Arc<dyn Fn(&HostConfig, &LaunchSession) -> Result<Arc<dyn AgentTurnExecutor>> + Send + Sync>;

fn default_host_executor_factory() -> HostExecutorFactory {
    Arc::new(|config, launch| {
        let executor = if launch.provider == CodingProvider::Kimi {
            crate::LocalAgentTurnExecutor::with_model_gateway(
                borg_provider::provider::ModelGateway::new(
                    endpoint(&config.server, "/api/remote/host/kimi/chat/completions"),
                    config.host_token.clone(),
                ),
            )
        } else {
            crate::LocalAgentTurnExecutor::default()
        };
        Ok(Arc::new(executor))
    })
}

pub async fn run_host(config_path: &Path) -> Result<()> {
    run_host_with_executor_factory(config_path, default_host_executor_factory()).await
}

pub async fn run_host_with_executor_factory(
    config_path: &Path,
    executor_factory: HostExecutorFactory,
) -> Result<()> {
    run_host_with_resolved_store(config_path, executor_factory, None).await
}

/// The host loop with the journal it runs against made explicit.
///
/// The public entry keeps environment selection, which is the production
/// contract for a relay. A caller that already holds one specific backend
/// passes it here instead: a test driving a scratch database needs the host to
/// run against that database, because a host that resolved its own would poll
/// a different journal than the test seeded and every fault the test injected
/// would be invisible to it -- the test would pass while proving nothing.
pub(crate) async fn run_host_with_resolved_store(
    config_path: &Path,
    executor_factory: HostExecutorFactory,
    injected_store: Option<crate::session_store::factory::ResolvedSessionStore>,
) -> Result<()> {
    let config: HostConfig = serde_json::from_slice(
        &fs::read(config_path)
            .with_context(|| format!("failed to read {}", config_path.display()))?,
    )
    .with_context(|| format!("invalid host config {}", config_path.display()))?;
    config.validate()?;
    ensure!(
        Url::parse(&config.server)?.scheme() == "https",
        "remote host daemon requires a verified HTTPS/WSS relay route"
    );
    ensure_execution_boundary(&config)?;
    let client = Client::builder()
        .connect_timeout(Duration::from_secs(10))
        .timeout(Duration::from_secs(35))
        .build()?;
    let sessions: Arc<Mutex<HashMap<Uuid, mpsc::Sender<HostCommand>>>> =
        Arc::new(Mutex::new(HashMap::new()));
    let session_root = config_path
        .parent()
        .unwrap_or_else(|| Path::new("."))
        .join("sessions");
    // The relay picks its backend from BORG_SESSIONS_URL like every other
    // entry point, and resolves every tier before starting any loop -- this
    // process is long-running by definition, so there is no ownership race to
    // settle first and nothing to defer.
    let resolved = match injected_store {
        Some(resolved) => resolved,
        None => {
            crate::session_store::factory::open_resolved(
                &crate::session_store::factory::SessionStoreConfig::from_env(),
            )
            .await?
        }
    };
    let session_store = Arc::clone(resolved.session());
    let receipts = Arc::clone(resolved.receipts());
    let mut capabilities =
        probe_capabilities_with_profile(config.roots.clone(), config.execution_profile).await;
    capabilities.resource_limits = config.resource_limits.clone();
    let authority = session_store
        .postgres_authority()
        .context("remote host requires PostgreSQL journal authority")?;
    let ledger = crate::command_ledger::CommandLedger::open(authority.pool.clone()).await?;
    let (outbound, mut outgoing) = mpsc::channel(128);
    let transport = host_transport::Transport::new(config.host_id, outbound.clone());
    transport.set_ledger(ledger.clone())?;
    host_transport::CURRENT.scope(transport.clone(), async move {
    let _shutdown = host_transport::StopOnDrop(transport.clone());
    let _heartbeat = AbortTask(host_transport::spawn(run_host_heartbeat_loop(
        client.clone(), config.clone(), Arc::clone(&sessions), capabilities,
    )));
    let _operations = AbortTask(host_transport::spawn(run_host_operation_loop(
        client.clone(), config.clone(), Arc::clone(&receipts), session_root.clone(),
    )));
    let _workspace_recovery = AbortTask(host_transport::spawn(run_host_workspace_recovery_loop(
        client.clone(), config.clone(), Arc::clone(&session_store), Arc::clone(&sessions), session_root.clone(),
    )));
    let (commands, mut command_rx) = mpsc::channel(128);
    let context = DispatchContext {
        client, config: config.clone(), session_root, sessions: Arc::clone(&sessions),
        session_store, receipts, executor_factory,
    };
    let recovery_context = context.clone();
    let _recovery = AbortTask(host_transport::spawn(async move {
        let mut offset = 0;
        let mut retry = RemoteRetryBackoff::default();
        loop {
            match resume_pending_host_sessions(offset, &recovery_context.client, &recovery_context.config,
                &recovery_context.session_root, &recovery_context.sessions, &recovery_context.session_store,
                &recovery_context.executor_factory).await {
                Ok(next) => { retry.reset(); offset = next; if next == 0 { break; } }
                Err(error) => {
                    tracing::warn!(%error, offset, "host startup recovery deferred; retrying");
                    tokio::time::sleep(retry.next_delay(None)).await;
                }
            }
        }
    }));
    let (viewer_tx, mut viewer_rx) = mpsc::channel(128);
    let sync = crate::sync::SyncAuthority::open(config.host_id, config.revocation_epoch, Arc::clone(&context.session_store), outbound.clone(), viewer_tx).await?;
    let viewer_context = context.clone();
    let viewer_ledger = ledger.clone();
    let viewer_authority = Arc::clone(&sync);
    let viewer_outbound = outbound.clone();
    let _viewer = AbortTask(host_transport::spawn(async move {
        while let Some(viewer) = viewer_rx.recv().await {
            let connection_id = viewer.connection_id.clone();
            let scope = viewer.scope.clone();
            let frame = match viewer_command(&viewer_ledger, viewer_context.clone(), viewer).await {
                Ok(frame) => frame,
                Err(error) => {
                    let _ = viewer_authority.emit(&connection_id, borg_view::wire::ServerFrame::Gap { scope, reason: error.to_string() });
                    viewer_authority.close_connection(&connection_id).await;
                    let _ = viewer_outbound.try_send(crate::auth::TunnelFrame::Close { connection_id, reason: error.to_string() });
                    continue;
                }
            };
            if let Err(error) = viewer_authority.emit(&connection_id, frame) {
                viewer_authority.close_connection(&connection_id).await;
                let _ = viewer_outbound.try_send(crate::auth::TunnelFrame::Close { connection_id, reason: error.to_string() });
            }
        }
    }));
    let issuer = crate::admission::issuer_key(&config.relay_public_key)?;
    let mut epoch = config.revocation_epoch;
    let mut direct = config.direct_listener.clone().map(|listener| direct_listener::start(listener, config.host_id, issuer, Arc::clone(&sync)).map(AbortTask)).transpose()?;
    let _dispatcher = AbortTask(host_transport::spawn(async move {
        while let Some((command_id, command, not_after)) = command_rx.recv().await {
            let result = owner_command(&ledger, context.clone(), command_id, command, not_after).await;
            if let Err(error) = transport.outbound.send(result).await {
                tracing::warn!(%error, "owner result transport stopped");
                break;
            }
        }
    }));
    let (incoming_tx, mut incoming) = mpsc::channel(128);
    let (lifecycle_tx, mut lifecycle) = mpsc::channel(8);
    let (restart_tx, mut restart_rx) = watch::channel(0_u64);
    let socket_config = config.clone();
    let socket_transport = host_transport::get(config.host_id)?;
    let mut socket = AbortTask(host_transport::spawn(async move {
        let mut retry = RemoteRetryBackoff::default();
        loop {
            let _ = lifecycle_tx.try_send(true);
            let connected_at = Instant::now();
            let result = tokio::select! {
                result = crate::tunnel::connect(&socket_config, incoming_tx.clone(), &mut outgoing) => result,
                changed = restart_rx.changed() => {
                    changed.context("host reconnect control stopped")?;
                    Err(anyhow::anyhow!("owner ingress overflow; reconnect without cancelling actors"))
                }
            };
            socket_transport.connection_lost();
            if let Err(error) = result {
                if error.downcast_ref::<crate::tunnel::TerminalAuthentication>().is_some() { return Err(error); }
                tracing::warn!(%error, "host tunnel disconnected; actors retained");
            } else {
                bail!("host tunnel unexpectedly stopped");
            }
            let _ = lifecycle_tx.try_send(false);
            if connected_at.elapsed() >= Duration::from_secs(60) { retry.reset(); }
            let jitter = Duration::from_millis(u64::from(Uuid::new_v4().as_bytes()[0]) * 4);
            tokio::time::sleep(retry.next_delay(None) + jitter).await;
        }
    }));
    loop {
        tokio::select! {
            result = &mut socket.0 => {
                let error = match result { Ok(Err(error)) => error, Ok(Ok(())) => anyhow::anyhow!("host socket supervisor stopped"), Err(error) => error.into() };
                if error.downcast_ref::<crate::tunnel::TerminalAuthentication>().is_some() {
                    for (id, sender) in sessions.lock().await.iter() {
                        let _ = sender.try_send(HostCommand::Stop { session_id: *id });
                    }
                }
                sync.shutdown().await;
                return Err(error);
            }
            result = async {
                match direct.as_mut() { Some(task) => (&mut task.0).await, None => std::future::pending().await }
            } => {
                sync.shutdown().await;
                result.context("direct listener task failed")?.context("direct listener failed")?;
                bail!("direct listener stopped unexpectedly");
            }
            started = lifecycle.recv() => {
                match started {
                    Some(true) => {
                        let authority = Arc::clone(&sync);
                        let transport = host_transport::get(config.host_id)?;
                        transport.wakes().reconnected();
                        host_transport::spawn(async move {
                            if let Err(error) = transport.announce_routes().await { tracing::warn!(%error, "route announcement deferred"); }
                            for (session, request) in transport.registrations() {
                                if let Err(error) = transport.register(session, request).await { tracing::debug!(%error, "registration replay deferred"); break; }
                            }
                            if let Err(error) = authority.relay_reconnected().await { tracing::warn!(%error, "relay catalog rescan deferred"); }
                        });
                    }
                    Some(false) => sync.relay_disconnected().await,
                    None => bail!("host socket lifecycle channel closed"),
                }
            }
            frame = incoming.recv() => {
                let Some(frame) = frame else { bail!("host tunnel ingress stopped") };
                match frame {
                        crate::auth::TunnelFrame::HostCommand { command_id, command, not_after } => {
                            match commands.try_send((command_id, command, not_after)) {
                                Ok(()) => {},
                                Err(mpsc::error::TrySendError::Full(_)) => {
                                    restart_tx.send_modify(|generation| *generation = generation.wrapping_add(1));
                                }
                                Err(mpsc::error::TrySendError::Closed(_)) => {
                                    sync.shutdown().await;
                                    bail!("owner command dispatcher stopped");
                                }
                            }
                        }
                        crate::auth::TunnelFrame::RegisteredSession { registration_id, error, .. } => {
                            host_transport::get(config.host_id)?.registered(&registration_id, error);
                        }
                        crate::auth::TunnelFrame::CollaborationChanged { session_id } => {
                            match Uuid::parse_str(&session_id) {
                                Ok(session_id) => host_transport::get(config.host_id)?.wakes().collaboration_changed(session_id),
                                Err(error) => tracing::warn!(%error, "relay sent an invalid collaboration session id"),
                            }
                        }
                        crate::auth::TunnelFrame::EpochUpdate { epoch: updated } => {
                            ensure!(updated >= epoch, "relay revocation epoch regressed");
                            epoch = updated;
                            sync.update_epoch(epoch).await;
                        }
                        crate::auth::TunnelFrame::OpenService { connection_id, ticket, nonce, proof } => {
                            let admitted = async {
                                let claims = crate::admission::verify_service_ticket(&ticket, &issuer, &config.host_id.to_string(), epoch, Utc::now().timestamp())?;
                                crate::admission::verify_service_proof(&claims, &nonce, &proof)?;
                                sync.open_service_connection(connection_id.clone(), claims).await
                            }.await;
                            if let Err(error) = admitted {
                                let _ = outbound.try_send(crate::auth::TunnelFrame::Close { connection_id, reason: error.to_string() });
                            }
                        }
                        crate::auth::TunnelFrame::Open { connection_id, ticket } => {
                            let admitted = crate::admission::verify_ticket(&ticket, &issuer, &config.host_id.to_string(), epoch, Utc::now().timestamp());
                            match admitted {
                                Ok(claims) => { if let Err(error) = sync.open_connection(connection_id.clone(), claims).await {
                                    let _ = outbound.try_send(crate::auth::TunnelFrame::Close { connection_id, reason: error.to_string() });
                                } }
                                Err(error) => { let _ = outbound.try_send(crate::auth::TunnelFrame::Close { connection_id, reason: error.to_string() }); }
                            }
                        }
                        crate::auth::TunnelFrame::Client { connection_id, frame } => {
                            let result = async { sync.handle(&connection_id, serde_json::from_value(frame)?).await }.await;
                            match result {
                                Ok(frames) => for frame in frames { let _ = outbound.try_send(crate::auth::TunnelFrame::Server { connection_id: connection_id.clone(), frame: serde_json::to_value(frame)? }); },
                                Err(error) => { sync.close_connection(&connection_id).await; let _ = outbound.try_send(crate::auth::TunnelFrame::Close { connection_id, reason: error.to_string() }); }
                            }
                        }
                        crate::auth::TunnelFrame::Close { connection_id, .. } => sync.close_connection(&connection_id).await,
                    _ => {}
                }
            }
        }
    }
    }).await
}

fn viewer_cancelled_provider_interaction_response(kind: &str) -> serde_json::Value {
    if kind == "mcp_elicitation" {
        serde_json::json!({ "action": "cancel" })
    } else {
        serde_json::json!({ "answers": {} })
    }
}

fn viewer_provider_interaction_response(
    kind: &str,
    payload: &serde_json::Value,
    input: &str,
) -> anyhow::Result<serde_json::Value> {
    use anyhow::Context as _;

    if input.eq_ignore_ascii_case("/cancel") {
        return Ok(viewer_cancelled_provider_interaction_response(kind));
    }
    if kind == "mcp_elicitation" {
        if input.eq_ignore_ascii_case("/decline") {
            return Ok(serde_json::json!({ "action": "decline" }));
        }
        let content = match serde_json::from_str::<serde_json::Value>(input) {
            Ok(value) => value,
            Err(_) => {
                let properties = payload
                    .get("requestedSchema")
                    .and_then(|schema| schema.get("properties"))
                    .and_then(serde_json::Value::as_object)
                    .context(
                        "Enter JSON matching the requested form, or use /decline or /cancel",
                    )?;
                anyhow::ensure!(
                    properties.len() == 1,
                    "Enter a JSON object matching the requested form, or use /decline or /cancel"
                );
                let key = properties.keys().next().expect("one property");
                serde_json::json!({ key: input })
            }
        };
        return Ok(serde_json::json!({ "action": "accept", "content": content }));
    }
    let questions = payload
        .get("questions")
        .and_then(serde_json::Value::as_array)
        .context("Provider user-input request did not include questions")?;
    if questions.len() == 1 {
        let id = questions[0]
            .get("id")
            .and_then(serde_json::Value::as_str)
            .context("Provider user-input question did not include an id")?;
        return Ok(serde_json::json!({ "answers": { (id): { "answers": [input] } } }));
    }
    let value: serde_json::Value = serde_json::from_str(input).context(
        "Answer multiple questions with a JSON object keyed by question id, or use /cancel",
    )?;
    if value.get("answers").is_some() {
        return Ok(value);
    }
    let values = value
        .as_object()
        .context("Multiple answers must be a JSON object keyed by question id")?;
    let mut answers = serde_json::Map::new();
    for question in questions {
        let id = question
            .get("id")
            .and_then(serde_json::Value::as_str)
            .context("Provider user-input question did not include an id")?;
        let answer = values
            .get(id)
            .with_context(|| format!("Missing answer for question {id}"))?;
        let answer_values = match answer {
            serde_json::Value::Array(values) => values.clone(),
            value => vec![value.clone()],
        };
        anyhow::ensure!(
            answer_values.iter().all(serde_json::Value::is_string),
            "Answer for {id} must be a string or an array of strings"
        );
        answers.insert(
            id.to_string(),
            serde_json::json!({ "answers": answer_values }),
        );
    }
    Ok(serde_json::json!({ "answers": answers }))
}

async fn viewer_attachments(
    context: &DispatchContext,
    session: Uuid,
    refs: &[borg_view::wire::AssetRef],
) -> Result<Vec<PathBuf>> {
    ensure!(
        refs.len() <= crate::MAX_MESSAGE_ATTACHMENTS,
        "too many attachments"
    );
    let mut paths = Vec::new();
    for asset in refs {
        let attachment = crate::MessageAttachment {
            name: asset.id.clone(),
            sha256: asset.id.clone(),
            media_type: asset.media_type.clone(),
            byte_len: asset.bytes.parse()?,
        };
        crate::validate_message_attachment(&attachment)?;
        if crate::load_message_attachment(&context.session_root, &attachment)
            .await
            .is_err()
        {
            let mut response = context
                .client
                .get(endpoint(
                    &context.config.server,
                    &format!(
                        "/api/remote/host/sessions/{session}/attachments/{}",
                        attachment.sha256
                    ),
                ))
                .bearer_auth(&context.config.host_token)
                .timeout(Duration::from_secs(30))
                .send()
                .await?
                .error_for_status()?;
            let mut bytes = Vec::new();
            while let Some(chunk) = response.chunk().await? {
                ensure!(
                    (bytes.len() as u64).saturating_add(chunk.len() as u64) <= attachment.byte_len,
                    "attachment exceeds declared length"
                );
                bytes.extend_from_slice(&chunk);
            }
            crate::store_relayed_message_attachment(&context.session_root, &attachment, &bytes)
                .await?;
        }
        let extension = match attachment.media_type.as_str() {
            "image/png" => "png",
            "image/jpeg" => "jpg",
            _ => bail!("unsupported attachment media type"),
        };
        paths.push(
            context
                .session_root
                .join("attachments")
                .join(format!("{}.{}", attachment.sha256, extension)),
        );
    }
    Ok(paths)
}

async fn viewer_command(
    ledger: &crate::command_ledger::CommandLedger,
    context: DispatchContext,
    viewer: crate::sync::ViewerCommand,
) -> Result<borg_view::wire::ServerFrame> {
    use borg_view::wire::{Command, CommandOutcome, Cursor, Scope, ServerFrame};
    let session_id = match &viewer.scope {
        Scope::Session { session_id } => Some(Uuid::parse_str(session_id)?),
        Scope::Host => None,
    };
    let scope = crate::projection::scope_key(context.config.host_id, session_id);
    let projection = crate::projection::ProjectionStore::open(
        context
            .session_store
            .postgres_authority()
            .context("missing PostgreSQL authority")?
            .pool,
    )
    .await?;
    let head = projection
        .load(&scope)
        .await?
        .context("scope projection is not initialized")?;
    let encoded = serde_json::to_vec(&viewer.command)?;
    let outcome = match ledger
        .admit(
            context.config.host_id,
            viewer.command_id,
            &scope,
            &viewer.principal,
            &encoded,
        )
        .await?
    {
        crate::command_ledger::Admission::Terminal(bytes) => serde_json::from_slice(&bytes)?,
        crate::command_ledger::Admission::InDoubt
            if matches!(viewer.command, Command::Prompt { .. }) =>
        {
            let session = session_id.context("prompt requires session scope")?;
            ledger
                .bind_prompt(
                    context.config.host_id,
                    viewer.command_id,
                    session,
                    viewer.command_id,
                )
                .await?;
            if let Command::Prompt {
                text,
                attachments,
                delivery,
            } = &viewer.command
            {
                let attachments = viewer_attachments(&context, session, attachments).await?;
                let delivery = match delivery {
                    borg_view::wire::Delivery::Queue => crate::PromptDelivery::Queue,
                    borg_view::wire::Delivery::Steer => crate::PromptDelivery::Steer,
                };
                if context
                    .session_store
                    .contains_message(session, viewer.command_id)
                    .await?
                {
                    admit_remote_prompt(
                        context.session_store.as_ref(),
                        session,
                        viewer.command_id,
                        text,
                        &attachments,
                        delivery,
                    )
                    .await?;
                } else {
                    ensure!(
                        dispatch(
                            context.clone(),
                            HostCommand::Prompt {
                                session_id: session,
                                message_id: viewer.command_id,
                                text: text.clone(),
                                attachments,
                                delivery,
                                output_schema: None
                            }
                        )
                        .await,
                        "prompt admission interrupted"
                    );
                }
            }
            CommandOutcome::Applied
        }
        crate::command_ledger::Admission::InDoubt => CommandOutcome::Rejected {
            code: "interrupted".into(),
            message: "effect was started; automatic replay refused".into(),
        },
        crate::command_ledger::Admission::New => {
            let mut approval_unconfirmed = false;
            let translate = async {
                let session_id = session_id.context("command requires session scope")?;
                let command = match viewer.command {
                    Command::Prompt {
                        text,
                        delivery,
                        attachments,
                    } => {
                        ledger.bind_prompt(context.config.host_id, viewer.command_id, session_id, viewer.command_id).await?;
                        let attachments = viewer_attachments(&context, session_id, &attachments).await?;
                        HostCommand::Prompt {
                            session_id,
                            message_id: viewer.command_id,
                            text,
                            attachments,
                            output_schema: None,
                            delivery: match delivery {
                                borg_view::wire::Delivery::Steer => crate::PromptDelivery::Steer,
                                borg_view::wire::Delivery::Queue => crate::PromptDelivery::Queue,
                            },
                        }
                    }
                    Command::Approval { approval_id, source_session_id, target_revision, decision, edited_input } => {
                        ensure!(Uuid::parse_str(&source_session_id)? == session_id, "approval source differs from scope");
                        HostCommand::Approve { session_id, approval_id, expected_request: Some(Uuid::parse_str(&target_revision)?), acknowledgement: None, edited_input, decision: match decision {
                            borg_view::wire::Decision::Once => crate::ApprovalDecision::AllowOnce,
                            borg_view::wire::Decision::Session => crate::ApprovalDecision::AllowSession,
                            borg_view::wire::Decision::Deny => crate::ApprovalDecision::Deny,
                        }
}
                    }
                    Command::RespondToQuestion { approval_id, source_session_id, target_revision, text } => {
                        ensure!(Uuid::parse_str(&source_session_id)? == session_id, "question source differs from scope");
                        let state = context.session_store.state(session_id).await?;
                        ensure!(state.pending_provider_interaction_id.as_deref() == Some(approval_id.as_str()), "question is no longer pending");
                        let response = viewer_provider_interaction_response(state.pending_provider_interaction_kind.as_deref().context("question kind unavailable")?, state.pending_provider_interaction_payload.as_ref().context("question payload unavailable")?, &text)?;
                        HostCommand::RespondToProviderInteraction { session_id, interaction_id: approval_id, response, expected_request: Some(Uuid::parse_str(&target_revision)?), acknowledgement: None,
}
                    }
                    Command::NewSession { cwd } => {
                        let mut request = scope_registration(context.session_store.as_ref(), session_id).await?.context("session launch configuration unavailable")?;
                        request.cwd = validate_host_cwd(&context.config.roots, Path::new(&cwd))?;
                        request.request_id = viewer.command_id;
                        request.initial_prompt = None;
                        HostCommand::Launch { session_id: viewer.command_id, request: Box::new(request), attachment: None }
                    }
                    Command::Configure {
                        provider,
                        model,
                        effort,
                        fast,
                        ultrafast,
                        permission_mode,
                        response_language,
                    } => {
                        if let Some(permission_mode) = permission_mode {
                            ensure!(
                                dispatch(
                                    context.clone(),
                                    HostCommand::Configure {
                                        session_id,
                                        action: crate::SessionConfigAction::SetPermissionMode {
                                            permission_mode
                                        }
                                    }
                                )
                                .await,
                                "permission configuration interrupted"
                            );
                        }
                        if let Some(response_language) = response_language {
                            ensure!(
                                dispatch(
                                    context.clone(),
                                    HostCommand::Configure {
                                        session_id,
                                        action: crate::SessionConfigAction::SetResponseLanguage {
                                            language: response_language
                                        }
                                    }
                                )
                                .await,
                                "language configuration interrupted"
                            );
                        }
                        HostCommand::Configure {
                            session_id,
                            action: crate::SessionConfigAction::SetAgent {
                                request_id: viewer.command_id,
                                provider,
                                model,
                                effort,
                                fast,
                                ultrafast,
                            },
                        }
                    }
                    Command::Interrupt => HostCommand::Interrupt { session_id },
                    Command::Compact => HostCommand::Compact { session_id },
                    Command::ClearContext => HostCommand::ClearContext { session_id },
                    Command::FlushPendingInput => HostCommand::FlushPendingInput { session_id },
                    Command::Goal { action } => HostCommand::Goal { session_id, action: action.try_into()? },
                    Command::Todo { action } => HostCommand::Todo { session_id, action },
                    Command::StopWatch { watch_id } => HostCommand::StopWatch {
                        session_id,
                        watch_id: Uuid::parse_str(&watch_id)?,
                    },
                    Command::RecallQueuedPrompt {
                        message_id,
                        replacement,
                    } => {
                        ensure!(
                            replacement.is_none(),
                            "recall replacement requires canonical recall result"
                        );
                        HostCommand::RecallQueuedPrompt {
                            session_id,
                            message_id: message_id.map(|id| Uuid::parse_str(&id)).transpose()?,
                        }
                    }
                    Command::Slash { text } => {
                        use borg_view::intent::FrontendCommand as F;
                        let state = context.session_store.state(session_id).await?;
                        match borg_view::intent::parse_submission(
                            &text,
                            state
                                .configuration
                                .as_ref()
                                .context("session configuration unavailable")?
                                .provider,
                            crate::PromptDelivery::Steer,
                            &state.todos,
                        )? {
                            F::Interrupt => HostCommand::Interrupt { session_id },
                            F::Compact => HostCommand::Compact { session_id },
                            F::ClearContext => HostCommand::ClearContext { session_id },
                            F::FlushPendingInput => HostCommand::FlushPendingInput { session_id },
                            F::ApplyGoal(action) => HostCommand::Goal { session_id, action },
                            F::ApplyTodo(action) => HostCommand::Todo { session_id, action },
                            F::StopWatch(watch_id) => HostCommand::StopWatch {
                                session_id,
                                watch_id,
                            },
                            F::SubmitPrompt {
                                text,
                                attachments,
                                delivery,
                            } => {
                                ledger.bind_prompt(context.config.host_id, viewer.command_id, session_id, viewer.command_id).await?;
                                HostCommand::Prompt { session_id, message_id: viewer.command_id, text, attachments, delivery, output_schema: None }
                            },
                            F::ControlPeer { target, intent, attachments, delivery } => {
                                use borg_view::intent::{PeerTarget, PeerIntent};
                                ensure!(attachments.is_empty(), "peer prompt attachments require typed asset references");
                                let (task_name, provider) = match target { PeerTarget::Claude => ("/root/claude", CodingProvider::Claude), PeerTarget::Gpt => ("/root/gpt", CodingProvider::Codex) };
                                let action = match intent {
                                    PeerIntent::Ensure => crate::SubagentAction::Ensure { request_id: viewer.command_id, task_name: task_name.into(), provider, model: None, effort: None },
                                    PeerIntent::Clear => crate::SubagentAction::ClearContext { request_id: viewer.command_id, target: task_name.into() },
                                    PeerIntent::Rotate { model, effort } => crate::SubagentAction::Rotate { request_id: viewer.command_id, task_name: task_name.into(), provider, model, effort },
                                    PeerIntent::Prompt(text) => crate::SubagentAction::Prompt { request_id: viewer.command_id, target: task_name.into(), message_id: viewer.command_id, text, attachments, delivery },
                                };
                                HostCommand::Subagent { session_id, action }
                            }
                            F::Quit => return Ok(CommandOutcome::ClientLocal { effect: borg_view::wire::ClientEffect::CloseView }),
                            F::NewSession => {
                                let mut request = scope_registration(context.session_store.as_ref(), session_id).await?.context("session launch configuration unavailable")?;
                                request.request_id = viewer.command_id;
                                request.initial_prompt = None;
                                request.cwd = validate_host_cwd(&context.config.roots, &request.cwd)?;
                                HostCommand::Launch { session_id: viewer.command_id, request: Box::new(request), attachment: None }
                            }
                            F::RecallQueuedPrompt(message_id) => HostCommand::RecallQueuedPrompt { session_id, message_id },
                            F::ApplyAgentTodo { target_session_id, action } => HostCommand::AgentTodo { session_id, target_session_id, action },
                            F::RunExtension { command, arguments } => HostCommand::ExtensionCommand { session_id, invocation_id: viewer.command_id, command, arguments },
                            F::SetModel { provider, model } => HostCommand::Configure { session_id, action: crate::SessionConfigAction::SetProvider { provider, model: Some(model) } },
                            F::SetPermission(permission_mode) => HostCommand::Configure { session_id, action: crate::SessionConfigAction::SetPermissionMode { permission_mode } },
                            F::SetLanguage(language) => HostCommand::Configure { session_id, action: crate::SessionConfigAction::SetResponseLanguage { language } },
                            F::SetEffort(effort) => HostCommand::Configure { session_id, action: crate::SessionConfigAction::SetEffort { effort } },
                            F::SetFast(enabled) => HostCommand::Configure { session_id, action: crate::SessionConfigAction::SetFast { enabled } },
                            F::SetUltrafast(enabled) => HostCommand::Configure { session_id, action: crate::SessionConfigAction::SetUltrafast { enabled } },
                            _ => bail!("slash intent requires client-local behavior or revision-bound approval; use typed control"),
                        }
                    }
                };
                let mut command = command;
                let receipt = match &mut command {
                    HostCommand::Approve { acknowledgement, .. }
                    | HostCommand::RespondToProviderInteraction { acknowledgement, .. } => {
                        let (ack, receipt) = crate::ApprovalAcknowledgement::channel();
                        *acknowledgement = Some(ack);
                        Some(receipt)
                    }
                    _ => None,
                };
                approval_unconfirmed = receipt.is_some();
                ensure!(dispatch(context.clone(), command).await, "command admission interrupted");
                if let Some(receipt) = receipt {
                    let actor_result = tokio::time::timeout(Duration::from_secs(30), receipt).await
                        .context("approval actor receipt timeout")?
                        .context("approval actor stopped without receipt")?;
                    approval_unconfirmed = false;
                    actor_result.map_err(anyhow::Error::msg)?;
                }
                Ok::<_, anyhow::Error>(CommandOutcome::Applied)
            }
            .await;
            if approval_unconfirmed {
                // Preserve Started/InDoubt: loss of the actor receipt is not a definitive rejection.
                return Err(translate
                    .err()
                    .unwrap_or_else(|| anyhow::anyhow!("approval receipt lost")));
            }
            let outcome = match translate {
                Ok(outcome) => outcome,
                Err(error) => CommandOutcome::Rejected {
                    code: "unsupported_or_interrupted".into(),
                    message: error.to_string(),
                },
            };
            ledger
                .finish(
                    context.config.host_id,
                    viewer.command_id,
                    &serde_json::to_vec(&outcome)?,
                )
                .await?;
            outcome
        }
    };
    Ok(ServerFrame::Result {
        command_id: viewer.command_id.to_string(),
        scope: viewer.scope,
        cursor: Cursor {
            epoch: head.epoch,
            revision: head.revision.to_string(),
        },
        outcome,
    })
}

tokio::task_local! { static OWNER_NOT_AFTER: Option<i64>; }

fn owner_effect_id(command: &HostCommand) -> Option<Uuid> {
    match command {
        HostCommand::WorkspaceFilesystem { request } => Some(request.request_id),
        HostCommand::WorkspaceCommand { request } => Some(request.request_id),
        HostCommand::ShellCommand { request } => Some(request.request_id),
        HostCommand::OpenTerminal { request } => Some(request.request_id),
        _ => None,
    }
}

fn validate_owner_deadline(command: &HostCommand, not_after: Option<i64>, now: i64) -> Result<()> {
    let fenced = matches!(
        command,
        HostCommand::Approve { .. }
            | HostCommand::RespondToProviderInteraction { .. }
            | HostCommand::Subagent {
                action: crate::SubagentAction::Approve { .. },
                ..
            }
    );
    ensure!(
        !fenced || not_after.is_some(),
        "approval or question command requires a deadline"
    );
    if let Some(deadline) = not_after {
        ensure!(deadline > now, "owner command deadline expired");
        ensure!(
            !fenced || deadline <= now.saturating_add(15),
            "approval deadline exceeds 15-second window"
        );
    }
    Ok(())
}

fn check_owner_deadline(command: &HostCommand) -> Result<()> {
    if let Ok(deadline) = OWNER_NOT_AFTER.try_with(|deadline| *deadline) {
        validate_owner_deadline(command, deadline, Utc::now().timestamp())?;
    }
    Ok(())
}

async fn terminal_owner_effect(
    context: &DispatchContext,
    command: &HostCommand,
) -> Result<Option<serde_json::Value>> {
    macro_rules! terminal {
        ($request:expr, $response:ty) => {
            match context
                .receipts
                .load::<_, $response>($request.request_id, $request)
                .await?
            {
                ReceiptState::Terminal(response) => Some(serde_json::to_value(response)?),
                ReceiptState::Conflict | ReceiptState::Corrupt => {
                    bail!("operation receipt conflicts or is corrupt")
                }
                _ => None,
            }
        };
    }
    Ok(match command {
        HostCommand::ShellCommand { request } => terminal!(request, HostShellCommandResponse),
        HostCommand::WorkspaceCommand { request } => terminal!(request, WorkspaceCommandResponse),
        HostCommand::WorkspaceFilesystem { request } => {
            terminal!(request, WorkspaceFilesystemResponse)
        }
        HostCommand::OpenTerminal { request } => terminal!(request, OpenTerminalResponse),
        _ => None,
    })
}

fn owner_frame(command_id: String, outcome: serde_json::Value) -> crate::auth::TunnelFrame {
    if outcome.get("status").and_then(serde_json::Value::as_str) == Some("accepted") {
        crate::auth::TunnelFrame::HostCommandAccepted { command_id }
    } else {
        crate::auth::TunnelFrame::HostCommandResult {
            command_id,
            outcome,
            error: None,
        }
    }
}

async fn owner_command(
    ledger: &crate::command_ledger::CommandLedger,
    context: DispatchContext,
    command_id: String,
    command: HostCommand,
    not_after: Option<i64>,
) -> crate::auth::TunnelFrame {
    let run = async {
        let host = context.config.host_id;
        let id = Uuid::parse_str(&command_id)?;
        let encoded = serde_json::to_vec(&command)?;
        let admission = ledger.admit(host, id, "host", "owner:trusted-relay", &encoded).await?;
        if let crate::command_ledger::Admission::Terminal(bytes) = admission {
            return Ok(owner_frame(command_id.clone(), serde_json::from_slice(&bytes)?));
        }
        let validation = validate_owner_deadline(&command, not_after, Utc::now().timestamp()).and_then(|()| {
            ensure!(owner_effect_id(&command).is_none_or(|request| request == id), "owner command ID differs from effect request ID");
            Ok(())
        });
        if let Err(error) = validation {
            let outcome = serde_json::json!({"status":"rejected","error":error.to_string(),"retryable":false});
            if matches!(admission, crate::command_ledger::Admission::New) { ledger.finish(host, id, &serde_json::to_vec(&outcome)?).await?; }
            return Ok(owner_frame(command_id.clone(), outcome));
        }
        if let HostCommand::Prompt { session_id, message_id, .. } = &command {
            ledger.bind_prompt(host, id, *session_id, *message_id).await?;
        }
        if owner_effect_id(&command).is_some() {
            if let Some(outcome) = terminal_owner_effect(&context, &command).await? {
                ensure!(upload_host_action_result(&context.client, &context.config, "", &command, id, &outcome).await, "terminal operation publication interrupted");
                return Ok(owner_frame(command_id.clone(), outcome));
            }
            if matches!(admission, crate::command_ledger::Admission::InDoubt) {
                if context.receipts.queued_host_operation(host, id).await?.is_some() {
                    return Ok(crate::auth::TunnelFrame::HostCommandAccepted { command_id: command_id.clone() });
                }
                let outcome = serde_json::json!({"status":"interrupted","retryable":false});
                ledger.finish(host, id, &serde_json::to_vec(&outcome)?).await?;
                return Ok(owner_frame(command_id.clone(), outcome));
            }
            ensure!(OWNER_NOT_AFTER.scope(not_after, dispatch(context.clone(), command)).await, "operation admission interrupted; unsafe replay refused");
            if let Some(bytes) = ledger.terminal(host, id, "host", "owner:trusted-relay", &encoded).await? {
                return Ok(owner_frame(command_id.clone(), serde_json::from_slice(&bytes)?));
            }
            return Ok(crate::auth::TunnelFrame::HostCommandAccepted { command_id: command_id.clone() });
        }
        let outcome = if matches!(admission, crate::command_ledger::Admission::InDoubt) {
            if let HostCommand::Prompt { session_id, message_id, text, attachments, delivery, .. } = &command {
                if context.session_store.contains_message(*session_id, *message_id).await? {
                    admit_remote_prompt(context.session_store.as_ref(), *session_id, *message_id, text, attachments, *delivery).await?;
                } else { ensure!(OWNER_NOT_AFTER.scope(not_after, dispatch(context, command)).await, "prompt retry interrupted"); }
                serde_json::json!({"status":"accepted"})
            } else { serde_json::json!({"status":"interrupted","retryable":false}) }
        } else {
            let handled = OWNER_NOT_AFTER.scope(not_after, dispatch(context, command)).await;
            let outcome = serde_json::json!({"status":if handled {"accepted"} else {"interrupted"},"retryable":false});
            ledger.finish(host, id, &serde_json::to_vec(&outcome)?).await?;
            outcome
        };
        Ok::<_, anyhow::Error>(owner_frame(command_id.clone(), outcome))
    }.await;
    run.unwrap_or_else(|error| crate::auth::TunnelFrame::HostCommandResult {
        command_id,
        outcome: serde_json::Value::Null,
        error: Some(error.to_string()),
    })
}

fn deferred_host_operation_id(command: &HostCommand) -> Option<Uuid> {
    match command {
        HostCommand::ShellCommand { request } => Some(request.request_id),
        HostCommand::WorkspaceCommand { request } => Some(request.request_id),
        _ => None,
    }
}

async fn run_host_operation_loop(
    client: Client,
    config: HostConfig,
    receipts: Arc<dyn ReceiptBackend>,
    session_root: PathBuf,
) {
    enum Step {
        Progress,
        Idle,
        Retry,
    }
    let wakes = host_transport::get(config.host_id)
        .map(|transport| transport.wakes())
        .unwrap_or_default();
    loop {
        let result: Result<Step> = async {
            // A receipt marked Started is only indeterminate after its worker
            // has released ownership. Never race another live host worker.
            let Some(_owner) =
                SessionWriterLease::try_acquire(session_root.join("host-operations.lock"))?
            else {
                return Ok(Step::Retry);
            };
            let Some((request_id, value)) = receipts.next_host_operation(config.host_id).await?
            else {
                return Ok(Step::Idle);
            };
            let command = match serde_json::from_value::<HostCommand>(value) {
                Ok(command) if deferred_host_operation_id(&command) == Some(request_id) => command,
                _ => {
                    receipts.quarantine_host_operation(config.host_id, request_id).await?;
                    tracing::error!(%request_id, "unsupported host operation quarantined; retained in host_operation_queue");
                    return Ok(Step::Progress);
                }
            };
            let Some(_operation_owner) = SessionWriterLease::try_acquire(
                session_root.join(format!("host-operation-{request_id}.lock")),
            )? else { return Ok(Step::Retry) };
            if !execute_host_operation(&client, &config, receipts.as_ref(), &command).await {
                return Ok(Step::Retry);
            }
            receipts
                .finish_host_operation(config.host_id, request_id)
                .await?;
            Ok(Step::Progress)
        }
        .await;
        match result {
            Ok(Step::Progress) => continue,
            // Enqueueing an operation wakes this loop; an empty queue waits.
            Ok(Step::Idle) => wakes.operations.notified().await,
            Ok(Step::Retry) => tokio::time::sleep(Duration::from_secs(1)).await,
            Err(error) => {
                tracing::warn!(%error, "host operation remains queued for recovery");
                tokio::time::sleep(Duration::from_secs(1)).await;
            }
        }
    }
}

async fn cancel_queued_workspace_command(
    receipts: &dyn ReceiptBackend,
    host_id: Uuid,
    session_root: &Path,
    request_id: Uuid,
) -> Result<()> {
    // Do not overwrite a live execution or interpret its Started receipt as a crash.
    let owner = SessionWriterLease::try_acquire(
        session_root.join(format!("host-operation-{request_id}.lock")),
    )?;
    let Some(value) = receipts.queued_host_operation(host_id, request_id).await? else {
        return Ok(());
    };
    let Ok(HostCommand::WorkspaceCommand { request }) = serde_json::from_value(value) else {
        return Ok(());
    };
    if request.request_id != request_id {
        receipts
            .quarantine_host_operation(host_id, request_id)
            .await?;
        tracing::error!(%request_id, "queued cancellation identity mismatch; operation quarantined");
        return Ok(());
    }
    if matches!(
        receipts
            .load::<_, WorkspaceCommandResponse>(request_id, &request)
            .await?,
        ReceiptState::Missing
    ) {
        ensure!(
            owner.is_some(),
            "workspace admission or cancellation is still being persisted"
        );
        receipts
            .finish(
                request_id,
                &request,
                &WorkspaceCommandResponse {
                    request_id,
                    workspace_id: request.workspace_id,
                    outcome: WorkspaceCommandOutcome::Failure {
                        code: WorkspaceCommandErrorCode::Cancelled,
                        message: "workspace command cancelled before execution".to_string(),
                        retryable: false,
                    },
                },
            )
            .await?;
    }
    Ok(())
}

async fn execute_host_operation(
    client: &Client,
    config: &HostConfig,
    receipts: &dyn ReceiptBackend,
    command: &HostCommand,
) -> bool {
    match command {
        HostCommand::ShellCommand { request } => {
            let Some(response) = shell_command_response(receipts, config, request).await else {
                return false;
            };
            upload_host_action_result(
                client,
                config,
                "/api/remote/host/shell-command-results",
                command,
                response.request_id,
                &response,
            )
            .await
        }
        HostCommand::WorkspaceCommand { request } => {
            let Some(response) = workspace_command_response(receipts, config, request).await else {
                return false;
            };
            upload_host_action_result(
                client,
                config,
                "/api/remote/host/workspace-command-results",
                command,
                response.request_id,
                &response,
            )
            .await
        }
        _ => false,
    }
}

async fn run_host_workspace_recovery_loop(
    client: Client,
    config: HostConfig,
    store: Arc<dyn SessionStore>,
    sessions: Arc<Mutex<HashMap<Uuid, mpsc::Sender<HostCommand>>>>,
    journal_root: PathBuf,
) {
    let workspace = loop {
        match store.workspace_store().await {
            Ok(Some(workspace)) => break workspace,
            result => {
                let error = result.err();
                tracing::warn!(
                    ?error,
                    "cannot open hosted message recovery store; retrying"
                );
                tokio::time::sleep(Duration::from_secs(2)).await;
            }
        }
    };
    let wakes = host_transport::get(config.host_id)
        .map(|transport| transport.wakes())
        .unwrap_or_default();
    // Listen before the first scan so a message committed in between still wakes it.
    let mut outbox = match store.postgres_authority() {
        Some(authority) => {
            let listener = async {
                let mut listener =
                    sqlx::postgres::PgListener::connect_with(&authority.pool).await?;
                listener.listen("borg_workspace_outbox").await?;
                Ok::<_, sqlx::Error>(listener)
            }
            .await;
            match listener {
                Ok(listener) => Some(listener),
                Err(error) => {
                    tracing::warn!(%error, "hosted message recovery cannot listen for new messages");
                    None
                }
            }
        }
        None => None,
    };
    let mut after = None;
    let mut retry_at = HashMap::new();
    let mut syncs: HashMap<Uuid, JournalSync> = HashMap::new();
    loop {
        retry_at.retain(|_, retry| *retry > Instant::now());
        syncs.retain(|_, sync| {
            sync.workspace_retry_at
                .retain(|_, retry| *retry > Instant::now());
            !sync.workspace_retry_at.is_empty()
        });
        let pending = match store
            .pending_host_workspace_messages(config.host_id, after, 32)
            .await
        {
            Ok(pending) => pending,
            Err(error) => {
                tracing::warn!(%error, "cannot scan pending hosted messages; retrying");
                tokio::time::sleep(Duration::from_secs(2)).await;
                continue;
            }
        };
        after = if pending.len() == 32 {
            pending.last().copied()
        } else {
            None
        };
        for session_id in pending {
            if sessions.lock().await.contains_key(&session_id)
                || retry_at
                    .get(&session_id)
                    .is_some_and(|retry| Instant::now() < *retry)
            {
                continue;
            }
            let sync = syncs
                .entry(session_id)
                .or_insert_with(|| JournalSync::new(false, journal_root.clone()));
            let result = tokio::time::timeout(
                Duration::from_secs(10),
                recover_host_workspace_messages(
                    &client,
                    &config,
                    store.as_ref(),
                    workspace.as_ref(),
                    session_id,
                    sync,
                ),
            )
            .await;
            match result {
                Ok(Ok(())) => {}
                error => {
                    tracing::warn!(?error, %session_id, "hosted message recovery deferred");
                    retry_at.insert(session_id, Instant::now() + Duration::from_secs(10));
                }
            }
        }
        if after.is_some() {
            continue;
        }
        // Undelivered messages appear when a session ends or the relay comes
        // back; between those, only deferred sessions owe a timed retry.
        let retry = retry_at
            .values()
            .chain(
                syncs
                    .values()
                    .flat_map(|sync| sync.workspace_retry_at.values()),
            )
            .min()
            .copied();
        tokio::select! {
            _ = wakes.recovery.notified() => {}
            notification = async {
                match outbox.as_mut() {
                    Some(listener) => listener.recv().await,
                    None => std::future::pending().await,
                }
            } => {
                // The listener reconnects itself; a lost notification is
                // covered by rescanning now.
                if let Err(error) = notification {
                    tracing::warn!(%error, "hosted message recovery notification failed");
                }
            }
            _ = async {
                match retry {
                    Some(retry) => tokio::time::sleep_until(tokio::time::Instant::from_std(retry)).await,
                    None => std::future::pending().await,
                }
            } => {}
        }
    }
}

async fn recover_host_workspace_messages(
    client: &Client,
    config: &HostConfig,
    store: &dyn SessionStore,
    workspace: &dyn WorkspaceStore,
    session_id: Uuid,
    sync: &mut JournalSync,
) -> Result<()> {
    ensure_host_launch_owner(client, config, store, session_id).await?;
    let binding = store
        .workspace_binding(session_id)
        .await?
        .context("hosted session has no workspace binding")?;
    ensure!(
        binding.host_id == Some(config.host_id),
        "session belongs to another enrolled host"
    );
    let Some(StoredHostLaunch::Launch(metadata)) = load_launch_metadata(store, session_id).await?
    else {
        bail!("session has no executable hosted launch");
    };
    let execution_workspace = metadata
        .attachment
        .as_ref()
        .and_then(|attachment| attachment.workspace_id);
    ensure!(
        execution_workspace.is_none_or(|id| id == binding.workspace_id),
        "hosted workspace binding changed"
    );
    let participant = metadata
        .attachment
        .as_ref()
        .and_then(|attachment| attachment.participant_id);
    ensure!(
        execution_workspace.is_some() == participant.is_some(),
        "incoherent hosted workspace identity"
    );
    ensure!(
        binding.participant_id == participant.unwrap_or(session_id),
        "hosted participant binding changed"
    );
    if let Some(identity) = metadata
        .attachment
        .as_ref()
        .and_then(|attachment| attachment.host_identity.as_ref())
    {
        ensure!(
            identity.host_id == config.host_id,
            "hosted launch belongs to another enrolled host"
        );
    }
    // Upload only: no inbox import, actor startup, provider admission, or lease renewal.
    let later = Instant::now() + Duration::from_secs(60);
    // Reload durable cursors after every attempt, including a cancelled checkpoint.
    // The caller keeps workspace backoffs across attempts/timeouts.
    sync.uploaded_workspace_sequences = store
        .host_workspace_cursors(config.host_id, session_id)
        .await?;
    sync.workspace_relay_available = execution_workspace.is_some();
    sync.instance_relay_available = true;
    sync.next_workspace_roster_sync = later;
    sync.next_instance_directory_sync = later;
    sync.next_inbox_sync = later;
    flush_host_workspace_messages(
        client,
        config,
        store,
        Some(workspace),
        session_id,
        execution_workspace,
        sync,
    )
    .await?;
    Ok(())
}

async fn flush_host_workspace_messages(
    client: &Client,
    config: &HostConfig,
    store: &dyn SessionStore,
    workspace: Option<&dyn WorkspaceStore>,
    session_id: Uuid,
    execution_workspace: Option<Uuid>,
    sync: &mut JournalSync,
) -> Result<bool> {
    let before = sync.uploaded_workspace_sequences.clone();
    let result = flush_workspace_messages(
        client,
        config,
        store,
        workspace,
        session_id,
        execution_workspace,
        sync,
    )
    .await;
    if sync.uploaded_workspace_sequences != before
        && let Err(error) = store
            .acknowledge_host_workspaces(
                config.host_id,
                session_id,
                &sync.uploaded_workspace_sequences,
            )
            .await
    {
        sync.uploaded_workspace_sequences = before;
        // Retry the checkpoint without masking a fatal upload rejection.
        result?;
        return Err(error);
    }
    result
}

async fn run_host_heartbeat_loop(
    client: Client,
    config: HostConfig,
    sessions: Arc<Mutex<HashMap<Uuid, mpsc::Sender<HostCommand>>>>,
    mut capabilities: HostCapabilities,
) {
    let mut capabilities_probed_at = Instant::now();
    let mut retry = RemoteRetryBackoff::default();
    let mut service_ready = notify_systemd(&[
        "--ready",
        "--status=Borg Remote initialized; connecting to its control plane",
    ])
    .await;
    loop {
        if capabilities_probed_at.elapsed() >= Duration::from_secs(300) {
            capabilities =
                probe_capabilities_with_profile(config.roots.clone(), config.execution_profile)
                    .await;
            capabilities.resource_limits = config.resource_limits.clone();
            capabilities_probed_at = Instant::now();
        }
        let active_session_ids = sessions.lock().await.keys().copied().collect();
        match heartbeat(
            &client,
            &config,
            capabilities.clone(),
            active_session_ids,
            None,
        )
        .await
        {
            Ok(()) => {
                retry.reset();
                if !service_ready {
                    service_ready = notify_systemd(&[
                        "--ready",
                        "--status=Borg Remote connected to its control plane",
                    ])
                    .await;
                }
                if service_ready {
                    let _ = notify_systemd(&[
                        "--status=Borg Remote connected to its control plane",
                        "WATCHDOG=1",
                    ])
                    .await;
                }
                tokio::time::sleep(HOST_HEARTBEAT_INTERVAL).await;
            }
            Err(error) => {
                let delay = retry.next_delay(None).min(HOST_HEARTBEAT_RETRY_MAX);
                tracing::warn!(
                    %error,
                    retry_seconds = delay.as_secs(),
                    "remote host heartbeat failed; retrying"
                );
                if service_ready {
                    let _ = notify_systemd(&[
                        "--status=Borg Remote control plane unavailable; retrying",
                        "WATCHDOG=1",
                    ])
                    .await;
                }
                tokio::time::sleep(delay).await;
            }
        }
    }
}

async fn notify_systemd(arguments: &[&str]) -> bool {
    if std::env::var_os("NOTIFY_SOCKET").is_none() {
        return true;
    }
    match tokio::time::timeout(
        SYSTEMD_NOTIFY_TIMEOUT,
        Command::new("systemd-notify").args(arguments).status(),
    )
    .await
    {
        Ok(Ok(status)) if status.success() => true,
        Ok(Ok(status)) => {
            tracing::warn!(
                ?status,
                "systemd-notify rejected the Borg Remote health update"
            );
            false
        }
        Ok(Err(error)) => {
            tracing::warn!(%error, "failed to run systemd-notify for Borg Remote");
            false
        }
        Err(_) => {
            tracing::warn!("systemd-notify timed out for Borg Remote");
            false
        }
    }
}

pub(crate) fn spawn_transport_task<F>(future: F) -> tokio::task::JoinHandle<F::Output>
where
    F: std::future::Future + Send + 'static,
    F::Output: Send + 'static,
{
    host_transport::spawn(future)
}

pub(crate) async fn scope_registration(
    store: &dyn SessionStore,
    session: Uuid,
) -> Result<Option<LaunchSession>> {
    let root = store.owning_root_session(session).await?.unwrap_or(session);
    let Some(StoredHostLaunch::Launch(metadata)) = load_launch_metadata(store, root).await? else {
        return Ok(None);
    };
    let mut request = metadata.request;
    let state = store.state(session).await?;
    if let Some(configuration) = state.configuration {
        request.cwd = configuration.cwd;
        request.provider = configuration.provider;
        request.model = configuration.model;
        request.effort = configuration.effort;
        request.fast = Some(configuration.fast);
        request.ultrafast = Some(configuration.ultrafast);
        request.permission_mode = configuration.permission_mode;
        request.response_language = configuration.response_language;
    } else if session != root {
        // A child must have its own committed configuration before registration.
        return Ok(None);
    }
    request.name = state
        .title
        .or(state.imported_title)
        .or_else(|| (session == root).then(|| request.name.clone()).flatten());
    request.request_id = session;
    request.initial_prompt = None;
    Ok(Some(request))
}

pub(crate) async fn register_child(
    host: Uuid,
    session_id: Uuid,
    request: LaunchSession,
) -> Result<()> {
    host_transport::get(host)?
        .register(session_id, request)
        .await
}

/// Register an existing canonical journal with the enrolled host publisher.
/// Commits metadata and a wakeup on the selected PostgreSQL authority; never
/// bootstraps a provider or takes ownership of the session's writer.
pub async fn register_existing_session(
    config_path: &Path,
    store: Arc<dyn SessionStore>,
    session_id: Uuid,
    request: LaunchSession,
) -> Result<()> {
    let config: HostConfig = serde_json::from_slice(&fs::read(config_path)?)?;
    config.validate()?;
    ensure_execution_boundary(&config)?;
    let authority = store
        .postgres_authority()
        .context("local remote registration requires PostgreSQL authority")?;
    ensure!(
        store.contains_session(session_id).await?,
        "local mirror session does not exist"
    );
    let rejection =
        persist_launch_metadata_as(&config, store.as_ref(), session_id, &request, None, true)
            .await?;
    ensure!(
        rejection.is_none(),
        "local session registration rejected: {}",
        rejection.unwrap_or_default()
    );
    // A wakeup is only a hint: the host restores its catalog from the same PG authority.
    sqlx::query("select pg_notify('borg_session_committed',$1)")
        .bind(session_id.to_string())
        .execute(&authority.pool)
        .await?;
    Ok(())
}

/// Keep the terminal-owned registration handoff alive until shutdown.
/// Commands continue through the canonical local-control endpoint.
pub async fn mirror_local_session(
    config_path: &Path,
    store: Arc<dyn crate::SessionStore>,
    session_id: Uuid,
    request: LaunchSession,
    commands: mpsc::Sender<HostCommand>,
    mut shutdown: watch::Receiver<bool>,
) -> Result<()> {
    register_existing_session(config_path, store, session_id, request).await?;
    let _ = commands; // The canonical local-control socket remains the actor ingress.
    while !*shutdown.borrow() {
        if shutdown.changed().await.is_err() {
            break;
        }
    }
    Ok(())
}

async fn heartbeat(
    client: &Client,
    config: &HostConfig,
    capabilities: HostCapabilities,
    active_session_ids: Vec<Uuid>,
    session_id: Option<Uuid>,
) -> Result<()> {
    let _ = (client, session_id);
    host_transport::get(config.host_id)?
        .outbound
        .send(crate::auth::TunnelFrame::Heartbeat {
            heartbeat: HostHeartbeat {
                name: config.name.clone(),
                platform: platform(),
                hostname: hostname(),
                capabilities,
                acknowledged_command_sequence: 0,
                acknowledged_command_claim_token: None,
                active_session_ids,
                identity: Some(RemoteHostIdentity {
                    host_id: config.host_id,
                    hostname: hostname(),
                    platform: platform(),
                }),
            },
        })
        .await?;
    Ok(())
}

#[derive(Clone)]
struct DispatchContext {
    client: Client,
    config: HostConfig,
    session_root: PathBuf,
    sessions: Arc<Mutex<HashMap<Uuid, mpsc::Sender<HostCommand>>>>,
    session_store: Arc<dyn SessionStore>,
    receipts: Arc<dyn ReceiptBackend>,
    executor_factory: HostExecutorFactory,
}

async fn dispatch(context: DispatchContext, command: HostCommand) -> bool {
    let DispatchContext {
        client,
        config,
        session_root,
        sessions,
        session_store,
        receipts,
        executor_factory,
    } = context;
    if let Err(error) = check_owner_deadline(&command) {
        tracing::warn!(%error, "expired owner command refused before mutation");
        return false;
    }
    if !matches!(command, HostCommand::Launch { .. })
        && let Some(session_id) = command.session_id()
    {
        let root = match session_store.owning_root_session(session_id).await {
            Ok(root) => root.unwrap_or(session_id),
            Err(error) => {
                tracing::warn!(%error, "cannot resolve local session owner");
                return false;
            }
        };
        let socket = crate::session_control_socket_path(&session_root, root);
        if crate::session_control_socket_is_reachable(&socket).await {
            match session_store.host_launch_owner(root).await {
                Ok(Some((host, origin)))
                    if host == config.host_id
                        && host_relay_origin(&config).ok().as_ref() == Some(&origin) => {}
                _ => return false,
            }
            if let HostCommand::Prompt {
                session_id,
                message_id,
                text,
                attachments,
                delivery,
                ..
            } = &command
            {
                match session_store
                    .contains_message(*session_id, *message_id)
                    .await
                {
                    Ok(true) => {
                        return admit_remote_prompt(
                            session_store.as_ref(),
                            *session_id,
                            *message_id,
                            text,
                            attachments,
                            *delivery,
                        )
                        .await
                        .is_ok();
                    }
                    Ok(false) => {}
                    Err(_) => return false,
                }
            }

            if check_owner_deadline(&command).is_err() {
                return false;
            }
            return crate::send_local_session_command(&socket, session_id, command)
                .await
                .is_ok();
        }
    }
    if let Some(request_id) = deferred_host_operation_id(&command) {
        return match receipts
            .enqueue_host_command(config.host_id, request_id, &command)
            .await
        {
            Ok(()) => {
                if let Ok(transport) = host_transport::get(config.host_id) {
                    transport.wakes().operations.notify_one();
                }
                true
            }
            Err(error) => {
                tracing::warn!(%error, %request_id, "failed to durably enqueue host operation; retaining relay command");
                false
            }
        };
    }
    if let HostCommand::OpenTerminal { request } = &command {
        let Some(response) = open_terminal_response(receipts.as_ref(), &config, request).await
        else {
            return false;
        };
        return upload_host_action_result(
            &client,
            &config,
            "/api/remote/host/terminal-results",
            &command,
            response.request_id,
            &response,
        )
        .await;
    }
    if let HostCommand::WorkspaceFilesystem { request } = &command {
        let Some(response) = filesystem_response(receipts.as_ref(), &config, request).await else {
            return false;
        };
        return upload_host_action_result(
            &client,
            &config,
            "/api/remote/host/filesystem-results",
            &command,
            response.request_id,
            &response,
        )
        .await;
    }
    if let HostCommand::CancelWorkspaceFilesystem { .. } = &command {
        return true;
    }
    if let HostCommand::CancelWorkspaceCommand { request_id } = &command {
        return match cancel_queued_workspace_command(
            receipts.as_ref(),
            config.host_id,
            &session_root,
            *request_id,
        )
        .await
        {
            Ok(()) => true,
            Err(error) => {
                tracing::warn!(%error, %request_id, "failed to persist queued workspace cancellation; retaining relay command");
                false
            }
        };
    }
    if let Some(session_id) = command.session_id() {
        let authorized: Result<()> = async {
            validate_stored_host_identity(&config, session_store.as_ref(), session_id).await?;
            ensure!(
                session_store
                    .load_host_launch_metadata(session_id)
                    .await?
                    .is_none()
                    || session_store.host_launch_owner(session_id).await?.is_some(),
                "legacy launch awaits background relay ownership verification"
            );
            Ok(())
        }
        .await;
        if let Err(error) = authorized {
            tracing::warn!(%error, %session_id, "stored session host identity rejected command; retaining it");
            return false;
        }
    }
    if let HostCommand::Launch {
        session_id,
        request,
        attachment,
    } = command
    {
        let rejection = match persist_launch_metadata(
            &config,
            session_store.as_ref(),
            session_id,
            &request,
            attachment.as_ref(),
        )
        .await
        {
            Ok(rejection) => rejection,
            Err(error) => {
                tracing::error!(%error, %session_id, "failed to persist remote session launch");
                return false;
            }
        };
        let at_capacity = {
            let sessions_guard = sessions.lock().await;
            if sessions_guard.contains_key(&session_id) {
                return true;
            }
            sessions_guard.len() >= config.resource_limits.max_concurrent_sessions as usize
        };
        match stored_host_session_state(session_store.as_ref(), session_id).await {
            Ok(Some(state))
                if state.started_at.is_none()
                    && matches!(
                        state.status,
                        Some(crate::SessionStatus::Failed | crate::SessionStatus::Stopped)
                    ) =>
            {
                return reject_host_launch(
                    &client,
                    &config,
                    &session_root,
                    session_store.as_ref(),
                    session_id,
                    "launch already rejected",
                )
                .await;
            }
            Ok(Some(state))
                if matches!(
                    state.status,
                    Some(
                        crate::SessionStatus::Failed
                            | crate::SessionStatus::Stopped
                            | crate::SessionStatus::Completed
                    )
                ) =>
            {
                return settle_inactive_host_session(
                    &config,
                    session_store.as_ref(),
                    &session_root,
                    session_id,
                    false,
                )
                .await;
            }
            Ok(_) => {}
            Err(error) => {
                tracing::warn!(%error, %session_id, "failed to read launch state; retaining command for retry");
                return false;
            }
        }
        let rejection = rejection.or_else(|| validate_host_cwd(&config.roots, &request.cwd)
            .err().map(|error| error.to_string()))
            .or_else(|| at_capacity.then(|| format!("remote host is at its {} session limit; stop another session and submit a new launch", config.resource_limits.max_concurrent_sessions)));
        if let Some(reason) = rejection {
            return reject_host_launch(
                &client,
                &config,
                &session_root,
                session_store.as_ref(),
                session_id,
                &reason,
            )
            .await;
        }
        if let Err(error) = session_store.begin_host_bootstrap(session_id).await {
            tracing::warn!(%error, %session_id, "failed to durably admit host bootstrap; retaining launch");
            return false;
        }
        spawn_host_session(
            client,
            config,
            session_root,
            sessions,
            Arc::clone(&executor_factory),
            HostSessionLaunch {
                session_id,
                request: *request,
                attachment,
            },
            Arc::clone(&session_store),
        )
        .await;
        return true;
    }
    if let Some(session_id) = command.session_id() {
        let metadata = match load_launch_metadata(session_store.as_ref(), session_id).await {
            Ok(Some(StoredHostLaunch::Launch(metadata))) => Some(*metadata),
            Ok(Some(StoredHostLaunch::Rejected { .. })) => {
                return settle_inactive_host_session(
                    &config,
                    session_store.as_ref(),
                    &session_root,
                    session_id,
                    false,
                )
                .await;
            }
            Ok(None) => None,
            Err(error) => {
                tracing::error!(%error, %session_id, "failed to load stored launch metadata");
                return false;
            }
        };
        let attachment = metadata
            .as_ref()
            .and_then(|metadata| metadata.attachment.as_ref());
        if matches!(
            command,
            HostCommand::TeamPrompt { .. }
                | HostCommand::Broadcast { .. }
                | HostCommand::BroadcastInstances { .. }
        ) {
            tracing::warn!(%session_id, "rejected host-local team prompt from remote command queue");
            return true;
        }
        if let Some(attachment) = attachment.as_ref()
            && let Err(error) = authorize_workspace_command(attachment, &command)
        {
            tracing::warn!(%error, %session_id, "rejected unauthorized workspace command");
            // The command was handled by rejecting it. Leaving its envelope
            // unacknowledged would make the relay retry the same denied
            // command forever and head-of-line block every later command.
            return true;
        }
        let state = match stored_host_session_state(session_store.as_ref(), session_id).await {
            Ok(state) => state,
            Err(error) => {
                tracing::warn!(%error, %session_id, "failed to read launch state; retaining command for retry");
                return false;
            }
        };
        let existing = { sessions.lock().await.get(&session_id).cloned() };
        let session = match existing {
            Some(session) => Some(session),
            None => {
                if let Some(metadata) = metadata {
                    let terminal = state.as_ref().is_some_and(|state| {
                        matches!(
                            state.status,
                            Some(
                                crate::SessionStatus::Failed
                                    | crate::SessionStatus::Stopped
                                    | crate::SessionStatus::Completed
                            )
                        )
                    });
                    if terminal {
                        return settle_inactive_host_session(
                            &config,
                            session_store.as_ref(),
                            &session_root,
                            session_id,
                            false,
                        )
                        .await;
                    }
                    if let Err(error) = validate_workspace_attachment(
                        &config,
                        session_id,
                        metadata.attachment.as_ref(),
                        false,
                    ) {
                        tracing::error!(%error, %session_id, "stored launch attachment is invalid");
                        return false;
                    }
                    if matches!(command, HostCommand::Stop { .. }) {
                        return settle_inactive_host_session(
                            &config,
                            session_store.as_ref(),
                            &session_root,
                            session_id,
                            true,
                        )
                        .await;
                    }
                    let attachment_error = validate_workspace_attachment(
                        &config,
                        session_id,
                        metadata.attachment.as_ref(),
                        true,
                    )
                    .err();
                    let at_capacity = sessions.lock().await.len()
                        >= config.resource_limits.max_concurrent_sessions as usize;
                    if attachment_error.is_some() || at_capacity {
                        if let HostCommand::Prompt {
                            message_id,
                            text,
                            attachments,
                            delivery,
                            output_schema: None,
                            ..
                        } = &command
                            && state.as_ref().is_some_and(|state| {
                                state.started_at.is_some() && state.configuration.is_some()
                            })
                        {
                            let admitted: Result<bool> = async {
                                admit_remote_prompt(
                                    session_store.as_ref(),
                                    session_id,
                                    *message_id,
                                    text,
                                    attachments,
                                    *delivery,
                                )
                                .await?;
                                // Workspace-only and inherited messages need not have a
                                // local action that restart recovery can discover.
                                Ok(session_store
                                    .contains_message(session_id, *message_id)
                                    .await?
                                    && session_store
                                        .action(session_id, *message_id)
                                        .await?
                                        .is_some())
                            }
                            .await;
                            match admitted {
                                Ok(true) => return true,
                                Ok(false) => {}
                                Err(error) => {
                                    tracing::warn!(%error, %session_id, "cannot durably defer remote prompt")
                                }
                            }
                        }
                        tracing::warn!(%session_id, at_capacity, ?attachment_error, "session restoration is unavailable; retaining non-deferable command");
                        return false;
                    }
                    Some(
                        spawn_host_session(
                            client,
                            config,
                            session_root,
                            sessions,
                            Arc::clone(&executor_factory),
                            HostSessionLaunch {
                                session_id,
                                request: metadata.request,
                                attachment: metadata.attachment,
                            },
                            Arc::clone(&session_store),
                        )
                        .await,
                    )
                } else {
                    None
                }
            }
        };
        let Some(session) = session else {
            tracing::warn!(%session_id, "remote command has no durable launch metadata; retaining it for relay retry");
            return false;
        };
        if let HostCommand::Prompt {
            message_id,
            text,
            attachments,
            delivery,
            ..
        } = &command
        {
            match admit_remote_prompt(
                session_store.as_ref(),
                session_id,
                *message_id,
                text,
                attachments,
                *delivery,
            )
            .await
            {
                Ok(true) => {}
                Ok(false) => return true,
                Err(error) => {
                    tracing::warn!(%error, %session_id, %message_id, "failed prompt admission");
                    return false;
                }
            }
        }
        let permit = match session.reserve().await {
            Ok(permit) => permit,
            Err(error) => {
                tracing::warn!(%error, %session_id, "remote session actor stopped before command admission");
                return false;
            }
        };
        if check_owner_deadline(&command).is_err() {
            return false;
        }
        permit.send(command);
        return true;
    }
    true
}

async fn settle_inactive_host_session(
    config: &HostConfig,
    store: &dyn SessionStore,
    session_root: &Path,
    session_id: Uuid,
    stop: bool,
) -> bool {
    let result: Result<()> = async {
        let _writer = SessionWriterLease::acquire(session_root.join(format!("{session_id}.lock")))?;
        validate_stored_host_identity(config, store, session_id).await?;
        if !store.contains_session(session_id).await? {
            ensure!(stop, "missing terminal session");
            store.create_session(session_id).await?;
        }
        let state = store.state(session_id).await?;
        if !matches!(
            state.status,
            Some(
                crate::SessionStatus::Failed
                    | crate::SessionStatus::Stopped
                    | crate::SessionStatus::Completed
            )
        ) {
            ensure!(stop, "session is no longer terminal");
            store
                .append(SessionEvent::new(
                    session_id,
                    0,
                    crate::SessionEventKind::StatusChanged {
                        lifecycle: Some(crate::SessionStatus::Stopped.into()),
                        status: crate::SessionStatus::Stopped,
                        detail: None,
                    },
                ))
                .await?;
        }
        // The independent hosted-journal worker owns final publication, even
        // when execution capacity is full or the relay is unavailable.
        store.settle_terminal_host_session(session_id).await
    }
    .await;
    match result {
        Ok(()) => true,
        Err(error) => {
            tracing::warn!(%error, %session_id, "cannot settle inactive session; retaining command for retry");
            false
        }
    }
}

async fn stored_host_session_state(
    store: &dyn SessionStore,
    session_id: Uuid,
) -> Result<Option<crate::SessionState>> {
    if store.contains_session(session_id).await? {
        Ok(Some(store.state(session_id).await?))
    } else {
        Ok(None)
    }
}

async fn reject_host_launch(
    client: &Client,
    config: &HostConfig,
    session_root: &Path,
    store: &dyn SessionStore,
    session_id: Uuid,
    reason: &str,
) -> bool {
    let result: Result<()> = async {
        let _writer = SessionWriterLease::acquire(session_root.join(format!("{session_id}.lock")))?;
        ensure_host_launch_owner(client, config, store, session_id).await?;
        ensure!(
            store.host_launch_owner(session_id).await?.is_some(),
            "unverified launch cannot be settled"
        );
        if !store.contains_session(session_id).await? {
            store.create_session(session_id).await?;
        }
        let state = store.state(session_id).await?;
        let terminal = matches!(
            state.status,
            Some(
                crate::SessionStatus::Failed
                    | crate::SessionStatus::Stopped
                    | crate::SessionStatus::Completed
            )
        );
        ensure!(
            state.started_at.is_none() || terminal,
            "cannot reject an already-running session"
        );
        if !terminal {
            store
                .append(SessionEvent::new(
                    session_id,
                    0,
                    crate::SessionEventKind::StatusChanged {
                        lifecycle: Some(crate::SessionStatus::Failed.into()),
                        status: crate::SessionStatus::Failed,
                        detail: Some(reason.to_owned()),
                    },
                ))
                .await?;
        }
        store.settle_terminal_host_session(session_id).await?;
        Ok(())
    }
    .await;
    if let Err(error) = &result {
        tracing::warn!(%error, %session_id, "failed to settle rejected launch");
    }
    result.is_ok()
}

async fn admit_remote_prompt(
    store: &dyn SessionStore,
    session_id: Uuid,
    message_id: Uuid,
    text: &str,
    attachments: &[PathBuf],
    delivery: crate::PromptDelivery,
) -> Result<bool> {
    let workspace_durable = match store.workspace_store().await? {
        Some(workspace) => workspace.contains_message(message_id).await?,
        None => false,
    };
    // A workspace copy does not replace validation of an existing local admission.
    // Action lookup is session-local; inherited and inbox-only messages stay actionless.
    if !workspace_durable || store.action(session_id, message_id).await?.is_some() {
        let event = SessionEvent::new(
            session_id,
            0,
            crate::SessionEventKind::Message {
                message_id,
                actor: crate::EventActor::User,
                text: text.to_string(),
                attachments: attachments.to_vec(),
                status: crate::MessageStatus::Queued,
                delivery: Some(delivery),
            },
        );
        let id = event.id;
        return Ok(store.admit_prompt(event).await?.id == id);
    }
    Ok(false)
}

async fn upload_host_action_result<T: Serialize>(
    client: &Client,
    config: &HostConfig,
    path: &str,
    command: &HostCommand,
    request_id: Uuid,
    response: &T,
) -> bool {
    let _ = (client, path);
    let result = async {
        ensure!(
            owner_effect_id(command) == Some(request_id),
            "terminal operation identity mismatch"
        );
        let transport = host_transport::get(config.host_id)?;
        let ledger = transport.ledger()?;
        let outcome = serde_json::to_value(response)?;
        let encoded = serde_json::to_vec(command)?;
        let result = serde_json::to_vec(&outcome)?;
        match ledger
            .admit(
                config.host_id,
                request_id,
                "host",
                "owner:trusted-relay",
                &encoded,
            )
            .await?
        {
            crate::command_ledger::Admission::Terminal(bytes) => {
                ensure!(bytes == result, "terminal operation result changed")
            }
            _ => {
                if let Err(error) = ledger.finish(config.host_id, request_id, &result).await {
                    ensure!(
                        ledger
                            .terminal(
                                config.host_id,
                                request_id,
                                "host",
                                "owner:trusted-relay",
                                &encoded
                            )
                            .await?
                            == Some(result),
                        "{error}"
                    );
                }
            }
        }
        transport
            .outbound
            .send(crate::auth::TunnelFrame::HostCommandResult {
                command_id: request_id.to_string(),
                outcome,
                error: None,
            })
            .await?;
        Ok::<_, anyhow::Error>(())
    }
    .await;
    if let Err(error) = &result {
        tracing::warn!(%error, "host result publication failed");
    }
    result.is_ok()
}

async fn filesystem_response(
    receipts: &dyn ReceiptBackend,
    config: &HostConfig,
    request: &WorkspaceFilesystemRequest,
) -> Option<WorkspaceFilesystemResponse> {
    let state = match receipts.load(request.request_id, request).await {
        Ok(state) => state,
        Err(error) => {
            tracing::warn!(%error, request_id = %request.request_id, "failed to read filesystem receipt");
            return None;
        }
    };
    match state {
        ReceiptState::Terminal(response) => Some(response),
        ReceiptState::Started => {
            let response = indeterminate_filesystem_response(
                request,
                "the host restarted after this mutation began; Borg will not replay it because its outcome cannot be proven",
            );
            persist_filesystem_terminal(receipts, request, &response).await
        }
        ReceiptState::Conflict => Some(indeterminate_filesystem_response(
            request,
            "request_id was already used for a different filesystem request",
        )),
        ReceiptState::Corrupt if request.operation.is_mutating() => {
            Some(indeterminate_filesystem_response(
                request,
                "the durable mutation receipt is unreadable; Borg will not replay the operation",
            ))
        }
        ReceiptState::Missing | ReceiptState::Corrupt => {
            if request.operation.is_mutating()
                && let Err(error) = receipts.begin(request.request_id, request).await
            {
                tracing::warn!(%error, request_id = %request.request_id, "failed to durably begin filesystem mutation");
                return None;
            }
            let response = execute_workspace_filesystem_with_limits(
                &config.roots,
                request.clone(),
                &config.resource_limits,
            )
            .await;
            persist_filesystem_terminal(receipts, request, &response).await
        }
    }
}

async fn persist_filesystem_terminal(
    receipts: &dyn ReceiptBackend,
    request: &WorkspaceFilesystemRequest,
    response: &WorkspaceFilesystemResponse,
) -> Option<WorkspaceFilesystemResponse> {
    if let Err(error) = receipts.finish(request.request_id, request, response).await {
        tracing::warn!(%error, request_id = %request.request_id, "failed to persist terminal filesystem receipt");
        return None;
    }
    Some(response.clone())
}

fn indeterminate_filesystem_response(
    request: &WorkspaceFilesystemRequest,
    message: &str,
) -> WorkspaceFilesystemResponse {
    WorkspaceFilesystemResponse {
        request_id: request.request_id,
        workspace_id: request.workspace_id,
        outcome: WorkspaceFilesystemOutcome::Failure {
            code: WorkspaceFilesystemErrorCode::Indeterminate,
            message: message.to_string(),
            retryable: false,
        },
    }
}

