    #[tokio::test]
    async fn hosted_duration_limit_settles_work_without_publication() {
        let host = Uuid::new_v4();
        with_test_transport(host, |_frames| async move {
            use tokio::sync::Notify;
            struct PendingExecutor(Arc<Notify>, Arc<Notify>);
            struct NotifyDrop(Arc<Notify>);
            impl Drop for NotifyDrop {
                fn drop(&mut self) {
                    self.0.notify_one();
                }
            }
            #[async_trait::async_trait]
            impl AgentTurnExecutor for PendingExecutor {
                async fn execute(
                    &self,
                    _turn: crate::AgentTurn,
                    _events: mpsc::Sender<crate::SessionEventKind>,
                    _controls: Option<mpsc::Receiver<crate::AgentTurnControl>>,
                ) -> Result<crate::AgentTurnResult> {
                    let _drop = NotifyDrop(Arc::clone(&self.1));
                    self.0.notify_one();
                    std::future::pending().await
                }
            }
            let root = tempdir().unwrap();
            let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
            let mut config = test_config_for(root.path(), host);
            config.server = format!("http://{}", listener.local_addr().unwrap());
            let _relay = spawn_not_found_relay(listener);
            config.resource_limits.max_session_seconds = 8;
            let client = Client::builder()
                .timeout(Duration::from_secs(30))
                .build()
                .unwrap();
            let id = Uuid::new_v4();
            let launch = bootstrap_test_launch(root.path());
            let (scratch, store) = crate::session_store::postgres::testing::session_store().await;
            persist_launch_metadata(&config, &store, id, &launch, None)
                .await
                .unwrap();
            store.begin_host_bootstrap(id).await.unwrap();
            let started = Arc::new(Notify::new());
            let dropped = Arc::new(Notify::new());
            let executor: Arc<dyn AgentTurnExecutor> =
                Arc::new(PendingExecutor(Arc::clone(&started), Arc::clone(&dropped)));
            let factory: HostExecutorFactory = Arc::new(move |_, _| Ok(Arc::clone(&executor)));
            let (_commands, rx) = mpsc::channel(8);
            let mut supervisor = AbortTask(host_transport::spawn(run_session(
                client.clone(),
                config.clone(),
                root.path().to_path_buf(),
                factory,
                HostSessionLaunch {
                    session_id: id,
                    request: launch,
                    attachment: None,
                },
                rx,
                host_store(&scratch).await,
            )));
            tokio::time::timeout(Duration::from_secs(30), started.notified())
                .await
                .unwrap();
            assert!(
                SessionWriterLease::try_acquire(root.path().join(format!("{id}.lock")))
                    .unwrap()
                    .is_none()
            );
            tokio::time::timeout(Duration::from_secs(10), &mut supervisor.0)
                .await
                .expect("a blocked relay upload must not postpone duration settlement")
                .unwrap()
                .unwrap();
            tokio::time::timeout(Duration::from_secs(1), dropped.notified())
                .await
                .expect("expiry must cancel the provider turn before releasing ownership");
            assert!(
                SessionWriterLease::try_acquire(root.path().join(format!("{id}.lock")))
                    .unwrap()
                    .is_some()
            );
            drop(store);
            let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                .await
                .unwrap();
            let state = store.state(id).await.unwrap();
            assert_eq!(
                state.status,
                Some(crate::SessionStatus::Failed),
                "duration expiry must be durable, not restartable unfinished work"
            );
            assert!(store.pending_actions(id, 8).await.unwrap().is_empty());
            assert!(
                store
                    .pending_host_launch_metadata(8)
                    .await
                    .unwrap()
                    .is_empty()
            );
            assert!(
                store
                    .pending_host_journals(None, 8)
                    .await
                    .unwrap()
                    .contains(&id)
            );
            let sessions = Arc::new(Mutex::new(HashMap::new()));
            let forbidden: HostExecutorFactory =
                Arc::new(|_, _| panic!("expired work must not restart"));
            resume_pending_host_sessions(
                0,
                &client,
                &config,
                root.path(),
                &sessions,
                &host_store(&scratch).await,
                &forbidden,
            )
            .await
            .unwrap();
            assert!(sessions.lock().await.is_empty());
            scratch.discard().await;
        })
        .await
    }

    #[tokio::test]
    async fn inactive_duration_expiry_settles_before_capacity_and_attachment_restoration() {
        for expired_attachment in [false, true] {
            let root = tempdir().unwrap();
            let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
            let mut config = test_config(root.path());
            config.server = format!("http://{}", listener.local_addr().unwrap());
            config.resource_limits.max_session_seconds = 10;
            config.resource_limits.max_concurrent_sessions = 1;
            let (scratch, store) = crate::session_store::postgres::testing::session_store().await;
            let id = Uuid::new_v4();
            let launch = bootstrap_test_launch(root.path());
            let metadata = serde_json::to_value(PersistedLaunchMetadata {
                request: launch.clone(),
                attachment: expired_attachment.then(|| WorkspaceAttachment {
                    workspace_id: None,
                    participant_id: None,
                    command_authority: None,
                    host_identity: None,
                    host_capabilities: None,
                    presence_lease: Some(crate::RemotePresenceLease {
                        lease_id: Uuid::new_v4(),
                        expires_at: Utc::now() - ChronoDuration::minutes(1),
                    }),
                    approval_provenance: None,
                    reconnect_sync_cursors: None,
                }),
            })
            .unwrap();
            store
                .persist_owned_host_launch_metadata(
                    id,
                    &metadata,
                    config.host_id,
                    &host_relay_origin(&config).unwrap(),
                )
                .await
                .unwrap();
            store.begin_host_bootstrap(id).await.unwrap();
            store.create_session(id).await.unwrap();
            let mut start = SessionEvent::new(id, 0, crate::SessionEventKind::SessionStarted);
            start.created_at = Utc::now() - ChronoDuration::seconds(60);
            store.append(start).await.unwrap();
            store
                .append(SessionEvent::new(
                    id,
                    0,
                    crate::SessionEventKind::SessionConfigured {
                        cwd: launch.cwd.clone(),
                        provider: launch.provider,
                        model: None,
                        effort: None,
                        fast: false,
                        ultrafast: false,
                        response_language: launch.response_language,
                        permission_mode: launch.permission_mode,
                        speed_support: Default::default(),
                    },
                ))
                .await
                .unwrap();
            admit_remote_prompt(
                &store,
                id,
                launch.request_id,
                "expired unfinished work",
                &[],
                crate::PromptDelivery::Queue,
            )
            .await
            .unwrap();
            drop(store);
            let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                .await
                .unwrap();
            let original = serde_json::to_value(store.read(id).await.unwrap()).unwrap();
            let sessions = Arc::new(Mutex::new(HashMap::new()));
            let (tx, _rx) = mpsc::channel(1);
            let active_id = Uuid::new_v4();
            sessions.lock().await.insert(active_id, tx.clone());
            let executor: HostExecutorFactory =
                Arc::new(|_, _| panic!("local expiry cannot construct a provider"));
            let client = Client::new();
            let mut foreign = config.clone();
            foreign.host_id = Uuid::new_v4();
            resume_pending_host_sessions(
                0,
                &client,
                &foreign,
                root.path(),
                &sessions,
                &host_store(&scratch).await,
                &executor,
            )
            .await
            .unwrap();
            foreign = config.clone();
            foreign.server = "https://another-relay.invalid".into();
            resume_pending_host_sessions(
                0,
                &client,
                &foreign,
                root.path(),
                &sessions,
                &host_store(&scratch).await,
                &executor,
            )
            .await
            .unwrap();
            sessions.lock().await.insert(id, tx);
            resume_pending_host_sessions(
                0,
                &client,
                &config,
                root.path(),
                &sessions,
                &host_store(&scratch).await,
                &executor,
            )
            .await
            .unwrap();
            sessions.lock().await.remove(&id);
            let other_due = Uuid::new_v4();
            store
                .persist_owned_host_launch_metadata(
                    other_due,
                    &metadata,
                    config.host_id,
                    &host_relay_origin(&config).unwrap(),
                )
                .await
                .unwrap();
            store.begin_host_bootstrap(other_due).await.unwrap();
            store.create_session(other_due).await.unwrap();
            let mut start =
                SessionEvent::new(other_due, 0, crate::SessionEventKind::SessionStarted);
            start.created_at = Utc::now() - ChronoDuration::seconds(60);
            store.append(start).await.unwrap();
            let writer =
                SessionWriterLease::acquire(root.path().join(format!("{id}.lock"))).unwrap();
            resume_pending_host_sessions(
                0,
                &client,
                &config,
                root.path(),
                &sessions,
                &host_store(&scratch).await,
                &executor,
            )
            .await
            .unwrap();
            assert_eq!(
                serde_json::to_value(store.read(id).await.unwrap()).unwrap(),
                original
            );
            assert_eq!(store.pending_actions(id, 8).await.unwrap().len(), 1);
            assert_eq!(
                store.state(other_due).await.unwrap().status,
                Some(crate::SessionStatus::Failed),
                "a held writer must not prevent another overdue candidate from settling"
            );
            drop(writer);
            let mut extended = config.clone();
            extended.resource_limits.max_session_seconds = 120;
            resume_pending_host_sessions(
                0,
                &client,
                &extended,
                root.path(),
                &sessions,
                &host_store(&scratch).await,
                &executor,
            )
            .await
            .unwrap();
            assert_eq!(
                serde_json::to_value(store.read(id).await.unwrap()).unwrap(),
                original
            );
            resume_pending_host_sessions(
                0,
                &client,
                &config,
                root.path(),
                &sessions,
                &host_store(&scratch).await,
                &executor,
            )
            .await
            .unwrap();
            assert_eq!(
                store.state(id).await.unwrap().status,
                Some(crate::SessionStatus::Failed),
                "expired work must settle even when capacity or attachment prevents restoration"
            );
            assert!(store.pending_actions(id, 8).await.unwrap().is_empty());
            assert!(
                store
                    .pending_host_launch_metadata(8)
                    .await
                    .unwrap()
                    .is_empty()
            );
            assert!(
                store
                    .pending_host_journals(None, 8)
                    .await
                    .unwrap()
                    .contains(&id)
            );
            let settled = serde_json::to_value(store.read(id).await.unwrap()).unwrap();
            drop(store);
            let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                .await
                .unwrap();
            resume_pending_host_sessions(
                0,
                &client,
                &config,
                root.path(),
                &sessions,
                &host_store(&scratch).await,
                &executor,
            )
            .await
            .unwrap();
            assert_eq!(
                serde_json::to_value(store.read(id).await.unwrap()).unwrap(),
                settled
            );
            assert_eq!(
                store.load_host_launch_metadata(id).await.unwrap(),
                Some(metadata)
            );
            assert_eq!(sessions.lock().await.len(), 1);
            assert!(
                tokio::time::timeout(Duration::from_millis(50), listener.accept())
                    .await
                    .is_err()
            );
            scratch.discard().await;
        }
    }

    #[tokio::test]
    async fn recovered_host_session_cannot_reset_its_elapsed_duration_budget() {
        let host = Uuid::new_v4();
        with_test_transport(host, |_frames| async move {
            let root = tempdir().unwrap();
            let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
            let mut config = test_config_for(root.path(), host);
            config.server = format!("http://{}", listener.local_addr().unwrap());
            config.resource_limits.max_session_seconds = 10;
            let id = Uuid::new_v4();
            let launch = bootstrap_test_launch(root.path());
            let (scratch, store) = crate::session_store::postgres::testing::session_store().await;
            persist_launch_metadata(&config, &store, id, &launch, None)
                .await
                .unwrap();
            store.create_session(id).await.unwrap();
            let mut start = SessionEvent::new(id, 0, crate::SessionEventKind::SessionStarted);
            start.created_at = Utc::now() - chrono::Duration::seconds(60);
            store.append(start).await.unwrap();
            store
                .append(SessionEvent::new(
                    id,
                    0,
                    crate::SessionEventKind::SessionConfigured {
                        cwd: launch.cwd.clone(),
                        provider: launch.provider,
                        model: None,
                        effort: None,
                        fast: false,
                        ultrafast: false,
                        response_language: launch.response_language,
                        permission_mode: launch.permission_mode,
                        speed_support: Default::default(),
                    },
                ))
                .await
                .unwrap();
            admit_remote_prompt(
                &store,
                id,
                launch.request_id,
                "unfinished work",
                &[],
                crate::PromptDelivery::Queue,
            )
            .await
            .unwrap();
            drop(store);
            let writer =
                SessionWriterLease::acquire(root.path().join(format!("{id}.lock"))).unwrap();
            let (_held_tx, held_rx) = mpsc::channel(1);
            assert!(
                run_session(
                    Client::new(),
                    config.clone(),
                    root.path().to_path_buf(),
                    Arc::new(|_, _| panic!("a live writer must fence expiry")),
                    HostSessionLaunch {
                        session_id: id,
                        request: launch.clone(),
                        attachment: None
                    },
                    held_rx,
                    host_store(&scratch).await,
                )
                .await
                .is_err()
            );
            let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                .await
                .unwrap();
            assert_ne!(
                store.state(id).await.unwrap().status,
                Some(crate::SessionStatus::Failed)
            );
            assert_eq!(store.pending_actions(id, 8).await.unwrap().len(), 1);
            drop(store);
            drop(writer);
            let (_commands, rx) = mpsc::channel(1);
            let result = tokio::time::timeout(
                Duration::from_secs(2),
                run_session(
                    Client::new(),
                    config.clone(),
                    root.path().to_path_buf(),
                    Arc::new(|_, _| panic!("an expired session must not construct a provider")),
                    HostSessionLaunch {
                        session_id: id,
                        request: launch,
                        attachment: None,
                    },
                    rx,
                    host_store(&scratch).await,
                ),
            )
            .await;
            assert!(
                result.is_ok(),
                "expired recovery must settle locally before contacting an unavailable relay"
            );
            result.unwrap().unwrap();
            let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                .await
                .unwrap();
            assert_eq!(
                store.state(id).await.unwrap().status,
                Some(crate::SessionStatus::Failed)
            );
            assert!(store.pending_actions(id, 8).await.unwrap().is_empty());
            assert!(
                store
                    .pending_host_launch_metadata(8)
                    .await
                    .unwrap()
                    .is_empty()
            );
            assert!(
                tokio::time::timeout(Duration::from_millis(50), listener.accept())
                    .await
                    .is_err()
            );
            scratch.discard().await;
        })
        .await
    }

    #[tokio::test]
    async fn panicked_host_startup_releases_routing_and_preserves_durable_recovery() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        use tokio::sync::Notify;
        for started in [false, true] {
            let root = tempdir().unwrap();
            let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
            let mut config = test_config(root.path());
            config.server = format!("http://{}", listener.local_addr().unwrap());
            let _server = AbortTask(host_transport::spawn(async move {
                loop {
                    let (mut socket, _) = listener.accept().await.unwrap();
                    // Runtime context and collaboration catch-up are optional here.
                    let _ = read_http_request(&mut socket).await;
                    socket.write_all(b"HTTP/1.1 404 Not Found\r\ncontent-length: 0\r\nconnection: close\r\n\r\n").await.unwrap();
                }
            }));
            let (outbound, mut frames) = mpsc::channel(8);
            let transport = host_transport::Transport::new(config.host_id, outbound);
            let acknowledger = transport.clone();
            let _registrations = AbortTask(tokio::spawn(async move {
                while let Some(frame) = frames.recv().await {
                    match frame {
                        crate::auth::TunnelFrame::RegisterSession {
                            registration_id, ..
                        } => acknowledger.registered(&registration_id, None),
                        other => panic!("unexpected registration fixture frame: {other:?}"),
                    }
                }
            }));
            host_transport::CURRENT
                .scope(transport, async {
                    let (scratch, store) =
                        crate::session_store::postgres::testing::session_store().await;
                    let id = Uuid::new_v4();
                    let launch = bootstrap_test_launch(root.path());
                    persist_launch_metadata(&config, &store, id, &launch, None)
                        .await
                        .unwrap();
                    store.begin_host_bootstrap(id).await.unwrap();
                    if started {
                        store.create_session(id).await.unwrap();
                        for kind in [
                            crate::SessionEventKind::SessionStarted,
                            crate::SessionEventKind::SessionConfigured {
                                cwd: launch.cwd.clone(),
                                provider: launch.provider,
                                model: None,
                                effort: None,
                                fast: false,
                                ultrafast: false,
                                response_language: launch.response_language,
                                permission_mode: launch.permission_mode,
                                speed_support: Default::default(),
                            },
                        ] {
                            store.append(SessionEvent::new(id, 0, kind)).await.unwrap();
                        }
                        admit_remote_prompt(
                            &store,
                            id,
                            launch.request_id,
                            "recover after panic",
                            &[],
                            crate::PromptDelivery::Queue,
                        )
                        .await
                        .unwrap();
                    }
                    let sessions = Arc::new(Mutex::new(HashMap::new()));
                    let reached = Arc::new(Notify::new());
                    let attempts = Arc::new(AtomicUsize::new(0));
                    let factory_reached = Arc::clone(&reached);
                    let factory_attempts = Arc::clone(&attempts);
                    let factory: HostExecutorFactory = Arc::new(move |_, _| {
                        factory_attempts.fetch_add(1, Ordering::SeqCst);
                        factory_reached.notify_one();
                        panic!("injected hosted startup panic");
                    });
                    let client = Client::builder()
                        .timeout(Duration::from_secs(5))
                        .build()
                        .unwrap();
                    let commands = spawn_host_session(
                        client.clone(),
                        config.clone(),
                        root.path().to_path_buf(),
                        Arc::clone(&sessions),
                        factory,
                        HostSessionLaunch {
                            session_id: id,
                            request: launch,
                            attachment: None,
                        },
                        host_store(&scratch).await,
                    )
                    .await;
                    tokio::time::timeout(Duration::from_secs(30), reached.notified())
                        .await
                        .unwrap();
                    tokio::time::timeout(Duration::from_secs(5), commands.closed())
                        .await
                        .unwrap();
                    tokio::time::timeout(Duration::from_secs(5), async {
                while sessions.lock().await.contains_key(&id) {
                    tokio::time::sleep(Duration::from_millis(10)).await;
                }
            })
            .await
            .expect(
                "a panic must not leave a closed route that blocks recovery and consumes capacity",
            );
                    tokio::time::timeout(Duration::from_secs(5), async {
                        loop {
                            if SessionWriterLease::try_acquire(
                                root.path().join(format!("{id}.lock")),
                            )
                            .unwrap()
                            .is_some()
                            {
                                break;
                            }
                            tokio::time::sleep(Duration::from_millis(10)).await;
                        }
                    })
                    .await
                    .expect("startup panic must release writer ownership");
                    drop(store);
                    let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                        .await
                        .unwrap();
                    let journal = serde_json::to_value(store.read(id).await.unwrap()).unwrap();
                    if started {
                        assert_ne!(
                            store.state(id).await.unwrap().status,
                            Some(crate::SessionStatus::Failed)
                        );
                        assert_eq!(store.pending_actions(id, 8).await.unwrap().len(), 1);
                    } else {
                        assert_eq!(
                            store.state(id).await.unwrap().status,
                            Some(crate::SessionStatus::Failed)
                        );
                        assert!(
                            store
                                .pending_host_launch_metadata(8)
                                .await
                                .unwrap()
                                .is_empty()
                        );
                    }
                    let factory_reached = Arc::clone(&reached);
                    let factory_attempts = Arc::clone(&attempts);
                    let retry: HostExecutorFactory = Arc::new(move |_, _| {
                        factory_attempts.fetch_add(1, Ordering::SeqCst);
                        factory_reached.notify_one();
                        bail!("stop recovery probe before executing a provider")
                    });
                    resume_pending_host_sessions(
                        0,
                        &client,
                        &config,
                        root.path(),
                        &sessions,
                        &host_store(&scratch).await,
                        &retry,
                    )
                    .await
                    .unwrap();
                    if started {
                        tokio::time::timeout(Duration::from_secs(30), reached.notified())
                            .await
                            .unwrap();
                        tokio::time::timeout(Duration::from_secs(5), async {
                            while sessions.lock().await.contains_key(&id) {
                                tokio::time::sleep(Duration::from_millis(10)).await;
                            }
                        })
                        .await
                        .unwrap();
                    }
                    assert_eq!(attempts.load(Ordering::SeqCst), if started { 2 } else { 1 });
                    assert_eq!(
                        serde_json::to_value(store.read(id).await.unwrap()).unwrap(),
                        journal
                    );
                    assert!(sessions.lock().await.is_empty());
                    scratch.discard().await;
                })
                .await;
        }
    }

    #[tokio::test]
    async fn hosted_actor_is_owned_on_stop_or_cancellation() {
        let host = Uuid::new_v4();
        with_test_transport(host, |_frames| async move {
            use tokio::sync::Notify;
            struct PendingExecutor {
                started: Arc<Notify>,
                dropped: Arc<Notify>,
            }
            struct NotifyDrop(Arc<Notify>);
            impl Drop for NotifyDrop {
                fn drop(&mut self) {
                    self.0.notify_one();
                }
            }
            #[async_trait::async_trait]
            impl AgentTurnExecutor for PendingExecutor {
                async fn execute(
                    &self,
                    _turn: crate::AgentTurn,
                    _events: mpsc::Sender<crate::SessionEventKind>,
                    _controls: Option<mpsc::Receiver<crate::AgentTurnControl>>,
                ) -> Result<crate::AgentTurnResult> {
                    let _lifetime = NotifyDrop(Arc::clone(&self.dropped));
                    self.started.notify_one();
                    std::future::pending().await
                }
            }
            let root = tempdir().unwrap();
            let mut config = test_config_for(root.path(), host);
            let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
            config.server = format!("http://{}", listener.local_addr().unwrap());
            let _relay = spawn_not_found_relay(listener);
            let client = Client::builder()
                .timeout(Duration::from_secs(5))
                .build()
                .unwrap();
            let started = Arc::new(Notify::new());
            let dropped = Arc::new(Notify::new());
            let executor: Arc<dyn AgentTurnExecutor> = Arc::new(PendingExecutor {
                started: Arc::clone(&started),
                dropped: Arc::clone(&dropped),
            });
            let factory: HostExecutorFactory = Arc::new(move |_, _| Ok(Arc::clone(&executor)));
            let session_id = Uuid::new_v4();
            let (commands, rx) = mpsc::channel(8);
            // The actor and this test must share one journal: the projection this
            // test corrupts below is the one the actor reads.
            let (scratch, store) = crate::session_store::postgres::testing::session_store().await;
            let mut supervisor = AbortTask(host_transport::spawn(run_session(
                client.clone(),
                config.clone(),
                root.path().to_path_buf(),
                Arc::clone(&factory),
                HostSessionLaunch {
                    session_id,
                    request: bootstrap_test_launch(root.path()),
                    attachment: None,
                },
                rx,
                host_store(&scratch).await,
            )));
            tokio::time::timeout(Duration::from_secs(30), started.notified())
                .await
                .unwrap();
            // Corrupt only a disposable live projection, not the authoritative
            // journal. The row is valid jsonb the column accepts but not a valid
            // event, so the projection read fails where the journal still reads.
            sqlx::query(
            "insert into session_live_state(session_id,live_key,revision,event_json,updated_at) \
             values($1,$2,$3,$4,$5)",
        )
        .bind(session_id)
        .bind("injected")
        .bind(i64::MAX)
        .bind(serde_json::json!({"not": "an event"}))
        .bind(Utc::now())
        .execute(store.pool())
        .await
        .unwrap();
            assert!(store.live_events_after(session_id, 0).await.is_err());
            tokio::time::sleep(Duration::from_secs(3)).await;
            assert!(
                !supervisor.0.is_finished(),
                "a projection read failure must not abandon the actor"
            );
            assert!(
                SessionWriterLease::try_acquire(root.path().join(format!("{session_id}.lock")))
                    .unwrap()
                    .is_none()
            );
            sqlx::query("delete from session_live_state where session_id=$1 and live_key=$2")
                .bind(session_id)
                .bind("injected")
                .execute(store.pool())
                .await
                .unwrap();
            let _marker = store
                .append(SessionEvent::new(
                    session_id,
                    0,
                    crate::SessionEventKind::Error {
                        message: "sync recovery marker".to_string(),
                    },
                ))
                .await
                .unwrap();
            commands
                .send(HostCommand::Stop { session_id })
                .await
                .unwrap();
            tokio::time::timeout(Duration::from_secs(8), &mut supervisor.0)
                .await
                .unwrap()
                .unwrap()
                .unwrap();
            tokio::time::timeout(Duration::from_secs(1), dropped.notified())
                .await
                .unwrap();
            assert_eq!(
                store.state(session_id).await.unwrap().status,
                Some(crate::SessionStatus::Stopped)
            );
            {
                let id = Uuid::new_v4();
                let (_commands, rx) = mpsc::channel(8);
                let mut supervisor = AbortTask(host_transport::spawn(run_session(
                    client.clone(),
                    config.clone(),
                    root.path().to_path_buf(),
                    Arc::clone(&factory),
                    HostSessionLaunch {
                        session_id: id,
                        request: bootstrap_test_launch(root.path()),
                        attachment: None,
                    },
                    rx,
                    host_store(&scratch).await,
                )));
                tokio::time::timeout(Duration::from_secs(30), started.notified())
                    .await
                    .unwrap();
                supervisor.0.abort();
                assert!((&mut supervisor.0).await.unwrap_err().is_cancelled());
                tokio::time::timeout(Duration::from_secs(2), dropped.notified())
                    .await
                    .expect("host supervisor must not detach its actor or provider turn");
                assert!(
                    SessionWriterLease::try_acquire(root.path().join(format!("{id}.lock")))
                        .unwrap()
                        .is_some()
                );
            }
            scratch.discard().await;
        })
        .await
    }

    #[tokio::test]
    async fn legacy_launch_owner_requires_local_ownership_and_rechecks_identity() {
        let root = tempdir().unwrap();
        let (scratch, store) = crate::session_store::postgres::testing::session_store().await;
        let id = Uuid::new_v4();
        let metadata = serde_json::to_value(PersistedLaunchMetadata {
            request: bootstrap_test_launch(root.path()),
            attachment: None,
        })
        .unwrap();
        store
            .persist_host_launch_metadata(id, &metadata)
            .await
            .unwrap();
        store.begin_host_bootstrap(id).await.unwrap();
        sqlx::query("drop table host_launch_owners")
            .execute(store.pool())
            .await
            .unwrap();
        // The dropped table only comes back if the database also stops
        // claiming this schema is already applied.
        sqlx::query("update borg_session_schema set definition_hash = null")
            .execute(store.pool())
            .await
            .unwrap();
        drop(store);
        let store: Arc<dyn SessionStore> = Arc::new(
            PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                .await
                .unwrap(),
        );
        assert!(
            store.host_launch_owner(id).await.unwrap().is_none(),
            "schema upgrade must not invent an owner"
        );
        let config = test_config(root.path());
        let client = Client::new();
        assert!(
            ensure_host_launch_owner(&client, &config, store.as_ref(), id)
                .await
                .is_err()
        );
        assert!(store.host_launch_owner(id).await.unwrap().is_none());
        assert!(!store.contains_session(id).await.unwrap());
        assert_eq!(
            store.load_host_launch_metadata(id).await.unwrap(),
            Some(metadata)
        );
        let owned = Uuid::new_v4();
        persist_launch_metadata(
            &config,
            store.as_ref(),
            owned,
            &bootstrap_test_launch(root.path()),
            None,
        )
        .await
        .unwrap();
        ensure_host_launch_owner(&client, &config, store.as_ref(), owned)
            .await
            .unwrap();
        let mut foreign = config.clone();
        foreign.host_id = Uuid::new_v4();
        assert!(
            ensure_host_launch_owner(&client, &foreign, store.as_ref(), owned)
                .await
                .is_err()
        );
        foreign = config.clone();
        foreign.server = "https://other.invalid".to_string();
        assert!(
            ensure_host_launch_owner(&client, &foreign, store.as_ref(), owned)
                .await
                .is_err()
        );
        scratch.discard().await;
    }

    #[tokio::test]
    async fn prestart_launch_keeps_its_host_and_relay_owner_after_reopen() {
        let root = tempdir().unwrap();
        let (scratch, store) = crate::session_store::postgres::testing::session_store().await;
        let config = test_config(root.path());
        let id = Uuid::new_v4();
        persist_launch_metadata(
            &config,
            &store,
            id,
            &bootstrap_test_launch(root.path()),
            None,
        )
        .await
        .unwrap();
        store.begin_host_bootstrap(id).await.unwrap();
        assert!(!store.contains_session(id).await.unwrap());
        drop(store);
        let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
            .await
            .unwrap();
        let mut foreign = config.clone();
        foreign.host_id = Uuid::new_v4();
        assert!(
            validate_stored_host_identity(&foreign, &store, id)
                .await
                .is_err(),
            "an acknowledged pre-start launch must retain its original host without a workspace binding"
        );
        foreign = config.clone();
        foreign.server = "https://another-relay.invalid".to_string();
        assert!(
            validate_stored_host_identity(&foreign, &store, id)
                .await
                .is_err(),
            "host UUID reuse at another relay must not transfer launch ownership"
        );
        validate_stored_host_identity(&config, &store, id)
            .await
            .unwrap();
        scratch.discard().await;
    }

    #[tokio::test]
    async fn reenrolled_host_cannot_rebind_or_settle_another_host_session() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        let root = tempdir().unwrap();
        let (scratch, postgres) = crate::session_store::postgres::testing::session_store().await;
        let store: Arc<dyn SessionStore> = Arc::new(postgres);
        let session_id = Uuid::new_v4();
        let original_host = Uuid::new_v4();
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let mut config = test_config(root.path());
        assert_ne!(config.host_id, original_host);
        config.server = format!("http://{}", listener.local_addr().unwrap());
        let mut owner_config = config.clone();
        owner_config.host_id = original_host;
        let launch = bootstrap_test_launch(root.path());
        persist_launch_metadata(&owner_config, store.as_ref(), session_id, &launch, None)
            .await
            .unwrap();
        store.create_session(session_id).await.unwrap();
        let binding = store.workspace_binding(session_id).await.unwrap().unwrap();
        let binding = crate::SessionWorkspaceBinding {
            host_id: Some(original_host),
            ..binding
        };
        store.attach_workspace(binding.clone()).await.unwrap();
        store
            .append(SessionEvent::new(
                session_id,
                0,
                crate::SessionEventKind::SessionStarted,
            ))
            .await
            .unwrap();
        store.begin_host_bootstrap(session_id).await.unwrap();
        let requests = Arc::new(AtomicUsize::new(0));
        let seen = Arc::clone(&requests);
        let _server = AbortTask(host_transport::spawn(async move {
            loop {
                let (mut socket, _) = listener.accept().await.unwrap();
                read_http_request(&mut socket).await;
                seen.fetch_add(1, Ordering::SeqCst);
                socket
                    .write_all(
                        b"HTTP/1.1 404 Not Found\r\ncontent-length: 0\r\nconnection: close\r\n\r\n",
                    )
                    .await
                    .unwrap();
            }
        }));
        let executor: HostExecutorFactory = Arc::new(|_, _| bail!("must not construct a provider"));
        let (_tx, rx) = mpsc::channel(1);
        assert!(
            tokio::time::timeout(
                Duration::from_secs(30),
                run_session(
                    Client::new(),
                    config.clone(),
                    root.path().to_path_buf(),
                    Arc::clone(&executor),
                    HostSessionLaunch {
                        session_id,
                        request: launch.clone(),
                        attachment: None
                    },
                    rx,
                    host_store(&scratch).await,
                )
            )
            .await
            .unwrap()
            .is_err()
        );
        assert_eq!(
            store.workspace_binding(session_id).await.unwrap().unwrap(),
            binding,
            "relay rejection must not come after silently rewriting the original host binding"
        );
        assert_eq!(
            requests.load(Ordering::SeqCst),
            0,
            "foreign durable identity must be rejected before network/provider startup"
        );
        let sessions = Arc::new(Mutex::new(HashMap::new()));
        // Same authority as the journal, obtained the way production does.
        let receipts = store.receipt_store().await.unwrap();
        let command_context = |config: &HostConfig| DispatchContext {
            client: Client::new(),
            config: config.clone(),
            session_root: root.path().to_path_buf(),
            sessions: Arc::clone(&sessions),
            session_store: Arc::clone(&store),
            receipts: Arc::clone(&receipts),
            executor_factory: Arc::clone(&executor),
        };
        for command in [
            HostCommand::Stop { session_id },
            HostCommand::Launch {
                session_id,
                request: Box::new(launch.clone()),
                attachment: None,
            },
        ] {
            assert!(!dispatch(command_context(&config), command).await);
        }
        resume_pending_host_sessions(
            0,
            &Client::new(),
            &config,
            root.path(),
            &sessions,
            &host_store(&scratch).await,
            &executor,
        )
        .await
        .unwrap();
        assert!(sessions.lock().await.is_empty());
        assert_eq!(
            store.workspace_binding(session_id).await.unwrap().unwrap(),
            binding
        );
        assert_eq!(
            store.events_after(session_id, 0, 10).await.unwrap().len(),
            1
        );
        assert_eq!(
            store.pending_host_launch_metadata(8).await.unwrap().len(),
            1
        );
        assert!(
            ensure_host_launch_owner(&Client::new(), &config, store.as_ref(), session_id)
                .await
                .is_err()
        );

        // A pre-start launch may carry its owner even before a workspace binding exists.
        let unstarted = Uuid::new_v4();
        let attachment = WorkspaceAttachment {
            workspace_id: None,
            participant_id: None,
            command_authority: None,
            host_identity: Some(RemoteHostIdentity {
                host_id: original_host,
                hostname: "original".to_string(),
                platform: "test".to_string(),
            }),
            host_capabilities: None,
            presence_lease: None,
            approval_provenance: None,
            reconnect_sync_cursors: None,
        };
        persist_launch_metadata(
            &owner_config,
            store.as_ref(),
            unstarted,
            &launch,
            Some(&attachment),
        )
        .await
        .unwrap();
        store.begin_host_bootstrap(unstarted).await.unwrap();
        assert!(
            !reject_host_launch(
                &Client::new(),
                &config,
                root.path(),
                store.as_ref(),
                unstarted,
                "wrong host startup failed"
            )
            .await
        );
        assert!(!store.contains_session(unstarted).await.unwrap());
        assert!(
            !dispatch(
                command_context(&config),
                HostCommand::Stop {
                    session_id: unstarted
                }
            )
            .await
        );
        resume_pending_host_sessions(
            0,
            &Client::new(),
            &config,
            root.path(),
            &sessions,
            &host_store(&scratch).await,
            &executor,
        )
        .await
        .unwrap();
        assert!(sessions.lock().await.is_empty());
        assert_eq!(
            store.pending_host_launch_metadata(8).await.unwrap().len(),
            2
        );

        assert!(
            dispatch(
                command_context(&owner_config),
                HostCommand::Stop { session_id }
            )
            .await,
            "the owning host can still durably stop its session without relay availability"
        );
        assert_eq!(
            store.state(session_id).await.unwrap().status,
            Some(crate::SessionStatus::Stopped)
        );
        assert!(!dispatch(command_context(&config), HostCommand::Stop { session_id }).await);
        assert_eq!(
            store.workspace_binding(session_id).await.unwrap().unwrap(),
            binding
        );
        assert_eq!(requests.load(Ordering::SeqCst), 0);
        let current = Uuid::new_v4();
        let mut current_attachment = attachment.clone();
        current_attachment.host_identity.as_mut().unwrap().host_id = config.host_id;
        persist_launch_metadata(
            &config,
            store.as_ref(),
            current,
            &launch,
            Some(&current_attachment),
        )
        .await
        .unwrap();
        store.begin_host_bootstrap(current).await.unwrap();
        assert_eq!(
            store
                .pending_host_launch_metadata_for_host(
                    0,
                    Some((config.host_id, &host_relay_origin(&config).unwrap())),
                    1
                )
                .await
                .unwrap()[0]
                .0,
            current,
            "foreign entries must not consume the bounded recovery page"
        );
        assert_eq!(
            store
                .pending_host_launch_metadata_for_host(
                    0,
                    Some((original_host, &host_relay_origin(&config).unwrap())),
                    1
                )
                .await
                .unwrap()[0]
                .0,
            unstarted
        );
        scratch.discard().await;
    }

    #[tokio::test]
    async fn recovery_scan_fault_preserves_metadata_and_retries_after_repair() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        let root = tempdir().unwrap();
        let config = test_config(root.path());
        let client = Client::new();
        let (scratch, store) = crate::session_store::postgres::testing::session_store().await;
        let sessions = Arc::new(Mutex::new(HashMap::new()));
        let factory_calls = Arc::new(AtomicUsize::new(0));
        let seen = Arc::clone(&factory_calls);
        let factory: HostExecutorFactory = Arc::new(move |_, _| {
            seen.fetch_add(1, Ordering::SeqCst);
            bail!("invalid or settled bootstrap must not construct a provider")
        });
        let session_store = host_store(&scratch).await;
        let id = Uuid::new_v4();
        let mut launch = bootstrap_test_launch(root.path());
        launch.cwd = root.path().join("no-longer-present");
        persist_launch_metadata(&config, &store, id, &launch, None)
            .await
            .unwrap();
        store.begin_host_bootstrap(id).await.unwrap();
        let metadata = store.load_host_launch_metadata(id).await.unwrap().unwrap();
        let corrupted = serde_json::json!({"not": "launch metadata"});
        sqlx::query("update host_launches set metadata_json=$1 where session_id=$2")
            .bind(&corrupted)
            .bind(id)
            .execute(store.pool())
            .await
            .unwrap();
        // Rename only this disposable database's table, preserving owner rows.
        sqlx::query("alter table host_launch_owners rename to host_launch_owners_faulted")
            .execute(store.pool())
            .await
            .unwrap();
        assert!(
            resume_pending_host_sessions(
                0,
                &client,
                &config,
                root.path(),
                &sessions,
                &session_store,
                &factory
            )
            .await
            .is_err()
        );
        assert!(!store.contains_session(id).await.unwrap());
        let retained: serde_json::Value =
            sqlx::query_scalar("select metadata_json from host_launches where session_id=$1")
                .bind(id)
                .fetch_one(store.pool())
                .await
                .unwrap();
        assert_eq!(
            retained, corrupted,
            "scan failures cannot rewrite pending work"
        );
        assert_eq!(factory_calls.load(Ordering::SeqCst), 0);
        sqlx::query("alter table host_launch_owners_faulted rename to host_launch_owners")
            .execute(store.pool())
            .await
            .unwrap();
        sqlx::query("update host_launches set metadata_json=$1 where session_id=$2")
            .bind(serde_json::to_value(&metadata).unwrap())
            .bind(id)
            .execute(store.pool())
            .await
            .unwrap();
        assert_eq!(
            resume_pending_host_sessions(
                0,
                &client,
                &config,
                root.path(),
                &sessions,
                &session_store,
                &factory
            )
            .await
            .unwrap(),
            0
        );
        tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                if store.contains_session(id).await.unwrap()
                    && store.state(id).await.unwrap().status == Some(crate::SessionStatus::Failed)
                    && !sessions.lock().await.contains_key(&id)
                {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap();
        let journal = serde_json::to_value(store.read(id).await.unwrap()).unwrap();
        resume_pending_host_sessions(
            0,
            &client,
            &config,
            root.path(),
            &sessions,
            &session_store,
            &factory,
        )
        .await
        .unwrap();
        assert_eq!(
            serde_json::to_value(store.read(id).await.unwrap()).unwrap(),
            journal
        );
        assert_eq!(factory_calls.load(Ordering::SeqCst), 0);
        assert!(sessions.lock().await.is_empty());
        assert_eq!(
            store.load_host_launch_metadata(id).await.unwrap(),
            Some(metadata)
        );
        scratch.discard().await;
    }

    #[tokio::test]
    async fn recovery_pages_past_lease_blocked_launches_to_acknowledged_work() {
        let host = Uuid::new_v4();
        with_test_transport(host, |_frames| async move {
        let root = tempdir().unwrap();
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let mut config = test_config_for(root.path(), host);
        config.server = format!("http://{}", listener.local_addr().unwrap());
        config.resource_limits.max_concurrent_sessions = 1;
        let (scratch, store) = crate::session_store::postgres::testing::session_store().await;
        let launch = bootstrap_test_launch(root.path());
        let expired = serde_json::to_value(PersistedLaunchMetadata {
            request: launch.clone(),
            attachment: Some(WorkspaceAttachment {
                workspace_id: None,
                participant_id: None,
                command_authority: None,
                host_identity: None,
                host_capabilities: None,
                presence_lease: Some(crate::RemotePresenceLease {
                    lease_id: Uuid::new_v4(),
                    expires_at: Utc::now() - ChronoDuration::minutes(1),
                }),
                approval_provenance: None,
                reconnect_sync_cursors: None,
            }),
        })
        .unwrap();
        let mut blocked = Vec::new();
        for _ in 0..256 {
            let id = Uuid::new_v4();
            store
                .persist_owned_host_launch_metadata(
                    id,
                    &expired,
                    config.host_id,
                    &host_relay_origin(&config).unwrap(),
                )
                .await
                .unwrap();
            store.begin_host_bootstrap(id).await.unwrap();
            store.create_session(id).await.unwrap();
            store
                .append(SessionEvent::new(
                    id,
                    0,
                    crate::SessionEventKind::SessionStarted,
                ))
                .await
                .unwrap();
            blocked.push(id);
        }
        let next = Uuid::new_v4();
        persist_launch_metadata(&config, &store, next, &launch, None)
            .await
            .unwrap();
        store.create_session(next).await.unwrap();
        for kind in [
            crate::SessionEventKind::SessionStarted,
            crate::SessionEventKind::SessionConfigured {
                cwd: launch.cwd.clone(),
                provider: launch.provider,
                model: None,
                effort: None,
                fast: false,
                ultrafast: false,
                response_language: launch.response_language,
                permission_mode: launch.permission_mode,
                speed_support: Default::default(),
            },
        ] {
            store
                .append(SessionEvent::new(next, 0, kind))
                .await
                .unwrap();
        }
        admit_remote_prompt(
            &store,
            next,
            launch.request_id,
            "acknowledged before host restart",
            &[],
            crate::PromptDelivery::Queue,
        )
        .await
        .unwrap();
        drop(store);
        let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
            .await
            .unwrap();
        let sessions = Arc::new(Mutex::new(HashMap::new()));
        let executor: HostExecutorFactory =
            Arc::new(|_, _| panic!("recovery probe must stop before provider construction"));
        let client = Client::new();
        for settle_earlier in [false, true] {
            let offset = resume_pending_host_sessions(
                0,
                &client,
                &config,
                root.path(),
                &sessions,
                &host_store(&scratch).await,
                &executor,
            )
            .await
            .unwrap();
            assert_eq!(offset, 256);
            assert!(sessions.lock().await.is_empty());
            if settle_earlier {
                // Deliberately remove one earlier candidate between page reads.
                store.finish_host_bootstrap(blocked[0]).await.unwrap();
            }
            let offset = resume_pending_host_sessions(
                offset,
                &client,
                &config,
                root.path(),
                &sessions,
                &host_store(&scratch).await,
                &executor,
            )
            .await
            .unwrap();
            assert_eq!(offset, 0, "a short or empty page must wrap the scan");
            if settle_earlier {
                assert!(
                    sessions.lock().await.is_empty(),
                    "the target shifted behind the offset"
                );
                resume_pending_host_sessions(
                    offset,
                    &client,
                    &config,
                    root.path(),
                    &sessions,
                    &host_store(&scratch).await,
                    &executor,
                )
                .await
                .unwrap();
            }
            assert!(
                sessions.lock().await.contains_key(&next),
                "a full page of lease-blocked launches must not permanently hide later durable work"
            );
            assert_eq!(sessions.lock().await.len(), 1);
            let (mut socket, _) = tokio::time::timeout(Duration::from_secs(5), listener.accept())
                .await
                .unwrap()
                .unwrap();
            let (path, _) = read_http_request(&mut socket).await;
            assert!(path.contains(&next.to_string()) && path.ends_with("/runtime-context"));
            socket
                .write_all(
                    b"HTTP/1.1 401 Unauthorized\r\ncontent-length: 0\r\nconnection: close\r\n\r\n",
                )
                .await
                .unwrap();
            drop(socket);
            tokio::time::timeout(Duration::from_secs(5), async {
                while !sessions.lock().await.is_empty() {
                    tokio::time::sleep(Duration::from_millis(10)).await;
                }
            })
            .await
            .unwrap();
            assert_eq!(store.pending_actions(next, 8).await.unwrap().len(), 1);
        }
        for id in blocked {
            assert_eq!(
                store.load_host_launch_metadata(id).await.unwrap(),
                Some(expired.clone())
            );
            assert_eq!(store.state(id).await.unwrap().latest_sequence, 1);
        }
        assert!(
            tokio::time::timeout(Duration::from_millis(50), listener.accept())
                .await
                .is_err()
        );
        scratch.discard().await;
    })
        .await
    }

    #[tokio::test]
    async fn expired_attachment_defers_plain_prompts_without_blocking_stop_or_starting_an_actor() {
        for (capacity, delivery) in [
            (1, crate::PromptDelivery::Queue),
            (2, crate::PromptDelivery::Steer),
        ] {
            let root = tempdir().unwrap();
            let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
            let mut config = test_config(root.path());
            config.server = format!("http://{}", listener.local_addr().unwrap());
            config.resource_limits.max_concurrent_sessions = capacity;
            let (scratch, postgres) =
                crate::session_store::postgres::testing::session_store().await;
            let store: Arc<dyn SessionStore> = Arc::new(postgres);
            let session_id = Uuid::new_v4();
            let active_id = Uuid::new_v4();
            let launch = bootstrap_test_launch(root.path());
            let metadata = serde_json::to_value(PersistedLaunchMetadata {
                request: launch.clone(),
                attachment: Some(WorkspaceAttachment {
                    workspace_id: None,
                    participant_id: None,
                    command_authority: None,
                    host_identity: None,
                    host_capabilities: None,
                    presence_lease: Some(crate::RemotePresenceLease {
                        lease_id: Uuid::new_v4(),
                        expires_at: Utc::now() - ChronoDuration::minutes(1),
                    }),
                    approval_provenance: None,
                    reconnect_sync_cursors: None,
                }),
            })
            .unwrap();
            // Persisted snapshot of a previously admitted session, now inactive with an expired lease.
            store
                .persist_owned_host_launch_metadata(
                    session_id,
                    &metadata,
                    config.host_id,
                    &host_relay_origin(&config).unwrap(),
                )
                .await
                .unwrap();
            store.create_session(session_id).await.unwrap();
            for kind in [
                crate::SessionEventKind::SessionStarted,
                crate::SessionEventKind::SessionConfigured {
                    cwd: launch.cwd.clone(),
                    provider: launch.provider,
                    model: None,
                    effort: None,
                    fast: false,
                    ultrafast: false,
                    response_language: launch.response_language,
                    permission_mode: launch.permission_mode,
                    speed_support: Default::default(),
                },
                crate::SessionEventKind::StatusChanged {
                    lifecycle: Some(crate::SessionStatus::Ready.into()),
                    status: crate::SessionStatus::Ready,
                    detail: None,
                },
            ] {
                store
                    .append(SessionEvent::new(session_id, 0, kind))
                    .await
                    .unwrap();
            }
            let sessions = Arc::new(Mutex::new(HashMap::new()));
            let (tx, mut rx) = mpsc::channel(1);
            sessions.lock().await.insert(active_id, tx);
            let executor: HostExecutorFactory =
                Arc::new(|_, _| panic!("expired lease cannot authorize actor restoration"));
            let client = Client::new();
            let receipts: Arc<dyn ReceiptBackend> = Arc::new(receipts_on(&scratch).await);
            let context = |store: &Arc<dyn SessionStore>| DispatchContext {
                client: client.clone(),
                config: config.clone(),
                session_root: root.path().to_path_buf(),
                sessions: Arc::clone(&sessions),
                session_store: Arc::clone(store),
                receipts: Arc::clone(&receipts),
                executor_factory: Arc::clone(&executor),
            };
            let message_id = Uuid::new_v4();
            let prompt = || HostCommand::Prompt {
                session_id,
                message_id,
                text: "retain while authorization is expired".into(),
                attachments: vec![root.path().join("note.txt")],
                output_schema: None,
                delivery,
            };
            assert!(
                dispatch(context(&store), prompt()).await,
                "durable admission must allow the host queue to reach later controls"
            );
            assert_eq!(
                sessions.lock().await.len(),
                1,
                "admission must not start another actor"
            );
            let admitted =
                serde_json::to_value(store.events_after(session_id, 0, 20).await.unwrap()).unwrap();
            assert!(
                store
                    .contains_message(session_id, message_id)
                    .await
                    .unwrap()
            );
            assert_eq!(store.pending_actions(session_id, 8).await.unwrap().len(), 1);
            assert!(
                dispatch(
                    context(&store),
                    HostCommand::Stop {
                        session_id: active_id
                    }
                )
                .await
            );
            assert!(
                matches!(rx.try_recv(), Ok(HostCommand::Stop { session_id }) if session_id == active_id)
            );
            let workspace = store.workspace_store().await.unwrap().unwrap();
            let binding = store.workspace_binding(session_id).await.unwrap().unwrap();
            workspace
                .ensure_execution_workspace(
                    binding.workspace_id,
                    "Replay test",
                    crate::local_human_participant_id("Human"),
                    "Human",
                    session_id,
                    "Recipient",
                )
                .await
                .unwrap();
            let incoming = crate::WorkspaceMessage {
                id: message_id,
                workspace_id: binding.workspace_id,
                author_id: Uuid::new_v4(),
                thread_id: None,
                reply_to_message_id: None,
                body: crate::WorkspaceMessageBody {
                    text: "retain while authorization is expired".into(),
                    mentions: vec![],
                    attachments: Vec::new(),
                },
                audience: Audience::Direct {
                    participant: session_id,
                },
                created_at: Utc::now(),
            };
            workspace
                .import_relay_message(
                    incoming.clone(),
                    "Sender",
                    session_id,
                    crate::DeliveryMode::NextTurn,
                )
                .await
                .unwrap();
            assert!(workspace.contains_message(message_id).await.unwrap());
            drop(workspace);
            drop(store);
            let store: Arc<dyn SessionStore> = Arc::new(
                PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                    .await
                    .unwrap(),
            );
            for field in ["text", "attachments", "delivery"] {
                let mut conflicting = prompt();
                let HostCommand::Prompt {
                    text,
                    attachments,
                    delivery,
                    ..
                } = &mut conflicting
                else {
                    unreachable!()
                };
                match field {
                    "text" => *text = "changed after admission".into(),
                    "attachments" => attachments.clear(),
                    "delivery" => {
                        *delivery = match delivery {
                            crate::PromptDelivery::Queue => crate::PromptDelivery::Steer,
                            crate::PromptDelivery::Steer => crate::PromptDelivery::Queue,
                        }
                    }
                    _ => unreachable!(),
                }
                assert!(
                    !dispatch(context(&store), conflicting).await,
                    "workspace presence must not acknowledge changed {field} as an exact retry"
                );
            }
            assert!(dispatch(context(&store), prompt()).await);
            assert_eq!(
                serde_json::to_value(store.events_after(session_id, 0, 20).await.unwrap()).unwrap(),
                admitted
            );
            assert_eq!(store.pending_actions(session_id, 8).await.unwrap().len(), 1);
            store
                .append(SessionEvent::new(
                    session_id,
                    0,
                    crate::SessionEventKind::Message {
                        message_id,
                        actor: crate::EventActor::User,
                        text: "coalesced execution payload".into(),
                        attachments: vec![],
                        status: crate::MessageStatus::InProgress,
                        delivery: Some(delivery),
                    },
                ))
                .await
                .unwrap();
            let action =
                serde_json::to_value(store.action(session_id, message_id).await.unwrap()).unwrap();
            let sequence = store.state(session_id).await.unwrap().latest_sequence;
            assert!(dispatch(context(&store), prompt()).await);
            assert_eq!(
                serde_json::to_value(store.action(session_id, message_id).await.unwrap()).unwrap(),
                action,
                "exact replay validates the original journal, not the coalesced action payload"
            );
            assert_eq!(
                store.state(session_id).await.unwrap().latest_sequence,
                sequence
            );
            sessions.lock().await.clear();
            resume_pending_host_sessions(
                0,
                &client,
                &config,
                root.path(),
                &sessions,
                &host_store(&scratch).await,
                &executor,
            )
            .await
            .unwrap();
            assert!(
                sessions.lock().await.is_empty(),
                "free capacity must not bypass lease authorization"
            );
            assert_eq!(
                store.state(session_id).await.unwrap().status,
                Some(crate::SessionStatus::Ready)
            );
            let schema_id = Uuid::new_v4();
            assert!(
                !dispatch(
                    context(&store),
                    HostCommand::Prompt {
                        session_id,
                        message_id: schema_id,
                        text: "requires schema".into(),
                        attachments: vec![],
                        output_schema: Some(serde_json::json!({"type":"object"})),
                        delivery: crate::PromptDelivery::Queue,
                    }
                )
                .await
            );
            assert!(!store.contains_message(session_id, schema_id).await.unwrap());
            let writer =
                SessionWriterLease::acquire(root.path().join(format!("{session_id}.lock")))
                    .unwrap();
            assert!(!dispatch(context(&store), HostCommand::Stop { session_id }).await);
            drop(writer);
            assert!(dispatch(context(&store), HostCommand::Stop { session_id }).await);
            assert_eq!(
                store.state(session_id).await.unwrap().status,
                Some(crate::SessionStatus::Stopped)
            );
            assert!(
                store
                    .pending_actions(session_id, 8)
                    .await
                    .unwrap()
                    .is_empty()
            );
            assert!(
                store
                    .pending_host_launch_metadata(8)
                    .await
                    .unwrap()
                    .is_empty()
            );
            assert!(
                store
                    .pending_host_journals(None, 8)
                    .await
                    .unwrap()
                    .contains(&session_id)
            );
            assert!(dispatch(context(&store), prompt()).await);
            assert!(sessions.lock().await.is_empty());
            assert_eq!(
                store.load_host_launch_metadata(session_id).await.unwrap(),
                Some(metadata)
            );
            // Workspace-only delivery must remain in the inbox, not become a new local action.
            let workspace = store.workspace_store().await.unwrap().unwrap();
            let workspace_only_id = Uuid::new_v4();
            let mut workspace_only = incoming;
            workspace_only.id = workspace_only_id;
            workspace
                .import_relay_message(
                    workspace_only,
                    "Sender",
                    session_id,
                    crate::DeliveryMode::NextTurn,
                )
                .await
                .unwrap();
            admit_remote_prompt(
                store.as_ref(),
                session_id,
                workspace_only_id,
                "retain while authorization is expired",
                &[],
                delivery,
            )
            .await
            .unwrap();
            assert!(
                store
                    .action(session_id, workspace_only_id)
                    .await
                    .unwrap()
                    .is_none()
            );
            assert!(
                !store
                    .contains_message(session_id, workspace_only_id)
                    .await
                    .unwrap()
            );

            // A settled history entry may be inherited without its parent-owned action.
            store
                .append(SessionEvent::new(
                    session_id,
                    0,
                    crate::SessionEventKind::Message {
                        message_id,
                        actor: crate::EventActor::User,
                        text: "retain while authorization is expired".into(),
                        attachments: vec![root.path().join("note.txt")],
                        status: crate::MessageStatus::Complete,
                        delivery: Some(delivery),
                    },
                ))
                .await
                .unwrap();
            let fork_id = Uuid::new_v4();
            let cut = store.state(session_id).await.unwrap().latest_sequence + 1;
            store.fork_before(session_id, fork_id, cut).await.unwrap();
            assert!(store.contains_message(fork_id, message_id).await.unwrap());
            let inherited = store.state(fork_id).await.unwrap().latest_sequence;
            admit_remote_prompt(
                store.as_ref(),
                fork_id,
                message_id,
                "retain while authorization is expired",
                &[root.path().join("note.txt")],
                delivery,
            )
            .await
            .unwrap();
            assert!(store.action(fork_id, message_id).await.unwrap().is_none());
            assert_eq!(
                store.state(fork_id).await.unwrap().latest_sequence,
                inherited
            );
            assert!(
                tokio::time::timeout(Duration::from_millis(50), listener.accept())
                    .await
                    .is_err(),
                "durable deferral and inactive Stop must not contact the relay"
            );
            scratch.discard().await;
        }
    }

    #[tokio::test]
    async fn inactive_commands_respect_capacity_and_stop_without_starting_an_actor() {
        let host = Uuid::new_v4();
        with_test_transport(host, |_frames| async move {
        let root = tempdir().unwrap();
        let mut config = test_config_for(root.path(), host);
        config.resource_limits.max_concurrent_sessions = 1;
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        config.server = format!("http://{}", listener.local_addr().unwrap());
        let (scratch, postgres) = crate::session_store::postgres::testing::session_store().await;
        let store: Arc<dyn SessionStore> = Arc::new(postgres);
        let session_id = Uuid::new_v4();
        let launch = bootstrap_test_launch(root.path());
        persist_launch_metadata(&config, store.as_ref(), session_id, &launch, None)
            .await
            .unwrap();
        store.create_session(session_id).await.unwrap();
        for kind in [
            crate::SessionEventKind::SessionStarted,
            crate::SessionEventKind::SessionConfigured {
                cwd: launch.cwd.clone(),
                provider: launch.provider,
                model: None,
                effort: None,
                fast: false,
                ultrafast: false,
                response_language: launch.response_language,
                permission_mode: launch.permission_mode,
                speed_support: Default::default(),
            },
            crate::SessionEventKind::StatusChanged {
                lifecycle: Some(crate::SessionStatus::Ready.into()),
                status: crate::SessionStatus::Ready,
                detail: None,
            },
        ] {
            store
                .append(SessionEvent::new(session_id, 0, kind))
                .await
                .unwrap();
        }
        // Same authority as the journal, obtained the way production does.
        let receipts = store.receipt_store().await.unwrap();
        let sessions = Arc::new(Mutex::new(HashMap::new()));
        let active_id = Uuid::new_v4();
        let (tx, mut rx) = mpsc::channel(2);
        sessions.lock().await.insert(active_id, tx.clone());
        let client = Client::builder()
            .timeout(Duration::from_secs(1))
            .build()
            .unwrap();
        let context = |store: &Arc<dyn SessionStore>| DispatchContext {
            client: client.clone(),
            config: config.clone(),
            session_root: root.path().to_path_buf(),
            sessions: Arc::clone(&sessions),
            session_store: Arc::clone(store),
            receipts: Arc::clone(&receipts),
            executor_factory: Arc::new(|_, _| {
                panic!("capacity or inactive Stop must not construct a provider")
            }),
        };
        let message_id = Uuid::new_v4();
        let prompt = || HostCommand::Prompt {
            session_id,
            message_id,
            text: "wait for an execution slot".to_string(),
            attachments: vec![],
            output_schema: None,
            delivery: crate::PromptDelivery::Queue,
        };
        assert!(dispatch(context(&store), prompt()).await);
        assert_eq!(
            sessions.lock().await.len(),
            1,
            "restoration must not bypass execution capacity"
        );
        assert_eq!(
            store.pending_host_launch_metadata(8).await.unwrap()[0].0,
            session_id
        );
        assert!(
            dispatch(
                context(&store),
                HostCommand::Stop {
                    session_id: active_id
                }
            )
            .await
        );
        assert!(
            matches!(rx.try_recv(), Ok(HostCommand::Stop { session_id }) if session_id == active_id)
        );
        let reopened: Arc<dyn SessionStore> = Arc::new(
            PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                .await
                .unwrap(),
        );
        assert!(
            reopened
                .contains_message(session_id, message_id)
                .await
                .unwrap()
        );
        assert!(dispatch(context(&reopened), prompt()).await);
        assert_eq!(
            reopened.pending_actions(session_id, 8).await.unwrap().len(),
            1
        );
        let executor: HostExecutorFactory =
            Arc::new(|_, _| panic!("recovery probe must fail before provider construction"));
        resume_pending_host_sessions(
            0,
            &client,
            &config,
            root.path(),
            &sessions,
            &reopened,
            &executor,
        )
        .await
        .unwrap();
        assert_eq!(sessions.lock().await.len(), 1);
        let schema_id = Uuid::new_v4();
        assert!(
            !dispatch(
                context(&reopened),
                HostCommand::Prompt {
                    session_id,
                    message_id: schema_id,
                    text: "requires a schema".to_string(),
                    attachments: vec![],
                    output_schema: Some(serde_json::json!({"type":"object"})),
                    delivery: crate::PromptDelivery::Queue
                }
            )
            .await
        );
        assert!(
            !reopened
                .contains_message(session_id, schema_id)
                .await
                .unwrap()
        );
        assert!(!dispatch(context(&reopened), HostCommand::Interrupt { session_id }).await);
        // A free slot schedules the durable prompt without another relay command.
        sessions.lock().await.clear();
        resume_pending_host_sessions(
            0,
            &client,
            &config,
            root.path(),
            &sessions,
            &reopened,
            &executor,
        )
        .await
        .unwrap();
        assert!(sessions.lock().await.contains_key(&session_id));
        let (mut stream, _) = tokio::time::timeout(Duration::from_secs(5), listener.accept())
            .await
            .unwrap()
            .unwrap();
        let (path, _) = read_http_request(&mut stream).await;
        assert!(path.ends_with("/runtime-context"), "unexpected relay request {path}");
        stream
            .write_all(
                b"HTTP/1.1 401 Unauthorized\r\ncontent-length: 0\r\nconnection: close\r\n\r\n",
            )
            .await
            .unwrap();
        drop(stream);
        tokio::time::timeout(Duration::from_secs(5), async {
            while sessions.lock().await.contains_key(&session_id) {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap();
        assert_eq!(
            reopened.pending_actions(session_id, 8).await.unwrap().len(),
            1,
            "failed startup must not erase the deferred prompt"
        );
        sessions.lock().await.insert(active_id, tx);
        // A second host can already be awaiting context before this host stops the session.
        let (_stale_tx, stale_rx) = mpsc::channel(1);
        let stale_startup = host_transport::spawn(run_session(
            client.clone(),
            config.clone(),
            root.path().to_path_buf(),
            Arc::clone(&executor),
            HostSessionLaunch {
                session_id,
                request: launch.clone(),
                attachment: None,
            },
            stale_rx,
            host_store(&scratch).await,
        ));
        let (mut stale_stream, _) = tokio::time::timeout(Duration::from_secs(5), listener.accept())
            .await
            .unwrap()
            .unwrap();
        let _ = read_http_request(&mut stale_stream).await;
        let writer =
            SessionWriterLease::acquire(root.path().join(format!("{session_id}.lock"))).unwrap();
        assert!(
            !dispatch(context(&reopened), HostCommand::Stop { session_id }).await,
            "an inactive map entry is not proof that another process released the writer"
        );
        drop(writer);
        assert!(dispatch(context(&reopened), HostCommand::Stop { session_id }).await);
        stale_stream
            .write_all(
                b"HTTP/1.1 404 Not Found
content-length: 0
connection: close

",
            )
            .await
            .unwrap();
        drop(stale_stream);
        tokio::time::timeout(Duration::from_secs(5), stale_startup)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        assert_eq!(
            reopened.state(session_id).await.unwrap().status,
            Some(crate::SessionStatus::Stopped)
        );
        assert!(
            reopened
                .pending_actions(session_id, 8)
                .await
                .unwrap()
                .is_empty()
        );
        assert!(
            reopened
                .pending_host_launch_metadata(8)
                .await
                .unwrap()
                .is_empty()
        );
        assert!(
            reopened
                .pending_host_journals(None, 8)
                .await
                .unwrap()
                .contains(&session_id),
            "terminal output must remain independently uploadable"
        );
        sessions.lock().await.clear();
        assert!(dispatch(context(&reopened), HostCommand::Stop { session_id }).await);
        assert!(dispatch(context(&reopened), prompt()).await);
        assert!(
            dispatch(
                context(&reopened),
                HostCommand::Launch {
                    session_id,
                    request: Box::new(launch),
                    attachment: None
                }
            )
            .await
        );
        assert!(
            sessions.lock().await.is_empty(),
            "terminal retry cannot resurrect an actor after capacity frees"
        );
        scratch.discard().await;
    })
        .await
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn queued_shell_does_not_block_controls_and_recovers_results_without_reexecution() {
        let host = Uuid::new_v4();
        with_test_transport(host, |mut frames| async move {
        let root = tempdir().unwrap();
        let mut config = test_config_for(root.path(), host);
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        config.server = format!("http://{}", listener.local_addr().unwrap());
        let _relay = spawn_not_found_relay(listener);
        let (scratch, postgres) = crate::session_store::postgres::testing::session_store().await;
        // Kept alongside the trait handle purely so the assertion below can
        // read `quarantine_reason` directly. The queue API deliberately does
        // not expose that column -- quarantine is a terminal state callers act
        // on, not inspect -- so the probe reaches past the trait on purpose.
        let probe_pool = postgres.pool().clone();
        let store: Arc<dyn SessionStore> = Arc::new(postgres);
        host_transport::get(host)
            .unwrap()
            .set_ledger(
                crate::command_ledger::CommandLedger::open(probe_pool.clone())
                    .await
                    .unwrap(),
            )
            .unwrap();
        // Terminal results leave through the tunnel; collect them by command.
        let mut published = HashMap::<String, serde_json::Value>::new();
        let result_for = async |frames: &mut mpsc::UnboundedReceiver<crate::auth::TunnelFrame>,
                                    published: &mut HashMap<String, serde_json::Value>,
                                    id: Uuid| {
            tokio::time::timeout(Duration::from_secs(5), async {
                loop {
                    if let Some(outcome) = published.get(&id.to_string()) {
                        return outcome.clone();
                    }
                    if let Some(crate::auth::TunnelFrame::HostCommandResult {
                        command_id, outcome, ..
                    }) = frames.recv().await
                    {
                        published.insert(command_id, outcome);
                    }
                }
            })
            .await
            .expect("terminal result must be published through the tunnel")
        };
        // Same authority as the journal, obtained the way production does.
        let receipts = store.receipt_store().await.unwrap();
        let sessions = Arc::new(Mutex::new(HashMap::new()));
        let active_id = Uuid::new_v4();
        let (tx, mut rx) = mpsc::channel(2);
        sessions.lock().await.insert(active_id, tx);
        let client = Client::builder()
            .timeout(Duration::from_secs(10))
            .build()
            .unwrap();
        let context = || DispatchContext {
            client: client.clone(),
            config: config.clone(),
            session_root: root.path().to_path_buf(),
            sessions: Arc::clone(&sessions),
            session_store: Arc::clone(&store),
            receipts: Arc::clone(&receipts),
            executor_factory: Arc::new(|_, _| panic!("host operation must not construct an agent")),
        };
        let poisoned = Uuid::new_v4();
        receipts
            .enqueue_host_command(
                config.host_id,
                poisoned,
                &serde_json::json!({"type": "unknown_future_command"}),
            )
            .await
            .unwrap();
        let request = HostShellCommandRequest {
            request_id: Uuid::new_v4(), cwd: root.path().to_path_buf(),
            command: format!("/bin/sh -c {}", serde_json::to_string("printf x >> executions; touch started; while [ ! -f release ]; do sleep 0.02; done; printf done").unwrap()),
            timeout_ms: 10_000, output_max_bytes: 1_024,
        };
        assert!(
            tokio::time::timeout(
                Duration::from_secs(2),
                dispatch(
                    context(),
                    HostCommand::ShellCommand {
                        request: request.clone()
                    }
                )
            )
            .await
            .unwrap()
        );
        let uncertain = WorkspaceCommandRequest {
            request_id: Uuid::new_v4(),
            workspace_id: Uuid::new_v4(),
            root_path: root.path().to_path_buf(),
            cwd: PathBuf::from("."),
            command: vec!["touch".to_string(), "must-not-run".to_string()],
            timeout_ms: 1_000,
            output_max_bytes: 1_024,
        };
        receipts
            .begin(uncertain.request_id, &uncertain)
            .await
            .unwrap();
        assert!(
            dispatch(
                context(),
                HostCommand::WorkspaceCommand {
                    request: uncertain.clone()
                }
            )
            .await
        );
        let cancelled = WorkspaceCommandRequest {
            request_id: Uuid::new_v4(),
            command: vec!["touch".to_string(), "cancelled-must-not-run".to_string()],
            ..uncertain.clone()
        };
        assert!(
            dispatch(
                context(),
                HostCommand::WorkspaceCommand {
                    request: cancelled.clone()
                }
            )
            .await
        );
        let mismatched = Uuid::new_v4();
        receipts
            .enqueue_host_command(
                config.host_id,
                mismatched,
                &HostCommand::WorkspaceCommand {
                    request: cancelled.clone(),
                },
            )
            .await
            .unwrap();
        assert!(
            dispatch(
                context(),
                HostCommand::CancelWorkspaceCommand {
                    request_id: mismatched
                }
            )
            .await
        );
        assert!(matches!(
            receipts
                .load::<_, WorkspaceCommandResponse>(cancelled.request_id, &cancelled)
                .await
                .unwrap(),
            ReceiptState::Missing
        ));
        let first = host_transport::spawn(run_host_operation_loop(
            client.clone(),
            config.clone(),
            Arc::clone(&receipts),
            root.path().to_path_buf(),
        ));
        tokio::time::timeout(Duration::from_secs(5), async {
            while !root.path().join("started").exists() {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap();
        assert!(
            SessionWriterLease::try_acquire(root.path().join("host-operations.lock"))
                .unwrap()
                .is_none()
        );
        let second = host_transport::spawn(run_host_operation_loop(
            client.clone(),
            config.clone(),
            Arc::clone(&receipts),
            root.path().to_path_buf(),
        ));
        for command in [
            HostCommand::Stop {
                session_id: active_id,
            },
            HostCommand::Interrupt {
                session_id: active_id,
            },
        ] {
            assert!(
                tokio::time::timeout(Duration::from_secs(2), dispatch(context(), command))
                    .await
                    .unwrap()
            );
        }
        assert!(
            matches!(rx.try_recv(), Ok(HostCommand::Stop { session_id }) if session_id == active_id)
        );
        assert!(
            matches!(rx.try_recv(), Ok(HostCommand::Interrupt { session_id }) if session_id == active_id)
        );
        assert!(matches!(
            receipts
                .load::<_, HostShellCommandResponse>(request.request_id, &request)
                .await
                .unwrap(),
            ReceiptState::Started
        ));
        // Ownership alone is not durable admission: retry cancellation until the receipt exists.
        let owner = SessionWriterLease::try_acquire(
            root.path()
                .join(format!("host-operation-{}.lock", cancelled.request_id)),
        )
        .unwrap()
        .unwrap();
        assert!(
            !dispatch(
                context(),
                HostCommand::CancelWorkspaceCommand {
                    request_id: cancelled.request_id
                }
            )
            .await
        );
        assert!(matches!(
            receipts
                .load::<_, WorkspaceCommandResponse>(cancelled.request_id, &cancelled)
                .await
                .unwrap(),
            ReceiptState::Missing
        ));
        drop(owner);
        for request_id in [uncertain.request_id, cancelled.request_id] {
            assert!(
                dispatch(
                    context(),
                    HostCommand::CancelWorkspaceCommand { request_id }
                )
                .await
            );
        }
        assert!(matches!(
            receipts
                .load::<_, WorkspaceCommandResponse>(uncertain.request_id, &uncertain)
                .await
                .unwrap(),
            ReceiptState::Started
        ));
        assert!(matches!(
            receipts
                .load::<_, WorkspaceCommandResponse>(cancelled.request_id, &cancelled)
                .await
                .unwrap(),
            ReceiptState::Terminal(_)
        ));
        fs::write(root.path().join("release"), "go").unwrap();
        let shell = result_for(&mut frames, &mut published, request.request_id).await;
        assert_eq!(shell["outcome"]["type"], "success");
        first.abort();
        second.abort();
        let _ = first.await;
        let _ = second.await;
        assert!(
            receipts
                .next_host_operation(config.host_id)
                .await
                .unwrap()
                .is_some()
        );
        drop(receipts);
        drop(store);

        let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
            .await
            .unwrap();
        // Same authority as the journal, obtained the way production does.
        let receipts = store.receipt_store().await.unwrap();
        let _worker = AbortTask(host_transport::spawn(run_host_operation_loop(
            client,
            config.clone(),
            Arc::clone(&receipts),
            root.path().to_path_buf(),
        )));
        assert_eq!(
            result_for(&mut frames, &mut published, uncertain.request_id).await["outcome"]["code"],
            "indeterminate"
        );
        assert_eq!(
            result_for(&mut frames, &mut published, cancelled.request_id).await["outcome"]["code"],
            "cancelled"
        );
        tokio::time::timeout(Duration::from_secs(5), async {
            while receipts
                .next_host_operation(config.host_id)
                .await
                .unwrap()
                .is_some()
            {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap();
        assert_eq!(
            fs::read_to_string(root.path().join("executions")).unwrap(),
            "x"
        );
        assert!(!root.path().join("must-not-run").exists());
        assert!(!root.path().join("cancelled-must-not-run").exists());
        let reason: Option<String> = sqlx::query_scalar(
            "select quarantine_reason from host_operation_queue where request_id=$1",
        )
        .bind(poisoned.to_string())
        .fetch_one(&probe_pool)
        .await
        .unwrap();
        assert!(
            reason.is_some(),
            "unsupported command is retained, not executed or silently deleted"
        );
        scratch.discard().await;
    })
        .await
    }

    #[tokio::test]
    async fn workspace_roster_recovers_without_restarting_or_losing_queued_messages() {
        let root = tempdir().unwrap();
        let (scratch, store) = crate::session_store::postgres::testing::session_store().await;
        let id = Uuid::new_v4();
        store.create_session(id).await.unwrap();
        let binding = store.workspace_binding(id).await.unwrap().unwrap();
        let workspace = store.workspace_store().await.unwrap().unwrap();
        workspace
            .ensure_execution_workspace(
                binding.workspace_id,
                "Shared",
                crate::local_human_participant_id("Human"),
                "Human",
                id,
                "Sender",
            )
            .await
            .unwrap();
        workspace
            .append_message(crate::NewWorkspaceMessage {
                workspace_id: binding.workspace_id,
                author_id: id,
                text: "queued through roster recovery".to_string(),
                mentions: Vec::new(),
                attachments: Vec::new(),
                audience: Audience::Workspace,
                mode: crate::DeliveryMode::NextTurn,
                thread_id: None,
                reply_to_message_id: None,
                idempotency_key: "roster-recovery".to_string(),
            })
            .await
            .unwrap();
        let original = workspace
            .replay(binding.workspace_id, id, 0, 256)
            .await
            .unwrap()
            .into_iter()
            .find(|event| matches!(event.kind, WorkspaceEventKind::Message { .. }))
            .unwrap();
        let peer = Uuid::new_v4();
        let roster = serde_json::json!({"participants": [{
            "id": peer, "kind": "agent", "role": "contributor",
            "display_name": "Recovered peer", "created_at": Utc::now(),
        }]})
        .to_string();
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let config = HostConfig {
            server: format!("http://{}", listener.local_addr().unwrap()),
            ..test_config(root.path())
        };
        let status = Arc::new(AtomicU16::new(404));
        let server_status = Arc::clone(&status);
        let (sent, mut requests) = mpsc::channel(8);
        let _server = AbortTask(host_transport::spawn(async move {
            loop {
                let (mut socket, _) = listener.accept().await.unwrap();
                let (path, body) = read_http_request(&mut socket).await;
                let participants = path.ends_with("/workspace/participants");
                assert!(participants || path.ends_with("/workspace/messages"));
                sent.send((path, body)).await.unwrap();
                let mode = server_status.load(Ordering::SeqCst);
                let (code, response) = if !participants {
                    (204, "")
                } else if mode == 200 {
                    (200, roster.as_str())
                } else if mode == 1 {
                    (200, "{")
                } else {
                    (mode, "")
                };
                socket.write_all(format!("HTTP/1.1 {code} Test\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{response}",response.len()).as_bytes()).await.unwrap();
            }
        }));
        let client = Client::builder()
            .timeout(Duration::from_secs(2))
            .build()
            .unwrap();
        let mut sync = JournalSync::new(true, PathBuf::new());
        sync.next_inbox_sync = Instant::now() + Duration::from_secs(60);
        sync.next_instance_directory_sync = Instant::now() + Duration::from_secs(60);
        for mode in [404, 503, 1, 200] {
            status.store(mode, Ordering::SeqCst);
            sync.next_workspace_roster_sync = Instant::now();
            flush_workspace_messages(
                &client,
                &config,
                &store,
                Some(workspace.as_ref()),
                id,
                Some(binding.workspace_id),
                &mut sync,
            )
            .await
            .unwrap();
            let request = requests
                .try_recv()
                .expect("an unavailable roster must be probed again when its retry is due");
            assert!(request.0.ends_with("/workspace/participants"));
            if mode == 200 {
                break;
            }
            assert!(!sync.workspace_relay_available);
            assert!(
                requests.try_recv().is_err(),
                "unverified roster recovery must not release shared messages"
            );
            assert!(
                sync.uploaded_workspace_sequences
                    .get(&binding.workspace_id)
                    .copied()
                    .unwrap_or_default()
                    < original.sequence
            );
            // Normal poll ticks before the retry time must not hammer discovery.
            flush_workspace_messages(
                &client,
                &config,
                &store,
                Some(workspace.as_ref()),
                id,
                Some(binding.workspace_id),
                &mut sync,
            )
            .await
            .unwrap();
            assert!(requests.try_recv().is_err());
        }
        let upload = requests
            .try_recv()
            .expect("queued shared message must upload after roster recovery");
        assert!(upload.0.ends_with("/workspace/messages"));
        let body: serde_json::Value = serde_json::from_slice(&upload.1).unwrap();
        assert_eq!(body["text"], "queued through roster recovery");
        assert_eq!(body["idempotency_key"], original.id.to_string());
        assert!(
            workspace
                .workspace_roster(binding.workspace_id, id)
                .await
                .unwrap()
                .iter()
                .any(|entry| entry.participant.id == peer
                    && entry.role == WorkspaceRole::Contributor)
        );
        assert!(sync.uploaded_workspace_sequences[&binding.workspace_id] >= original.sequence);
        flush_workspace_messages(
            &client,
            &config,
            &store,
            Some(workspace.as_ref()),
            id,
            Some(binding.workspace_id),
            &mut sync,
        )
        .await
        .unwrap();
        assert!(
            requests.try_recv().is_err(),
            "caught-up messages and a fresh roster must not repeat"
        );
        scratch.discard().await;
    }

    #[tokio::test]
    async fn failed_shared_upload_does_not_skip_private_messages_or_advance_its_cursor() {
        let root = tempdir().unwrap();
        let (scratch, store) = crate::session_store::postgres::testing::session_store().await;
        let session_id = Uuid::new_v4();
        store.create_session(session_id).await.unwrap();
        let binding = store.workspace_binding(session_id).await.unwrap().unwrap();
        let workspace = store.workspace_store().await.unwrap().unwrap();
        workspace
            .ensure_execution_workspace(
                binding.workspace_id,
                "Sender",
                crate::local_human_participant_id("Human"),
                "Human",
                session_id,
                "Sender",
            )
            .await
            .unwrap();
        let recipient = Uuid::new_v4();
        workspace
            .upsert_instance(
                Participant {
                    id: recipient,
                    display_name: "Remote".to_string(),
                    kind: ParticipantKind::Agent,
                    created_at: Utc::now(),
                },
                Some(Uuid::new_v4()),
                None,
            )
            .await
            .unwrap();
        let direct = workspace
            .ensure_direct_workspace(session_id, recipient)
            .await
            .unwrap();
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let config = HostConfig {
            server: format!("http://{}", listener.local_addr().unwrap()),
            ..test_config(root.path())
        };
        persist_launch_metadata(
            &config,
            &store,
            session_id,
            &bootstrap_test_launch(root.path()),
            None,
        )
        .await
        .unwrap();
        let status = Arc::new(AtomicU16::new(503));
        let server_status = Arc::clone(&status);
        let (sent, mut received) = mpsc::channel(32);
        let _server = AbortTask(host_transport::spawn(async move {
            loop {
                let (mut socket, _) = listener.accept().await.unwrap();
                let (path, body) = read_http_request(&mut socket).await;
                let shared = path.ends_with("/workspace/messages");
                assert!(
                    path.ends_with("/messages"),
                    "unexpected relay request {path}"
                );
                sent.send((
                    shared,
                    serde_json::from_slice::<serde_json::Value>(&body).unwrap(),
                ))
                .await
                .unwrap();
                let status = if shared {
                    server_status.load(Ordering::SeqCst)
                } else {
                    204
                };
                if status == 0 {
                    continue;
                } // Lost response, not an acknowledged upload.
                socket.write_all(format!("HTTP/1.1 {status} Response\r\ncontent-length: 0\r\nconnection: close\r\n\r\n").as_bytes()).await.unwrap();
            }
        }));
        let client = Client::builder()
            .timeout(Duration::from_secs(2))
            .build()
            .unwrap();
        let mut first_shared = None;
        for (attempt, rejection) in [503, 0, 404].into_iter().enumerate() {
            status.store(rejection, Ordering::SeqCst);
            for (workspace_id, audience, text) in [
                (binding.workspace_id, Audience::Workspace, "shared"),
                (
                    direct,
                    Audience::Direct {
                        participant: recipient,
                    },
                    "private",
                ),
            ] {
                workspace
                    .append_message(crate::NewWorkspaceMessage {
                        workspace_id,
                        author_id: session_id,
                        text: format!("{text}-{attempt}"),
                        mentions: Vec::new(),
                        attachments: Vec::new(),
                        audience,
                        mode: crate::DeliveryMode::NextTurn,
                        thread_id: None,
                        reply_to_message_id: None,
                        idempotency_key: format!("{text}-{attempt}"),
                    })
                    .await
                    .unwrap();
            }
            let later = Instant::now() + Duration::from_secs(60);
            let mut sync = JournalSync::new(true, PathBuf::new());
            sync.uploaded_workspace_sequences = store
                .host_workspace_cursors(config.host_id, session_id)
                .await
                .unwrap();
            // A blocked session journal must not suppress independent messages.

            sync.next_inbox_sync = later;
            sync.next_instance_directory_sync = later;
            sync.next_workspace_roster_sync = later;
            flush_host_workspace_messages(
                &client,
                &config,
                &store,
                Some(workspace.as_ref()),
                session_id,
                Some(binding.workspace_id),
                &mut sync,
            )
            .await
            .unwrap();
            let rejected = tokio::time::timeout(Duration::from_secs(2), received.recv())
                .await
                .expect("message uploads must progress during journal backoff")
                .unwrap();
            assert!(rejected.0);
            if let Some(first) = &first_shared {
                assert_eq!(
                    &rejected.1, first,
                    "retry must keep the original event and FIFO order"
                );
            } else {
                first_shared = Some(rejected.1.clone());
            }
            let delivered = received.try_recv().expect(
                "a failed shared upload must not skip an unrelated private message in the same pass");
            assert!(!delivered.0);
            assert_eq!(delivered.1["text"], format!("private-{attempt}"));
            assert!(
                received.try_recv().is_err(),
                "later shared messages must not overtake the failed one"
            );
            let cursors = store
                .host_workspace_cursors(config.host_id, session_id)
                .await
                .unwrap();
            let rejected_sequence = rejected.1["metadata"]["local_workspace_sequence"]
                .as_u64()
                .unwrap();
            assert!(
                cursors
                    .get(&binding.workspace_id)
                    .copied()
                    .unwrap_or_default()
                    < rejected_sequence
            );
            assert!(
                cursors[&direct]
                    >= delivered.1["metadata"]["local_workspace_sequence"]
                        .as_u64()
                        .unwrap()
            );
        }
        drop(workspace);
        drop(store);
        let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
            .await
            .unwrap();
        let workspace = store.workspace_store().await.unwrap().unwrap();
        status.store(204, Ordering::SeqCst);
        let later = Instant::now() + Duration::from_secs(60);
        let mut sync = JournalSync::new(true, PathBuf::new());
        sync.uploaded_workspace_sequences = store
            .host_workspace_cursors(config.host_id, session_id)
            .await
            .unwrap();
        sync.next_inbox_sync = later;
        sync.next_instance_directory_sync = later;
        sync.next_workspace_roster_sync = later;
        assert!(
            flush_host_workspace_messages(
                &client,
                &config,
                &store,
                Some(workspace.as_ref()),
                session_id,
                Some(binding.workspace_id),
                &mut sync
            )
            .await
            .unwrap()
        );
        for attempt in 0..3 {
            let uploaded = received.recv().await.unwrap();
            assert!(uploaded.0);
            assert_eq!(uploaded.1["text"], format!("shared-{attempt}"));
            if attempt == 0 {
                assert_eq!(Some(uploaded.1), first_shared);
            }
        }
        assert!(
            received.try_recv().is_err(),
            "acknowledged private messages must not replay after reopen"
        );
        scratch.discard().await;
    }

    #[tokio::test]
    async fn stopped_host_recovers_final_messages_without_an_actor_or_pending_journal() {
        let host = Uuid::new_v4();
        with_test_transport(host, |_frames| async move {
        let root = tempdir().unwrap();
        let (scratch, store) = crate::session_store::postgres::testing::session_store().await;
        // Current-v5 databases acquire the additive table without losing their journal.
        sqlx::query("drop table host_workspace_cursors")
            .execute(store.pool())
            .await
            .unwrap();
        // The dropped table only comes back if the database also stops
        // claiming this schema is already applied.
        sqlx::query("update borg_session_schema set definition_hash = null")
            .execute(store.pool())
            .await
            .unwrap();
        drop(store);
        let store: Arc<dyn SessionStore> = Arc::new(
            PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                .await
                .unwrap(),
        );
        let session_id = Uuid::new_v4();
        let recipient = Uuid::new_v4();
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let mut config = test_config_for(root.path(), host);
        config.server = format!("http://{}", listener.local_addr().unwrap());
        config.resource_limits.max_concurrent_sessions = 1;
        store.create_session(session_id).await.unwrap();
        let binding = store.workspace_binding(session_id).await.unwrap().unwrap();
        let attachment = WorkspaceAttachment {
            workspace_id: Some(binding.workspace_id),
            participant_id: Some(session_id),
            command_authority: None,
            host_identity: None,
            host_capabilities: None,
            presence_lease: None,
            approval_provenance: None,
            reconnect_sync_cursors: None,
        };
        persist_launch_metadata(
            &config,
            store.as_ref(),
            session_id,
            &bootstrap_test_launch(root.path()),
            Some(&attachment),
        )
        .await
        .unwrap();
        store
            .attach_workspace(crate::SessionWorkspaceBinding {
                host_id: Some(config.host_id),
                ..binding.clone()
            })
            .await
            .unwrap();
        let workspace = store.workspace_store().await.unwrap().unwrap();
        workspace
            .ensure_execution_workspace(
                binding.workspace_id,
                "Sender",
                crate::local_human_participant_id("Human"),
                "Human",
                session_id,
                "Sender",
            )
            .await
            .unwrap();
        workspace
            .upsert_instance(
                Participant {
                    id: recipient,
                    display_name: "Remote".to_string(),
                    kind: ParticipantKind::Agent,
                    created_at: Utc::now(),
                },
                Some(Uuid::new_v4()),
                None,
            )
            .await
            .unwrap();
        let direct = workspace
            .ensure_direct_workspace(session_id, recipient)
            .await
            .unwrap();
        workspace
            .append_message(crate::NewWorkspaceMessage {
                workspace_id: direct,
                author_id: session_id,
                text: "final private report".to_string(),
                mentions: Vec::new(),
                attachments: Vec::new(),
                audience: Audience::Direct {
                    participant: recipient,
                },
                mode: crate::DeliveryMode::NextTurn,
                thread_id: None,
                reply_to_message_id: None,
                idempotency_key: "final-report".to_string(),
            })
            .await
            .unwrap();
        let stopped = store
            .append(SessionEvent::new(
                session_id,
                0,
                crate::SessionEventKind::StatusChanged {
                    lifecycle: Some(crate::SessionStatus::Stopped.into()),
                    status: crate::SessionStatus::Stopped,
                    detail: None,
                },
            ))
            .await
            .unwrap();
        store
            .acknowledge_host_journal(session_id, stopped.sequence, 0)
            .await
            .unwrap();
        assert!(
            store
                .pending_host_journals(None, 8)
                .await
                .unwrap()
                .is_empty()
        );
        assert!(
            store
                .pending_host_launch_metadata(8)
                .await
                .unwrap()
                .is_empty()
        );
        let (sent, mut received) = mpsc::channel(8);
        let status = Arc::new(AtomicU16::new(503));
        let server_status = Arc::clone(&status);
        let _server = AbortTask(host_transport::spawn(async move {
            loop {
                let (mut socket, _) = listener.accept().await.unwrap();
                let (path, body) = read_http_request(&mut socket).await;
                assert!(
                    path.ends_with("/messages"),
                    "recovery must only upload messages: {path}"
                );
                sent.send((
                    path.clone(),
                    serde_json::from_slice::<serde_json::Value>(&body).unwrap(),
                ))
                .await
                .unwrap();
                let status = server_status.load(Ordering::SeqCst);
                let status = if status == 404 && !path.ends_with("/workspace/messages") {
                    204
                } else {
                    status
                };
                if status == 0 {
                    continue;
                } // Accepted by relay, response lost.
                socket.write_all(format!("HTTP/1.1 {status} Response\r\ncontent-length: 0\r\nconnection: close\r\n\r\n").as_bytes()).await.unwrap();
            }
        }));
        let client = Client::builder()
            .timeout(Duration::from_secs(3))
            .build()
            .unwrap();
        let mut recovery_sync = JournalSync::new(false, PathBuf::new());
        recover_host_workspace_messages(
            &client,
            &config,
            store.as_ref(),
            workspace.as_ref(),
            session_id,
            &mut recovery_sync,
        )
        .await
        .unwrap();
        assert!(recovery_sync.workspace_retry_at[&direct] > Instant::now());
        let original = received.recv().await.unwrap();
        assert_eq!(original.1["text"], "final private report");
        assert_eq!(
            store
                .pending_host_workspace_messages(config.host_id, None, 8)
                .await
                .unwrap(),
            [session_id]
        );
        drop(workspace);
        drop(store);
        let store: Arc<dyn SessionStore> = Arc::new(
            PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                .await
                .unwrap(),
        );
        let workspace = store.workspace_store().await.unwrap().unwrap();
        for rejected in [0, 401] {
            status.store(rejected, Ordering::SeqCst);
            recovery_sync.workspace_retry_at.clear();
            // Simulate a prior upload whose in-memory cursor never checkpointed.
            recovery_sync.uploaded_workspace_sequences.insert(
                direct,
                original.1["metadata"]["local_workspace_sequence"]
                    .as_u64()
                    .unwrap(),
            );
            let result = recover_host_workspace_messages(
                &client,
                &config,
                store.as_ref(),
                workspace.as_ref(),
                session_id,
                &mut recovery_sync,
            )
            .await;
            if rejected == 401 {
                assert_eq!(
                    result
                        .unwrap_err()
                        .downcast_ref::<reqwest::Error>()
                        .unwrap()
                        .status(),
                    Some(StatusCode::UNAUTHORIZED)
                );
            } else {
                result.unwrap();
                assert!(recovery_sync.workspace_retry_at[&direct] > Instant::now());
            }
            assert_eq!(
                received.recv().await.unwrap(),
                original,
                "lost/rejected responses replay identical message identity and body"
            );
            assert_eq!(
                store
                    .pending_host_workspace_messages(config.host_id, None, 8)
                    .await
                    .unwrap(),
                [session_id]
            );
        }
        status.store(204, Ordering::SeqCst);
        let sessions = Arc::new(Mutex::new(HashMap::new()));
        let (tx, _rx) = mpsc::channel(1);
        sessions.lock().await.insert(session_id, tx.clone());
        let mut worker = AbortTask(host_transport::spawn(run_host_workspace_recovery_loop(
            client.clone(),
            config.clone(),
            Arc::clone(&store),
            Arc::clone(&sessions),
            PathBuf::new(),
        )));
        assert!(
            tokio::time::timeout(Duration::from_millis(200), received.recv())
                .await
                .is_err(),
            "active actors keep their own uploader"
        );
        sessions.lock().await.remove(&session_id);
        // A finished session hands its undelivered messages to recovery.
        host_transport::get(host).unwrap().wakes().recovery.notify_one();
        let active_id = Uuid::new_v4();
        sessions.lock().await.insert(active_id, tx);
        let delivered = tokio::time::timeout(Duration::from_secs(5), received.recv()).await
            .expect("stopped hosted messages must recover even when the session journal is already caught up")
            .unwrap();
        assert_eq!(delivered, original);
        tokio::time::timeout(Duration::from_secs(3), async {
            while !store
                .pending_host_workspace_messages(config.host_id, None, 8)
                .await
                .unwrap()
                .is_empty()
            {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap();
        worker.0.abort();
        let _ = (&mut worker.0).await;
        assert_eq!(
            sessions.lock().await.keys().copied().collect::<Vec<_>>(),
            [active_id]
        );
        assert_eq!(
            store.state(session_id).await.unwrap().status,
            Some(crate::SessionStatus::Stopped)
        );
        let acknowledged = store
            .host_workspace_cursors(config.host_id, session_id)
            .await
            .unwrap();
        store
            .acknowledge_host_workspaces(config.host_id, session_id, &HashMap::from([(direct, 0)]))
            .await
            .unwrap();
        assert_eq!(
            store
                .host_workspace_cursors(config.host_id, session_id)
                .await
                .unwrap(),
            acknowledged
        );
        drop(workspace);
        drop(store);
        let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
            .await
            .unwrap();
        let workspace = store.workspace_store().await.unwrap().unwrap();
        assert_eq!(
            store
                .host_workspace_cursors(config.host_id, session_id)
                .await
                .unwrap(),
            acknowledged
        );
        recovery_sync.workspace_retry_at.clear();
        recover_host_workspace_messages(
            &client,
            &config,
            &store,
            workspace.as_ref(),
            session_id,
            &mut recovery_sync,
        )
        .await
        .unwrap();
        assert!(
            received.try_recv().is_err(),
            "acknowledged output stays caught up after reopen"
        );
        let mut other_host = config.clone();
        other_host.host_id = Uuid::new_v4();
        assert!(
            store
                .pending_host_workspace_messages(other_host.host_id, None, 8)
                .await
                .unwrap()
                .is_empty()
        );
        assert!(
            store
                .host_workspace_cursors(other_host.host_id, session_id)
                .await
                .unwrap()
                .is_empty()
        );
        assert!(
            recover_host_workspace_messages(
                &client,
                &other_host,
                &store,
                workspace.as_ref(),
                session_id,
                &mut recovery_sync
            )
            .await
            .is_err()
        );
        assert!(received.try_recv().is_err());
        workspace
            .append_message(crate::NewWorkspaceMessage {
                workspace_id: binding.workspace_id,
                author_id: session_id,
                text: "final shared report".to_string(),
                mentions: Vec::new(),
                attachments: Vec::new(),
                audience: Audience::Workspace,
                mode: crate::DeliveryMode::NextTurn,
                thread_id: None,
                reply_to_message_id: None,
                idempotency_key: "shared-report".to_string(),
            })
            .await
            .unwrap();
        status.store(404, Ordering::SeqCst);
        recovery_sync.workspace_retry_at.clear();
        recover_host_workspace_messages(
            &client,
            &config,
            &store,
            workspace.as_ref(),
            session_id,
            &mut recovery_sync,
        )
        .await
        .unwrap();
        assert!(
            recovery_sync.workspace_retry_at[&binding.workspace_id]
                > Instant::now() + Duration::from_secs(290)
        );
        let shared = received.recv().await.unwrap();
        assert!(shared.0.ends_with("/workspace/messages"));
        assert_eq!(
            store
                .pending_host_workspace_messages(config.host_id, None, 8)
                .await
                .unwrap(),
            [session_id]
        );
        status.store(204, Ordering::SeqCst);
        recovery_sync.workspace_retry_at.clear();
        recover_host_workspace_messages(
            &client,
            &config,
            &store,
            workspace.as_ref(),
            session_id,
            &mut recovery_sync,
        )
        .await
        .unwrap();
        assert_eq!(received.recv().await.unwrap(), shared);
        assert!(
            store
                .pending_host_workspace_messages(config.host_id, None, 8)
                .await
                .unwrap()
                .is_empty()
        );
        // A later private message must not inherit the shared route backoff.
        let store: Arc<dyn SessionStore> = Arc::new(store);
        workspace
            .append_message(crate::NewWorkspaceMessage {
                workspace_id: binding.workspace_id,
                author_id: session_id,
                text: "shared route unavailable".to_string(),
                mentions: Vec::new(),
                attachments: Vec::new(),
                audience: Audience::Workspace,
                mode: crate::DeliveryMode::NextTurn,
                thread_id: None,
                reply_to_message_id: None,
                idempotency_key: "shared-backoff".to_string(),
            })
            .await
            .unwrap();
        let private = |text: &str| crate::NewWorkspaceMessage {
            workspace_id: direct,
            author_id: session_id,
            text: text.to_string(),
            mentions: Vec::new(),
            attachments: Vec::new(),
            audience: Audience::Direct {
                participant: recipient,
            },
            mode: crate::DeliveryMode::NextTurn,
            thread_id: None,
            reply_to_message_id: None,
            idempotency_key: text.to_string(),
        };
        workspace
            .append_message(private("before backoff"))
            .await
            .unwrap();
        status.store(404, Ordering::SeqCst);
        let mut worker = AbortTask(host_transport::spawn(run_host_workspace_recovery_loop(
            client.clone(),
            config.clone(),
            Arc::clone(&store),
            Arc::clone(&sessions),
            PathBuf::new(),
        )));
        let first = tokio::time::timeout(Duration::from_secs(5), received.recv())
            .await
            .unwrap()
            .unwrap();
        let second = tokio::time::timeout(Duration::from_secs(5), received.recv())
            .await
            .unwrap()
            .unwrap();
        let initial_private = if first.0.ends_with("/workspace/messages") {
            second
        } else {
            first
        };
        assert_eq!(initial_private.1["text"], "before backoff");
        let sequence = initial_private.1["metadata"]["local_workspace_sequence"]
            .as_u64()
            .unwrap();
        tokio::time::timeout(Duration::from_secs(3), async {
            while store
                .host_workspace_cursors(config.host_id, session_id)
                .await
                .unwrap()
                .get(&direct)
                .copied()
                .unwrap_or_default()
                < sequence
            {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap();
        workspace
            .append_message(private("during shared backoff"))
            .await
            .unwrap();
        let next = tokio::time::timeout(Duration::from_secs(5), received.recv())
            .await
            .expect("shared-workspace backoff must not defer a newly queued private message")
            .unwrap();
        assert!(
            !next.0.ends_with("/workspace/messages"),
            "shared retries must still respect their backoff"
        );
        assert_eq!(next.1["text"], "during shared backoff");
        let sequence = next.1["metadata"]["local_workspace_sequence"]
            .as_u64()
            .unwrap();
        tokio::time::timeout(Duration::from_secs(3), async {
            while store
                .host_workspace_cursors(config.host_id, session_id)
                .await
                .unwrap()
                .get(&direct)
                .copied()
                .unwrap_or_default()
                < sequence
            {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap();
        worker.0.abort();
        let _ = (&mut worker.0).await;
        assert_eq!(
            store.state(session_id).await.unwrap().status,
            Some(crate::SessionStatus::Stopped)
        );
        assert_eq!(
            sessions.lock().await.len(),
            1,
            "message recovery must not consume another actor slot"
        );
        scratch.discard().await;
    })
        .await
    }

    #[tokio::test]
    async fn expired_bootstrap_settles_offline_before_capacity() {
        let root = tempdir().unwrap();
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let mut config = test_config(root.path());
        config.server = format!("http://{}", listener.local_addr().unwrap());
        config.resource_limits.max_concurrent_sessions = 1;
        let (scratch, postgres) = crate::session_store::postgres::testing::session_store().await;
        let store: Arc<dyn SessionStore> = Arc::new(postgres);
        let [expired, locked, started, active, foreign, legacy] =
            std::array::from_fn(|_| Uuid::new_v4());
        let metadata = serde_json::to_value(PersistedLaunchMetadata {
            request: bootstrap_test_launch(root.path()),
            attachment: Some(WorkspaceAttachment {
                workspace_id: None,
                participant_id: None,
                command_authority: None,
                host_identity: None,
                host_capabilities: None,
                presence_lease: Some(crate::RemotePresenceLease {
                    lease_id: Uuid::new_v4(),
                    expires_at: Utc::now() - ChronoDuration::minutes(1),
                }),
                approval_provenance: None,
                reconnect_sync_cursors: None,
            }),
        })
        .unwrap();
        // Durable snapshots admitted before their lease expired and before host restart.
        for id in [expired, locked, started, active, foreign, legacy] {
            if id == legacy {
                store
                    .persist_host_launch_metadata(id, &metadata)
                    .await
                    .unwrap();
            } else {
                store
                    .persist_owned_host_launch_metadata(
                        id,
                        &metadata,
                        if id == foreign {
                            Uuid::new_v4()
                        } else {
                            config.host_id
                        },
                        &host_relay_origin(&config).unwrap(),
                    )
                    .await
                    .unwrap();
            }
            store.begin_host_bootstrap(id).await.unwrap();
        }
        store.create_session(started).await.unwrap();
        store
            .append(SessionEvent::new(
                started,
                0,
                crate::SessionEventKind::SessionStarted,
            ))
            .await
            .unwrap();
        let started_events = store.events_after(started, 0, 10).await.unwrap();
        let sessions = Arc::new(Mutex::new(HashMap::new()));
        let (tx, mut rx) = mpsc::channel(1);
        sessions.lock().await.insert(active, tx);
        let writer =
            SessionWriterLease::acquire(root.path().join(format!("{locked}.lock"))).unwrap();
        let executor: HostExecutorFactory =
            Arc::new(|_, _| panic!("expired bootstrap cannot execute"));
        let client = Client::builder()
            .timeout(Duration::from_secs(10))
            .build()
            .unwrap();
        tokio::time::timeout(
            Duration::from_secs(2),
            resume_pending_host_sessions(
                0,
                &client,
                &config,
                root.path(),
                &sessions,
                &host_store(&scratch).await,
                &executor,
            ),
        )
        .await
        .unwrap()
        .unwrap();
        let failed = store.events_after(expired, 0, 10).await.unwrap();
        assert_eq!(failed.len(), 1);
        assert_eq!(
            store.state(expired).await.unwrap().status,
            Some(crate::SessionStatus::Failed)
        );
        assert!(store.state(expired).await.unwrap().started_at.is_none());
        for id in [locked, active, foreign, legacy] {
            assert!(!store.contains_session(id).await.unwrap());
        }
        assert_eq!(
            serde_json::to_value(store.events_after(started, 0, 10).await.unwrap()).unwrap(),
            serde_json::to_value(started_events).unwrap()
        );
        assert!(
            dispatch(
                DispatchContext {
                    client: client.clone(),
                    config: config.clone(),
                    session_root: root.path().to_path_buf(),
                    sessions: Arc::clone(&sessions),
                    session_store: Arc::clone(&store),
                    receipts: Arc::new(receipts_on(&scratch).await),
                    executor_factory: Arc::clone(&executor),
                },
                HostCommand::Stop { session_id: active }
            )
            .await
        );
        assert!(
            matches!(rx.try_recv(), Ok(HostCommand::Stop { session_id }) if session_id == active)
        );
        drop(writer);
        drop(store);
        let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
            .await
            .unwrap();
        tokio::time::timeout(
            Duration::from_secs(2),
            resume_pending_host_sessions(
                0,
                &client,
                &config,
                root.path(),
                &sessions,
                &host_store(&scratch).await,
                &executor,
            ),
        )
        .await
        .unwrap()
        .unwrap();
        assert_eq!(
            store.state(locked).await.unwrap().status,
            Some(crate::SessionStatus::Failed)
        );
        assert_eq!(
            serde_json::to_value(store.events_after(expired, 0, 10).await.unwrap()).unwrap(),
            serde_json::to_value(failed).unwrap()
        );
        let pending: HashSet<_> = store
            .pending_host_launch_metadata(10)
            .await
            .unwrap()
            .into_iter()
            .map(|(id, _)| id)
            .collect();
        assert_eq!(pending, HashSet::from([started, active, foreign, legacy]));
        for id in [expired, locked, started, active, foreign, legacy] {
            assert_eq!(
                store.load_host_launch_metadata(id).await.unwrap(),
                Some(metadata.clone())
            );
        }
        assert!(
            tokio::time::timeout(Duration::from_millis(50), listener.accept())
                .await
                .is_err(),
            "local bootstrap settlement must not probe or publish to the relay"
        );
        let unpublished = store.pending_host_journals(None, 10).await.unwrap();
        assert!(
            unpublished.contains(&expired) && unpublished.contains(&locked),
            "journal recovery must discover failures after bootstrap markers are removed"
        );
        scratch.discard().await;
    }

    #[tokio::test]
    async fn acknowledged_bootstrap_failure_replays_after_restart_without_execution() {
        let host = Uuid::new_v4();
        with_test_transport(host, |_frames| async move {
        let root = tempdir().unwrap();
        let session_id = Uuid::new_v4();
        let launch = bootstrap_test_launch(root.path());
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let mut config = test_config_for(root.path(), host);
        config.server = format!("http://{}", listener.local_addr().unwrap());
        let (context_seen_tx, context_seen_rx) = tokio::sync::oneshot::channel();
        let (release_tx, release_rx) = tokio::sync::oneshot::channel();
        let server = host_transport::spawn(async move {
            let (mut stream, _) = listener.accept().await.unwrap();
            let (path, _) = read_http_request(&mut stream).await;
            assert_eq!(
                path,
                format!("/api/remote/host/sessions/{session_id}/runtime-context")
            );
            context_seen_tx.send(()).unwrap();
            release_rx.await.unwrap();
            stream.write_all(b"HTTP/1.1 503 Service Unavailable\r\ncontent-length: 0\r\nconnection: close\r\n\r\n").await.unwrap();
        });
        let (scratch, postgres) = crate::session_store::postgres::testing::session_store().await;
        let store: Arc<dyn SessionStore> = Arc::new(postgres);
        let sessions = Arc::new(Mutex::new(HashMap::new()));
        let executor: HostExecutorFactory =
            Arc::new(|_, _| panic!("failed bootstrap must never execute"));
        let client = Client::builder()
            .timeout(Duration::from_secs(5))
            .build()
            .unwrap();
        assert!(
            dispatch(
                DispatchContext {
                    client: client.clone(),
                    config: config.clone(),
                    session_root: root.path().to_path_buf(),
                    sessions: Arc::clone(&sessions),
                    session_store: Arc::clone(&store),
                    receipts: Arc::new(receipts_on(&scratch).await),
                    executor_factory: Arc::clone(&executor),
                },
                HostCommand::Launch {
                    session_id,
                    request: Box::new(launch.clone()),
                    attachment: None,
                }
            )
            .await
        );
        tokio::time::timeout(Duration::from_secs(5), context_seen_rx)
            .await
            .unwrap()
            .unwrap();
        assert!(!store.contains_session(session_id).await.unwrap());
        assert_eq!(
            store.pending_host_launch_metadata(8).await.unwrap()[0].0,
            session_id,
            "acknowledged launch must be recoverable before any session/action exists"
        );
        release_tx.send(()).unwrap();
        tokio::time::timeout(Duration::from_secs(10), async {
            while sessions.lock().await.contains_key(&session_id) {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap();
        let failed = store.events_after(session_id, 0, 10).await.unwrap();
        assert_eq!(failed.len(), 1);
        assert_eq!(
            store.state(session_id).await.unwrap().status,
            Some(crate::SessionStatus::Failed)
        );
        // Rejection settles locally; the tunnel publishes the journal.
        assert!(
            store
                .pending_host_launch_metadata(8)
                .await
                .unwrap()
                .is_empty()
        );
        drop(store);
        let store: Arc<dyn SessionStore> = Arc::new(
            PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                .await
                .unwrap(),
        );
        resume_pending_host_sessions(
            0,
            &client,
            &config,
            root.path(),
            &sessions,
            &host_store(&scratch).await,
            &executor,
        )
        .await
        .unwrap();
        assert!(
            store
                .pending_host_launch_metadata(8)
                .await
                .unwrap()
                .is_empty()
        );
        assert!(sessions.lock().await.is_empty());
        assert_eq!(
            serde_json::to_value(store.events_after(session_id, 0, 10).await.unwrap()).unwrap(),
            serde_json::to_value(failed).unwrap()
        );
        // A settled launch replays as acknowledged without executing again.
        assert!(
            dispatch(
                DispatchContext {
                    client: client.clone(),
                    config: config.clone(),
                    session_root: root.path().to_path_buf(),
                    sessions: Arc::clone(&sessions),
                    session_store: Arc::clone(&store),
                    receipts: Arc::new(receipts_on(&scratch).await),
                    executor_factory: Arc::clone(&executor),
                },
                HostCommand::Launch {
                    session_id,
                    request: Box::new(launch),
                    attachment: None
                }
            )
            .await
        );
        assert!(
            store
                .pending_host_journals(None, 8)
                .await
                .unwrap()
                .contains(&session_id)
        );
        server.await.unwrap();
        scratch.discard().await;
    })
        .await
    }

    #[tokio::test]
    async fn bootstrap_upgrade_and_handoff_preserve_initial_prompt_recovery() {
        let root = tempdir().unwrap();
        let mut config = test_config(root.path());
        config.resource_limits.max_concurrent_sessions = 1;
        let session_id = Uuid::new_v4();
        let launch = bootstrap_test_launch(root.path());
        let (scratch, store) = crate::session_store::postgres::testing::session_store().await;
        persist_launch_metadata(&config, &store, session_id, &launch, None)
            .await
            .unwrap();
        // Simulate the previous current schema: additive upgrade must preserve metadata.
        sqlx::query("drop table host_journal_cursors")
            .execute(store.pool())
            .await
            .unwrap();
        sqlx::query("drop table host_bootstraps")
            .execute(store.pool())
            .await
            .unwrap();
        // Part of the simulation, not a workaround: a database that predates
        // this schema has not recorded it either. `ensure_schema` returns
        // early when the stored fingerprint matches the current one, so
        // dropping a table alone leaves a database that still claims to be
        // current and therefore never acquires the table back.
        sqlx::query("update borg_session_schema set definition_hash = null")
            .execute(store.pool())
            .await
            .unwrap();
        drop(store);
        let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
            .await
            .unwrap();
        store.begin_host_bootstrap(session_id).await.unwrap();
        drop(store);
        let store = PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
            .await
            .unwrap();
        assert_eq!(
            store.pending_host_launch_metadata(8).await.unwrap()[0].0,
            session_id
        );
        store.create_session(session_id).await.unwrap();
        for kind in [
            crate::SessionEventKind::SessionStarted,
            crate::SessionEventKind::SessionConfigured {
                cwd: launch.cwd.clone(),
                provider: launch.provider,
                model: None,
                effort: None,
                fast: false,
                ultrafast: false,
                response_language: launch.response_language,
                permission_mode: launch.permission_mode,
                speed_support: Default::default(),
            },
        ] {
            store
                .append(SessionEvent::new(session_id, 0, kind))
                .await
                .unwrap();
        }
        assert!(
            !finish_ready_host_bootstrap(&store, session_id, Some(launch.request_id))
                .await
                .unwrap(),
            "started/configured alone does not prove initial prompt admission"
        );
        admit_remote_prompt(
            &store,
            session_id,
            launch.request_id,
            launch.initial_prompt.as_deref().unwrap(),
            &[],
            crate::PromptDelivery::Steer,
        )
        .await
        .unwrap();
        assert!(
            finish_ready_host_bootstrap(&store, session_id, Some(launch.request_id))
                .await
                .unwrap()
        );
        let markers: i64 = sqlx::query_scalar("select count(*) from host_bootstraps")
            .fetch_one(store.pool())
            .await
            .unwrap();
        assert_eq!(markers, 0);
        assert_eq!(
            store.pending_host_launch_metadata(8).await.unwrap()[0].0,
            session_id,
            "durable action takes over recovery after bootstrap marker is removed"
        );

        let stopped_id = Uuid::new_v4();
        persist_launch_metadata(&config, &store, stopped_id, &launch, None)
            .await
            .unwrap();
        store.begin_host_bootstrap(stopped_id).await.unwrap();
        store.create_session(stopped_id).await.unwrap();
        for kind in [
            crate::SessionEventKind::SessionStarted,
            crate::SessionEventKind::StatusChanged {
                lifecycle: Some(crate::SessionStatus::Stopped.into()),
                status: crate::SessionStatus::Stopped,
                detail: None,
            },
        ] {
            store
                .append(SessionEvent::new(stopped_id, 0, kind))
                .await
                .unwrap();
        }
        // Keep the other recoverable prompt assigned while checking stopped bootstrap recovery.
        let sessions = Arc::new(Mutex::new(HashMap::new()));
        let (tx, _rx) = mpsc::channel(1);
        sessions.lock().await.insert(session_id, tx);
        let executor: HostExecutorFactory =
            Arc::new(|_, _| panic!("stopped bootstrap must not restart"));
        resume_pending_host_sessions(
            0,
            &Client::new(),
            &config,
            root.path(),
            &sessions,
            &host_store(&scratch).await,
            &executor,
        )
        .await
        .unwrap();
        assert!(!sessions.lock().await.contains_key(&stopped_id));
        assert!(
            store
                .pending_host_launch_metadata(8)
                .await
                .unwrap()
                .iter()
                .all(|(id, _)| *id != stopped_id)
        );
        scratch.discard().await;
    }

    #[tokio::test]
    async fn rejected_launch_is_durable_replayable_and_does_not_block_stop() {
        let host = Uuid::new_v4();
        with_test_transport(host, |_frames| async move {
        for rejection in ["capacity", "oversized", "malformed", "expired"] {
            let oversized = rejection == "oversized";
            let root = tempdir().unwrap();
            let mut config = test_config_for(root.path(), host);
            config.resource_limits.max_concurrent_sessions = 1;
            let session_id = Uuid::new_v4();
            let active_id = Uuid::new_v4();
            let launch = LaunchSession {
                request_id: Uuid::new_v4(),
                cwd: root.path().to_path_buf(),
                provider: CodingProvider::Codex,
                model: None,
                effort: None,
                fast: Some(false),
                ultrafast: None,
                response_language: crate::ResponseLanguage::Auto,
                permission_mode: crate::PermissionMode::Manual,
                name: None,
                initial_prompt: Some(if oversized {
                    "x".repeat(512 * 1024)
                } else {
                    "must not run after rejection".to_string()
                }),
                capabilities: Default::default(),
                subagent_concurrency_limit: None,
                extension_skill_roots: Vec::new(),
                team_policy: None,
            };
            let attachment = match rejection {
                "malformed" | "expired" => Some(WorkspaceAttachment {
                    workspace_id: Some(Uuid::new_v4()),
                    participant_id: (rejection != "malformed").then_some(session_id),
                    command_authority: None,
                    host_identity: None,
                    host_capabilities: None,
                    presence_lease: Some(crate::RemotePresenceLease {
                        lease_id: Uuid::new_v4(),
                        expires_at: Utc::now() - ChronoDuration::minutes(1),
                    }),
                    approval_provenance: None,
                    reconnect_sync_cursors: None,
                }),
                _ => None,
            };
            let (scratch, postgres) =
                crate::session_store::postgres::testing::session_store().await;
            let session_store: Arc<dyn SessionStore> = Arc::new(postgres);
            let sessions = Arc::new(Mutex::new(HashMap::new()));
            let (active_tx, mut active_rx) = mpsc::channel(1);
            sessions.lock().await.insert(active_id, active_tx);
            let receipts: Arc<dyn ReceiptBackend> = Arc::new(receipts_on(&scratch).await);
            let context = |store: &Arc<dyn SessionStore>| DispatchContext {
                client: Client::new(),
                config: config.clone(),
                session_root: root.path().to_path_buf(),
                sessions: Arc::clone(&sessions),
                session_store: Arc::clone(store),
                receipts: Arc::clone(&receipts),
                executor_factory: Arc::new(|_, _| panic!("rejected launch must not execute")),
            };
            if rejection == "expired" {
                let mut foreign_attachment = attachment.clone().unwrap();
                foreign_attachment.host_identity = Some(RemoteHostIdentity {
                    host_id: Uuid::new_v4(),
                    hostname: "other".into(),
                    platform: "test".into(),
                });
                let foreign_id = Uuid::new_v4();
                assert!(
                    !dispatch(
                        context(&session_store),
                        HostCommand::Launch {
                            session_id: foreign_id,
                            request: Box::new(launch.clone()),
                            attachment: Some(foreign_attachment),
                        }
                    )
                    .await
                );
                assert!(
                    session_store
                        .load_host_launch_metadata(foreign_id)
                        .await
                        .unwrap()
                        .is_none()
                );
                assert!(
                    session_store
                        .host_launch_owner(foreign_id)
                        .await
                        .unwrap()
                        .is_none()
                );
                assert!(!session_store.contains_session(foreign_id).await.unwrap());

                // A lease can expire after executable metadata and an actor were admitted.
                let admitted_id = Uuid::new_v4();
                let admitted = serde_json::to_value(PersistedLaunchMetadata {
                    request: launch.clone(),
                    attachment: attachment.clone(),
                })
                .unwrap();
                session_store
                    .persist_owned_host_launch_metadata(
                        admitted_id,
                        &admitted,
                        config.host_id,
                        &host_relay_origin(&config).unwrap(),
                    )
                    .await
                    .unwrap();
                session_store.create_session(admitted_id).await.unwrap();
                session_store
                    .append(SessionEvent::new(
                        admitted_id,
                        0,
                        crate::SessionEventKind::SessionStarted,
                    ))
                    .await
                    .unwrap();
                let (tx, _rx) = mpsc::channel(1);
                sessions.lock().await.insert(admitted_id, tx);
                assert!(
                    dispatch(
                        context(&session_store),
                        HostCommand::Launch {
                            session_id: admitted_id,
                            request: Box::new(launch.clone()),
                            attachment: attachment.clone(),
                        }
                    )
                    .await,
                    "exact replay cannot invalidate an already-admitted actor"
                );
                sessions.lock().await.remove(&admitted_id);
                assert!(
                    !dispatch(
                        context(&session_store),
                        HostCommand::Prompt {
                            session_id: admitted_id,
                            message_id: Uuid::new_v4(),
                            text: "expired".into(),
                            attachments: vec![],
                            output_schema: None,
                            delivery: crate::PromptDelivery::Queue,
                        }
                    )
                    .await,
                    "an expired lease must not authorize actor restoration"
                );
                assert!(
                    dispatch(
                        context(&session_store),
                        HostCommand::Stop {
                            session_id: admitted_id
                        }
                    )
                    .await
                );
                assert_eq!(
                    session_store.state(admitted_id).await.unwrap().status,
                    Some(crate::SessionStatus::Stopped)
                );
                assert_eq!(
                    session_store
                        .load_host_launch_metadata(admitted_id)
                        .await
                        .unwrap(),
                    Some(admitted)
                );

                // Snapshot a rejected lease that appears valid after the wall clock moves back.
                let rejected_id = Uuid::new_v4();
                let mut future_attachment = attachment.clone().unwrap();
                future_attachment
                    .presence_lease
                    .as_mut()
                    .unwrap()
                    .expires_at = Utc::now() + ChronoDuration::hours(1);
                let original = serde_json::to_value(PersistedLaunchMetadata {
                    request: launch.clone(),
                    attachment: Some(future_attachment.clone()),
                })
                .unwrap();
                let fingerprint: [u8; 32] =
                    Sha256::digest(serde_json::to_vec(&original).unwrap()).into();
                let rejected = serde_json::to_value(StoredHostLaunch::Rejected {
                    rejected_launch: RejectedHostLaunch {
                        metadata_sha256: fingerprint,
                        reason: "workspace presence lease has expired".into(),
                    },
                })
                .unwrap();
                session_store
                    .persist_owned_host_launch_metadata(
                        rejected_id,
                        &rejected,
                        config.host_id,
                        &host_relay_origin(&config).unwrap(),
                    )
                    .await
                    .unwrap();
                assert_eq!(
                    persist_launch_metadata(
                        &config,
                        session_store.as_ref(),
                        rejected_id,
                        &launch,
                        Some(&future_attachment)
                    )
                    .await
                    .unwrap(),
                    Some("workspace presence lease has expired".into())
                );
                assert_eq!(
                    session_store
                        .load_host_launch_metadata(rejected_id)
                        .await
                        .unwrap(),
                    Some(rejected)
                );
                assert!(!session_store.contains_session(rejected_id).await.unwrap());
            }
            let launch_command = || HostCommand::Launch {
                session_id,
                request: Box::new(launch.clone()),
                attachment: attachment.clone(),
            };
            if oversized {
                assert!(
                    persist_launch_metadata(
                        &config,
                        session_store.as_ref(),
                        session_id,
                        &launch,
                        None
                    )
                    .await
                    .unwrap()
                    .is_some()
                );
                assert!(!dispatch(context(&session_store), HostCommand::Stop { session_id }).await);
                assert!(!session_store.contains_session(session_id).await.unwrap());
            }
            // Restart after metadata admission but before the failure journal exists.
            drop(session_store);
            let session_store: Arc<dyn SessionStore> = Arc::new(
                PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                    .await
                    .unwrap(),
            );
            assert!(
                dispatch(context(&session_store), launch_command()).await,
                "a locally durable rejection acknowledges the relay command"
            );
            let failure = session_store.events_after(session_id, 0, 10).await.unwrap();
            assert_eq!(failure.len(), 1);
            assert!(matches!(
                &failure[0].kind,
                crate::SessionEventKind::StatusChanged {
                    status: crate::SessionStatus::Failed,
                    detail: Some(_),

                    ..
                }
            ));
            let saved = session_store
                .load_host_launch_metadata(session_id)
                .await
                .unwrap()
                .unwrap();
            assert!(
                serde_json::to_vec(&saved).unwrap().len()
                    <= crate::session_store::MAX_HOST_LAUNCH_METADATA_BYTES
            );
            for initial_prompt in [
                Some("a smaller conflicting request".to_string()),
                Some("y".repeat(512 * 1024)),
            ] {
                let mut changed = launch.clone();
                changed.initial_prompt = initial_prompt;
                assert!(
                    persist_launch_metadata(
                        &config,
                        session_store.as_ref(),
                        session_id,
                        &changed,
                        attachment.as_ref()
                    )
                    .await
                    .is_err(),
                    "different launch cannot overwrite admitted identity"
                );
            }
            let mut foreign = config.clone();
            foreign.host_id = Uuid::new_v4();
            assert!(
                !dispatch(
                    DispatchContext {
                        config: foreign,
                        ..context(&session_store)
                    },
                    launch_command()
                )
                .await
            );
            let mut foreign = config.clone();
            foreign.server = "http://127.0.0.1:1".to_string();
            assert!(
                !dispatch(
                    DispatchContext {
                        config: foreign,
                        ..context(&session_store)
                    },
                    launch_command()
                )
                .await
            );
            assert_eq!(
                session_store
                    .load_host_launch_metadata(session_id)
                    .await
                    .unwrap(),
                Some(saved)
            );
            // Failed publication must survive process restart with exactly the same journal.
            drop(session_store);
            let session_store: Arc<dyn SessionStore> = Arc::new(
                PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                    .await
                    .unwrap(),
            );
            assert!(dispatch(context(&session_store), launch_command()).await);
            assert!(
                dispatch(
                    context(&session_store),
                    HostCommand::Stop {
                        session_id: active_id
                    }
                )
                .await
            );
            assert!(
                matches!(active_rx.try_recv(), Ok(HostCommand::Stop { session_id }) if session_id == active_id)
            );
            sessions.lock().await.clear();
            drop(session_store);

            // Reopen the durable journal after the slot is free: rejection must not
            // turn into a deferred launch or accept a new prompt into an actor.
            let session_store: Arc<dyn SessionStore> = Arc::new(
                PostgresSessionStore::connect_with_pool_size(&scratch.url, 2)
                    .await
                    .unwrap(),
            );
            assert!(dispatch(context(&session_store), launch_command()).await);
            assert!(
                dispatch(
                    context(&session_store),
                    HostCommand::Prompt {
                        session_id,
                        message_id: Uuid::new_v4(),
                        text: "already queued before failure reached relay".to_string(),
                        attachments: Vec::new(),
                        output_schema: None,
                        delivery: crate::PromptDelivery::Queue,
                    }
                )
                .await
            );
            let replay = session_store.events_after(session_id, 0, 10).await.unwrap();
            assert_eq!(
                serde_json::to_value(&replay).unwrap(),
                serde_json::to_value(&failure).unwrap()
            );
            assert!(sessions.lock().await.is_empty());

            let invalid_id = Uuid::new_v4();
            let mut invalid_launch = launch.clone();
            invalid_launch.request_id = Uuid::new_v4();
            invalid_launch.cwd = root.path().join("does-not-exist");
            assert!(
                dispatch(
                    context(&session_store),
                    HostCommand::Launch {
                        session_id: invalid_id,
                        request: Box::new(invalid_launch),
                        attachment: None,
                    }
                )
                .await
            );
            let state = session_store.state(invalid_id).await.unwrap();
            assert_eq!(state.status, Some(crate::SessionStatus::Failed));
            assert!(state.started_at.is_none());
            assert!(sessions.lock().await.is_empty());
            scratch.discard().await;
        }
    })
        .await
    }

    #[tokio::test]
    async fn undeliverable_remote_prompt_is_durable_and_unacknowledged() {
        let root = tempdir().unwrap();
        let config = test_config(root.path());
        let session_id = Uuid::new_v4();
        let message_id = Uuid::new_v4();
        let launch = LaunchSession {
            request_id: Uuid::new_v4(),
            cwd: root.path().to_path_buf(),
            provider: CodingProvider::Codex,
            model: None,
            effort: None,
            fast: Some(false),
            ultrafast: None,
            response_language: crate::ResponseLanguage::Auto,
            permission_mode: crate::PermissionMode::Manual,
            name: None,
            initial_prompt: None,
            capabilities: Default::default(),
            subagent_concurrency_limit: None,
            extension_skill_roots: Vec::new(),
            team_policy: None,
        };
        let (scratch, postgres) = crate::session_store::postgres::testing::session_store().await;
        let session_store: Arc<dyn SessionStore> = Arc::new(postgres);
        session_store.create_session(session_id).await.unwrap();
        for kind in [
            crate::SessionEventKind::SessionStarted,
            crate::SessionEventKind::SessionConfigured {
                cwd: root.path().to_path_buf(),
                provider: CodingProvider::Codex,
                model: None,
                effort: None,
                fast: false,
                ultrafast: false,
                response_language: crate::ResponseLanguage::Auto,
                permission_mode: crate::PermissionMode::Manual,
                speed_support: Default::default(),
            },
        ] {
            session_store
                .append(SessionEvent::new(session_id, 0, kind))
                .await
                .unwrap();
        }
        persist_launch_metadata(&config, session_store.as_ref(), session_id, &launch, None)
            .await
            .unwrap();
        let sessions = Arc::new(Mutex::new(HashMap::new()));
        let (dead_sender, dead_receiver) = mpsc::channel(1);
        drop(dead_receiver);
        sessions.lock().await.insert(session_id, dead_sender);

        let handled = dispatch(
            DispatchContext {
                client: Client::new(),
                config,
                session_root: root.path().to_path_buf(),
                sessions,
                session_store: Arc::clone(&session_store),
                receipts: Arc::new(receipts_on(&scratch).await),
                executor_factory: default_host_executor_factory(),
            },
            HostCommand::Prompt {
                session_id,
                message_id,
                text: "survive the actor crash".to_string(),
                attachments: Vec::new(),
                output_schema: None,
                delivery: crate::PromptDelivery::Queue,
            },
        )
        .await;

        assert!(!handled, "the relay must retry an undelivered command");
        assert!(
            session_store
                .contains_message(session_id, message_id)
                .await
                .unwrap()
        );
        assert_eq!(
            session_store
                .pending_host_launch_metadata(8)
                .await
                .unwrap()
                .into_iter()
                .map(|(id, _)| id)
                .collect::<Vec<_>>(),
            [session_id]
        );
        scratch.discard().await;
    }

