    #[tokio::test]
    async fn started_filesystem_mutation_is_not_replayed() {
        let root = tempdir().unwrap();
        let target = root.path().join("keep.txt");
        fs::write(&target, "still here").unwrap();
        let request = WorkspaceFilesystemRequest {
            request_id: Uuid::new_v4(),
            workspace_id: Uuid::new_v4(),
            root_path: root.path().to_path_buf(),
            timeout_ms: 1_000,
            operation: WorkspaceFilesystemOperation::Delete {
                path: PathBuf::from("keep.txt"),
                archive: false,
                recursive: false,
            },
        };
        // The session store owns schema bootstrap for the whole database,
        // including the receipt tier this test writes to.
        let (scratch, _store) = crate::session_store::postgres::testing::session_store().await;
        let receipts: Arc<dyn ReceiptBackend> = Arc::new(receipts_on(&scratch).await);
        receipts.begin(request.request_id, &request).await.unwrap();

        let response = filesystem_response(receipts.as_ref(), &test_config(root.path()), &request)
            .await
            .unwrap();

        assert!(target.exists(), "indeterminate delete must not be replayed");
        assert!(matches!(
            response.outcome,
            WorkspaceFilesystemOutcome::Failure {
                code: WorkspaceFilesystemErrorCode::Indeterminate,
                retryable: false,
                ..
            }
        ));
        assert!(matches!(
            receipts
                .load::<_, WorkspaceFilesystemResponse>(request.request_id, &request)
                .await
                .unwrap(),
            ReceiptState::Terminal(_)
        ));
        scratch.discard().await;
    }

